import { createContext, useContext } from "react";
import type { AccordionContextValue } from "./Accordion.types";

export const AccordionContext = createContext<AccordionContextValue | null>(
  null,
);

export function useAccordion(): AccordionContextValue {
  const ctx = useContext(AccordionContext);
  if (!ctx) {
    throw new Error(
      "Accordion compound components must be used within <Accordion>",
    );
  }
  return ctx;
}

export const AccordionItemContext = createContext<string>("");

export function useAccordionItem(): string {
  return useContext(AccordionItemContext);
}

import { useCallback, useMemo, useState } from "react";
import { cn } from "../../utils/cn";
import { AccordionContext } from "./Accordion.context";
import { AccordionItem } from "./AccordionItem";
import { AccordionTrigger } from "./AccordionTrigger";
import { AccordionContent } from "./AccordionContent";
import type { AccordionProps } from "./Accordion.types";

function AccordionRoot({
  children,
  type = "single",
  defaultOpen = [],
  className,
}: AccordionProps) {
  const [openItems, setOpenItems] = useState<string[]>(defaultOpen);
  const multiple = type === "multiple";

  const toggle = useCallback(
    (value: string) => {
      setOpenItems((prev) => {
        if (prev.includes(value)) {
          return prev.filter((v) => v !== value);
        }
        return multiple ? [...prev, value] : [value];
      });
    },
    [multiple],
  );

  const ctx = useMemo(
    () => ({ openItems, toggle, multiple }),
    [openItems, toggle, multiple],
  );

  return (
    <AccordionContext.Provider value={ctx}>
      <div data-react-fancy-accordion="" className={cn(className)}>{children}</div>
    </AccordionContext.Provider>
  );
}

export const Accordion = Object.assign(AccordionRoot, {
  Item: AccordionItem,
  Trigger: AccordionTrigger,
  Content: AccordionContent,
});

import type { ReactNode } from "react";

export interface AccordionContextValue {
  openItems: string[];
  toggle: (value: string) => void;
  multiple: boolean;
}

export interface AccordionProps {
  children: ReactNode;
  type?: "single" | "multiple";
  defaultOpen?: string[];
  className?: string;
}

export interface AccordionItemProps {
  children: ReactNode;
  value: string;
  className?: string;
}

export interface AccordionTriggerProps {
  children: ReactNode;
  className?: string;
}

export interface AccordionContentProps {
  children: ReactNode;
  className?: string;
}

import { cn } from "../../utils/cn";
import { useAccordion, useAccordionItem } from "./Accordion.context";
import type { AccordionContentProps } from "./Accordion.types";

export function AccordionContent({
  children,
  className,
}: AccordionContentProps) {
  const { openItems } = useAccordion();
  const value = useAccordionItem();
  const isOpen = openItems.includes(value);

  return (
    <div
      data-react-fancy-accordion-content=""
      className={cn(
        "grid transition-all duration-200",
        isOpen ? "grid-rows-[1fr]" : "grid-rows-[0fr]",
      )}
    >
      <div className="overflow-hidden">
        <div className={cn("pb-4 text-sm text-zinc-600 dark:text-zinc-400", className)}>
          {children}
        </div>
      </div>
    </div>
  );
}

AccordionContent.displayName = "AccordionContent";

import { cn } from "../../utils/cn";
import { AccordionItemContext } from "./Accordion.context";
import type { AccordionItemProps } from "./Accordion.types";

export function AccordionItem({
  children,
  value,
  className,
}: AccordionItemProps) {
  return (
    <AccordionItemContext.Provider value={value}>
      <div
        data-react-fancy-accordion-item=""
        className={cn(
          "border-b border-zinc-200 dark:border-zinc-700",
          className,
        )}
      >
        {children}
      </div>
    </AccordionItemContext.Provider>
  );
}

AccordionItem.displayName = "AccordionItem";

import { ChevronDown } from "lucide-react";
import { cn } from "../../utils/cn";
import { useAccordion, useAccordionItem } from "./Accordion.context";
import type { AccordionTriggerProps } from "./Accordion.types";

export function AccordionTrigger({
  children,
  className,
}: AccordionTriggerProps) {
  const { openItems, toggle } = useAccordion();
  const value = useAccordionItem();
  const isOpen = openItems.includes(value);

  return (
    <button
      data-react-fancy-accordion-trigger=""
      type="button"
      onClick={() => toggle(value)}
      aria-expanded={isOpen}
      className={cn(
        "flex w-full items-center justify-between py-4 text-left text-sm font-medium transition-colors hover:text-zinc-600 dark:hover:text-zinc-300",
        className,
      )}
    >
      {children}
      <ChevronDown size={16} className={cn("shrink-0 transition-transform duration-200", isOpen && "rotate-180")} />
    </button>
  );
}

AccordionTrigger.displayName = "AccordionTrigger";

export { Accordion } from "./Accordion";
export { useAccordion } from "./Accordion.context";
export type {
  AccordionProps,
  AccordionItemProps,
  AccordionTriggerProps,
  AccordionContentProps,
  AccordionContextValue,
} from "./Accordion.types";

import type { ReactNode } from "react";
import { cn } from "../../utils/cn";
import { useAccordionSection } from "./AccordionPanel.context";

export interface AccordionPanelContentProps {
  children: ReactNode;
  className?: string;
  /**
   * Skip the default flex-row/flex-col + items-center + gap classes so the
   * consumer can lay out the open-state content however they want (e.g. a
   * full-height chat panel with header/scroll/input rows). The
   * `data-react-fancy-accordion-content` attribute and conditional render
   * (only when the section is open) are kept.
   */
  unstyled?: boolean;
}

/**
 * Wrapper for the open-state content of a Section. Renders its children
 * only when the parent Section is open; returns `null` otherwise.
 *
 * Use this so siblings of `<AccordionPanel.Trigger>` inside a section can
 * cleanly toggle in/out of the DOM.
 *
 * The default styling assumes an inline cluster — flex row (horizontal
 * orientation) or column (vertical), centered, with a small gap. For panel
 * use cases where the content needs full-bleed layout (chat panes, canvas
 * surfaces, etc.), pass `unstyled` and supply your own className.
 */
export function AccordionPanelContent({
  children,
  className,
  unstyled,
}: AccordionPanelContentProps) {
  const { open, orientation } = useAccordionSection();
  if (!open) return null;

  return (
    <div
      data-react-fancy-accordion-content=""
      data-orientation={orientation}
      className={cn(
        !unstyled && "flex items-center gap-1",
        !unstyled && (orientation === "horizontal" ? "flex-row" : "flex-col"),
        className,
      )}
    >
      {children}
    </div>
  );
}

AccordionPanelContent.displayName = "AccordionPanelContent";

import { useEffect, useMemo } from "react";
import { cn } from "../../utils/cn";
import {
  AccordionSectionContext,
  useAccordionPanel,
} from "./AccordionPanel.context";
import type { AccordionPanelSectionProps } from "./AccordionPanel.types";

/**
 * One collapsible section inside an AccordionPanel.
 *
 * Compose with `<AccordionPanel.Trigger>` and `<AccordionPanel.Content>`
 * children — Content renders only when open, Trigger always renders and
 * adapts its look by state. Children that are not Trigger/Content are
 * rendered as-is, regardless of state, so static decorations stay put.
 *
 * Pinned sections never collapse and don't need a Trigger.
 */
export function AccordionPanelSection({
  id,
  pinned = false,
  className,
  openClassName,
  closedClassName,
  unstyled,
  children,
}: AccordionPanelSectionProps) {
  const panel = useAccordionPanel();
  const { orientation, isOpen, toggle, registerSection } = panel;

  useEffect(() => registerSection(id), [id, registerSection]);

  const open = pinned || isOpen(id);

  const sectionCtx = useMemo(
    () => ({
      id,
      open,
      pinned,
      orientation,
      toggle: () => toggle(id),
    }),
    [id, open, pinned, orientation, toggle],
  );

  return (
    <AccordionSectionContext.Provider value={sectionCtx}>
      <div
        data-react-fancy-accordion-section=""
        data-state={open ? "open" : "closed"}
        data-pinned={pinned ? "" : undefined}
        data-orientation={orientation}
        className={cn(
          "flex shrink-0",
          !unstyled && "items-center gap-1",
          orientation === "horizontal" ? "flex-row" : "flex-col",
          className,
          open ? openClassName : closedClassName,
        )}
      >
        {children}
      </div>
    </AccordionSectionContext.Provider>
  );
}

AccordionPanelSection.displayName = "AccordionPanelSection";

import { cn } from "../../utils/cn";
import { useAccordionSection } from "./AccordionPanel.context";
import type {
  AccordionPanelTriggerProps,
  SectionRenderable,
  SectionRenderState,
} from "./AccordionPanel.types";

function renderSlot(slot: SectionRenderable, state: SectionRenderState) {
  return typeof slot === "function" ? slot(state) : slot;
}

/**
 * Trigger for an AccordionPanel.Section.
 *
 * Has two visual roles, picked automatically from section state:
 *
 *   - When the section is OPEN: renders as a thin divider on the section's
 *     trailing edge. Hovering reveals an inset chevron pointing toward the
 *     section so the user knows clicking will collapse it.
 *
 *   - When the section is CLOSED: renders as a standalone chevron button
 *     in place of the section content. Clicking re-expands the section.
 *
 * Supply `children` (node or render-prop) to fully replace the default
 * rendering. The render-prop receives `{ open, toggle, orientation, id }`.
 */
export function AccordionPanelTrigger({
  children,
  className,
  "aria-label": ariaLabel,
}: AccordionPanelTriggerProps) {
  const { id, open, orientation, toggle } = useAccordionSection();
  const state: SectionRenderState = { id, open, orientation, toggle };

  // Custom render path — caller is in charge of look & feel.
  if (children !== undefined) {
    return (
      <div
        data-react-fancy-accordion-trigger=""
        data-state={open ? "open" : "closed"}
        data-orientation={orientation}
        className={className}
      >
        {renderSlot(children, state)}
      </div>
    );
  }

  // Default rendering ----------------------------------------------------

  if (open) {
    // Trailing-edge divider. The visible line is 1px (rendered via the
    // ::before pseudo-element so it stays narrow); the button's actual
    // hitbox is much wider (w-3 / h-3 = 12px) so users don't have to land
    // pixel-perfect on the line. Hovering the hitbox highlights the line
    // and reveals an inset chevron signalling "click to collapse".
    return (
      <button
        type="button"
        onClick={toggle}
        aria-label={ariaLabel ?? "Collapse section"}
        data-react-fancy-accordion-trigger=""
        data-state="open"
        data-orientation={orientation}
        className={cn(
          "group relative flex shrink-0 items-center justify-center cursor-pointer",
          "text-zinc-500 dark:text-zinc-500",
          "hover:text-zinc-900 dark:hover:text-zinc-100",
          // Wide hitbox + thin visible line (drawn via ::before).
          orientation === "horizontal"
            ? "w-3 self-stretch"
            : "h-3 self-stretch",
          "before:absolute before:bg-zinc-200 dark:before:bg-zinc-700",
          "before:transition-colors group-hover:before:bg-zinc-400 dark:group-hover:before:bg-zinc-500",
          orientation === "horizontal"
            ? "before:top-0 before:bottom-0 before:w-px before:left-1/2 before:-translate-x-1/2"
            : "before:left-0 before:right-0 before:h-px before:top-1/2 before:-translate-y-1/2",
          "transition-colors",
          className,
        )}
      >
        <ChevronIcon
          orientation={orientation}
          purpose="collapse"
          className="relative opacity-0 group-hover:opacity-100 transition-opacity"
        />
      </button>
    );
  }

  // Closed: standalone chevron button. Click to re-expand.
  return (
    <button
      type="button"
      onClick={toggle}
      aria-label={ariaLabel ?? "Expand section"}
      data-react-fancy-accordion-trigger=""
      data-state="closed"
      data-orientation={orientation}
      className={cn(
        "flex shrink-0 items-center justify-center rounded-md",
        "text-zinc-400 dark:text-zinc-500",
        "hover:text-zinc-900 dark:hover:text-zinc-100",
        "hover:bg-zinc-100 dark:hover:bg-zinc-800",
        "transition-colors cursor-pointer",
        orientation === "horizontal" ? "h-8 w-6 mx-0.5" : "w-8 h-6 my-0.5",
        className,
      )}
    >
      <ChevronIcon orientation={orientation} purpose="expand" />
    </button>
  );
}

AccordionPanelTrigger.displayName = "AccordionPanelTrigger";

// ── Internal chevron ────────────────────────────────────────────────────

function ChevronIcon({
  orientation,
  purpose,
  className,
}: {
  orientation: "horizontal" | "vertical";
  /** "expand" → closed section, click to open. "collapse" → open section, click to close. */
  purpose: "expand" | "collapse";
  className?: string;
}) {
  // For horizontal: both states use a left-pointing chevron (matches the
  // screenshot convention — closed sections show ❮, open dividers reveal
  // a ❮ on hover indicating the section will collapse leftward).
  //
  // For vertical: closed shows down ⌄ (click to expand below); open
  // divider on hover shows up ⌃ (click to collapse upward).
  const transform =
    orientation === "horizontal"
      ? "rotate(180deg)"
      : purpose === "expand"
        ? "rotate(90deg)"
        : "rotate(270deg)";

  return (
    <svg
      viewBox="0 0 16 16"
      width="12"
      height="12"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ transform }}
      className={className}
      aria-hidden="true"
    >
      <polyline points="6 4 10 8 6 12" />
    </svg>
  );
}

import { createContext, useContext } from "react";
import type { AccordionOrientation } from "./AccordionPanel.types";

// ── Panel-level context ─────────────────────────────────────────────────

export interface AccordionPanelContextValue {
  orientation: AccordionOrientation;
  isOpen: (id: string) => boolean;
  toggle: (id: string) => void;
  open: (id: string) => void;
  close: (id: string) => void;
  /** Ordered list of all section ids registered in this panel */
  sectionIds: string[];
  registerSection: (id: string) => () => void;
}

export const AccordionPanelContext =
  createContext<AccordionPanelContextValue | null>(null);

export function useAccordionPanel(): AccordionPanelContextValue {
  const ctx = useContext(AccordionPanelContext);
  if (!ctx) {
    throw new Error(
      "AccordionPanel components must be used inside <AccordionPanel>",
    );
  }
  return ctx;
}

// ── Section-level context ───────────────────────────────────────────────

export interface AccordionSectionContextValue {
  id: string;
  open: boolean;
  pinned: boolean;
  orientation: AccordionOrientation;
  toggle: () => void;
}

export const AccordionSectionContext =
  createContext<AccordionSectionContextValue | null>(null);

export function useAccordionSection(): AccordionSectionContextValue {
  const ctx = useContext(AccordionSectionContext);
  if (!ctx) {
    throw new Error(
      "<AccordionPanel.Trigger> must be rendered inside <AccordionPanel.Section>",
    );
  }
  return ctx;
}

import { useCallback, useMemo, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import { useControllableState } from "../../hooks/use-controllable-state";
import { AccordionPanelContext } from "./AccordionPanel.context";
import { AccordionPanelSection } from "./AccordionPanel.Section";
import { AccordionPanelTrigger } from "./AccordionPanel.Trigger";
import { AccordionPanelContent } from "./AccordionPanel.Content";
import type { AccordionPanelProps } from "./AccordionPanel.types";

/**
 * Horizontal or vertical accordion of collapsible sections.
 *
 * Use the compound parts:
 *   <AccordionPanel orientation="horizontal" defaultValue={["wishlist"]}>
 *     <AccordionPanel.Section id="home" pinned>
 *       <Button icon="home" />
 *     </AccordionPanel.Section>
 *     <AccordionPanel.Section id="wishlist">
 *       <Button icon="list">Wishlist</Button>
 *     </AccordionPanel.Section>
 *   </AccordionPanel>
 *
 * Each non-pinned section renders a trigger (default chevron-divider) that
 * collapses/expands. Pass a custom `trigger` prop on a Section, or use the
 * exported `AccordionPanel.Trigger` directly to compose your own.
 */
function AccordionPanelRoot({
  orientation = "horizontal",
  value: controlledValue,
  defaultValue,
  onValueChange,
  className,
  children,
}: AccordionPanelProps) {
  const [openIds, setOpenIds] = useControllableState<string[]>(
    controlledValue,
    defaultValue ?? [],
    onValueChange,
  );

  const openSet = useMemo(() => new Set(openIds), [openIds]);

  const isOpen = useCallback((id: string) => openSet.has(id), [openSet]);

  const open = useCallback(
    (id: string) => {
      setOpenIds(openSet.has(id) ? (openIds ?? []) : [...(openIds ?? []), id]);
    },
    [openSet, openIds, setOpenIds],
  );

  const close = useCallback(
    (id: string) => {
      setOpenIds((openIds ?? []).filter((x) => x !== id));
    },
    [openIds, setOpenIds],
  );

  const toggle = useCallback(
    (id: string) => {
      setOpenIds(
        openSet.has(id)
          ? (openIds ?? []).filter((x) => x !== id)
          : [...(openIds ?? []), id],
      );
    },
    [openSet, openIds, setOpenIds],
  );

  // Track section order for downstream consumers (e.g. trigger direction
  // heuristics that need to know neighbors).
  const [sectionIds, setSectionIds] = useState<string[]>([]);
  const orderRef = useRef<string[]>([]);

  const registerSection = useCallback((id: string) => {
    if (!orderRef.current.includes(id)) {
      orderRef.current = [...orderRef.current, id];
      setSectionIds(orderRef.current);
    }
    return () => {
      orderRef.current = orderRef.current.filter((x) => x !== id);
      setSectionIds(orderRef.current);
    };
  }, []);

  const ctx = useMemo(
    () => ({
      orientation,
      isOpen,
      toggle,
      open,
      close,
      sectionIds,
      registerSection,
    }),
    [orientation, isOpen, toggle, open, close, sectionIds, registerSection],
  );

  return (
    <AccordionPanelContext.Provider value={ctx}>
      <div
        data-react-fancy-accordion-panel=""
        data-orientation={orientation}
        className={cn(
          "inline-flex items-stretch",
          orientation === "horizontal" ? "flex-row" : "flex-col",
          className,
        )}
      >
        {children}
      </div>
    </AccordionPanelContext.Provider>
  );
}

AccordionPanelRoot.displayName = "AccordionPanel";

// ── Compound exports ────────────────────────────────────────────────────

type AccordionPanelType = typeof AccordionPanelRoot & {
  Section: typeof AccordionPanelSection;
  Trigger: typeof AccordionPanelTrigger;
  Content: typeof AccordionPanelContent;
};

export const AccordionPanel = AccordionPanelRoot as AccordionPanelType;
AccordionPanel.Section = AccordionPanelSection;
AccordionPanel.Trigger = AccordionPanelTrigger;
AccordionPanel.Content = AccordionPanelContent;

import type { ReactNode } from "react";

export type AccordionOrientation = "horizontal" | "vertical";

/**
 * Render-prop or static node accepted by Trigger.children — lets the
 * caller branch rendering on the section state.
 */
export type SectionRenderable =
  | ReactNode
  | ((state: SectionRenderState) => ReactNode);

export interface SectionRenderState {
  /** Section's id */
  id: string;
  /** True when the section is currently open */
  open: boolean;
  /** Direction the panel is laid out in */
  orientation: AccordionOrientation;
  /** Toggle this section open/closed */
  toggle: () => void;
}

export interface AccordionPanelProps {
  /** Layout direction. Horizontal for menus/toolbars, vertical for sidebars/panels. */
  orientation?: AccordionOrientation;
  /** Controlled list of open section ids */
  value?: string[];
  /** Default open section ids (uncontrolled) */
  defaultValue?: string[];
  /** Fires whenever the open set changes */
  onValueChange?: (open: string[]) => void;
  /** Optional class on the root container */
  className?: string;
  children: ReactNode;
}

export interface AccordionPanelSectionProps {
  /** Stable id used for open-state tracking */
  id: string;
  /**
   * Pinned sections never collapse. Useful for an "anchor" item like a
   * Home button at the start of a menu.
   */
  pinned?: boolean;
  /** Class on the section's outer container */
  className?: string;
  /** Class applied only when the section is open */
  openClassName?: string;
  /** Class applied only when the section is collapsed */
  closedClassName?: string;
  /**
   * Skip the default flex layout (items-center + gap-1 + flex-row/col).
   * Use this for full-bleed panel sections that need their children
   * to stretch (e.g. a chat sidebar where the trigger should fill
   * full panel height). The data attributes, section context, and
   * conditional render of children stay in place.
   */
  unstyled?: boolean;
  /**
   * Children. Compose with `<AccordionPanel.Trigger>` and
   * `<AccordionPanel.Content>` — Trigger always renders, Content only
   * renders when the section is open.
   */
  children: ReactNode;
}

export interface AccordionPanelTriggerProps {
  /**
   * Custom render. Receives section state — `{ open, toggle, ... }`. If
   * omitted, the default chevron-divider is rendered.
   */
  children?: SectionRenderable;
  /** Class on the trigger element */
  className?: string;
  /** Aria label override (default: "Toggle section") */
  "aria-label"?: string;
}

export { AccordionPanel } from "./AccordionPanel";
export { AccordionPanelSection } from "./AccordionPanel.Section";
export { AccordionPanelTrigger } from "./AccordionPanel.Trigger";
export { AccordionPanelContent } from "./AccordionPanel.Content";
export {
  useAccordionPanel,
  useAccordionSection,
} from "./AccordionPanel.context";
export type {
  AccordionPanelProps,
  AccordionPanelSectionProps,
  AccordionPanelTriggerProps,
  AccordionOrientation,
  SectionRenderable,
  SectionRenderState,
} from "./AccordionPanel.types";
export type { AccordionPanelContentProps } from "./AccordionPanel.Content";

import type { CSSProperties } from "react";

export type AgentCursorProps = {
  x: number;
  y: number;
  name?: string;
  color?: string;
  /** Optional caption shown under the name (e.g. current tool). */
  status?: string;
  className?: string;
  style?: CSSProperties;
};

/**
 * AgentCursor — on-canvas presence marker for the agent. Drop it inside
 * (or alongside) a fancy-whiteboard <Board> at screen coords matching
 * the agent's reported position.
 */
export function AgentCursor({ x, y, name, color = "#a855f7", status, className, style }: AgentCursorProps) {
  return (
    <div
      className={["fai-cursor", className ?? ""].filter(Boolean).join(" ")}
      style={{
        position: "absolute",
        left: x,
        top: y,
        pointerEvents: "none",
        transform: "translate(-2px, -2px)",
        ...style,
      }}
    >
      <svg width="22" height="22" viewBox="0 0 22 22" aria-hidden>
        <path
          d="M2 2 L2 17 L7 13 L10 19 L12 18 L9 12 L15 12 Z"
          fill={color}
          stroke="white"
          strokeWidth="1.2"
        />
      </svg>
      {name && (
        <span
          className="fai-cursor__tag"
          style={{ background: color }}
        >
          {name}
          {status ? <em className="fai-cursor__status"> · {status}</em> : null}
        </span>
      )}
    </div>
  );
}

import { type CSSProperties, type ReactNode, useEffect, useRef } from "react";

export type AgentActivity = {
  id: string;
  /** Wall-clock timestamp; component formats it. */
  at: number;
  /** "tool" for MCP tool invocations, "message" for chat, "info" for status. */
  kind: "tool" | "message" | "info" | "error";
  /** Short label, e.g. "whiteboard_add_sticky" or "Agent". */
  source: string;
  /** Body text. */
  text: string;
  /** Optional structured payload, rendered as collapsed JSON. */
  detail?: unknown;
};

export type AgentPanelProps = {
  /** The agent's identity (name + color appears in the header). */
  agent?: { name?: string; color?: string };
  /** Activity stream. Most recent at the end. */
  activity: AgentActivity[];
  /** Optional chat composer — pass an onSubmit to enable. */
  onSubmit?: (message: string) => void;
  /** Disabled while a request is in flight. */
  busy?: boolean;
  /** Right-rail header actions. */
  actions?: ReactNode;
  className?: string;
  style?: CSSProperties;
};

/**
 * AgentPanel — sidebar showing the agent's identity, a tool-and-chat log,
 * and an optional input composer. Pure presentational: hosts feed it the
 * activity stream from their own state (typically the MCP transport log).
 */
export function AgentPanel({ agent, activity, onSubmit, busy, actions, className, style }: AgentPanelProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    el.scrollTop = el.scrollHeight;
  }, [activity.length]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const value = inputRef.current?.value.trim();
    if (!value || !onSubmit) return;
    onSubmit(value);
    if (inputRef.current) inputRef.current.value = "";
  };

  const color = agent?.color ?? "#a855f7";
  const name = agent?.name ?? "Agent";

  return (
    <div className={["fai-panel", className ?? ""].filter(Boolean).join(" ")} style={style}>
      <header className="fai-panel__header">
        <div
          className="fai-panel__avatar"
          style={{ background: color }}
          aria-hidden
        >
          {name.slice(0, 1)}
        </div>
        <div className="fai-panel__title">
          <strong>{name}</strong>
          <span className="fai-panel__subtitle">
            {busy ? "Working…" : `${activity.length} event${activity.length === 1 ? "" : "s"}`}
          </span>
        </div>
        {actions && <div className="fai-panel__actions">{actions}</div>}
      </header>

      <div ref={scrollRef} className="fai-panel__stream">
        {activity.length === 0 ? (
          <p className="fai-panel__empty">No activity yet.</p>
        ) : (
          activity.map((a) => <ActivityRow key={a.id} item={a} />)
        )}
      </div>

      {onSubmit && (
        <form className="fai-panel__composer" onSubmit={handleSubmit}>
          <textarea
            ref={inputRef}
            className="fai-panel__input"
            placeholder={busy ? "Working…" : "Ask the agent…"}
            disabled={busy}
            rows={2}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                handleSubmit(e as unknown as React.FormEvent);
              }
            }}
          />
          <button type="submit" className="fai-panel__send" disabled={busy}>
            Send
          </button>
        </form>
      )}
    </div>
  );
}

function ActivityRow({ item }: { item: AgentActivity }) {
  const time = formatTime(item.at);
  return (
    <div className={`fai-row fai-row--${item.kind}`}>
      <div className="fai-row__meta">
        <span className="fai-row__source">{item.source}</span>
        <span className="fai-row__time">{time}</span>
      </div>
      <div className="fai-row__text">{item.text}</div>
      {item.detail !== undefined && (
        <details className="fai-row__detail">
          <summary>details</summary>
          <pre>{safeJson(item.detail)}</pre>
        </details>
      )}
    </div>
  );
}

function formatTime(at: number): string {
  const d = new Date(at);
  const hh = d.getHours().toString().padStart(2, "0");
  const mm = d.getMinutes().toString().padStart(2, "0");
  const ss = d.getSeconds().toString().padStart(2, "0");
  return `${hh}:${mm}:${ss}`;
}

function safeJson(v: unknown): string {
  try {
    return JSON.stringify(v, null, 2);
  } catch {
    return String(v);
  }
}

import { type ReactNode } from "react";
import type { ArtPieceContent } from "../../types";

export type ArtPieceProps = {
  /** Stable handle — agents/selectors target this without guessing the DOM. */
  id: string;
  label?: string;
  width?: number;
  height?: number;
  /**
   * Content source. Omit to render `children` as a `kind:"node"` piece
   * (JSX authoring sugar), or pass an explicit image/html/node descriptor.
   */
  content?: ArtPieceContent;
  /** Proposed (agent-staged) piece — renders with a trust-but-verify affordance. */
  pending?: boolean;
  /** JSX content when authoring inline (compiled to a `kind:"node"` piece). */
  children?: ReactNode;
};

/**
 * Authoring marker for a single design frame. Renders nothing itself — the
 * parent `<ArtBoard>` walks `<ArtPiece>` children to compile the
 * `ArtBoardValue` and a content registry (for `kind:"node"` JSX). The frame
 * chrome + content host is rendered by `PieceFrame`.
 */
export function ArtPiece(_props: ArtPieceProps): null {
  return null;
}
ArtPiece.displayName = "ArtPiece";

import { useRef, useState, type CSSProperties } from "react";
import { Action, Dropdown, Tooltip } from "@particle-academy/react-fancy";
import type { ArtPieceData, ArtSectionData } from "../../types";
import { useArtBoard } from "../ArtBoard/context";
import { InlineEditor } from "../InlineEditor";
import { exportPiece, exportName, type ExportKind } from "../../lib/export";
import { cx } from "../../lib/cx";

const DEFAULT_W = 260;
const DEFAULT_H = 480;

type PieceFrameProps = {
  sectionId: string;
  piece: ArtPieceData;
  /** Ordered piece ids in the section — for live drag-reorder. */
  order: string[];
};

export function PieceFrame({ sectionId, piece, order }: PieceFrameProps) {
  const board = useArtBoard();
  const slotRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  // Two-click delete confirm — persists across menu re-opens.
  const [confirming, setConfirming] = useState(false);
  const width = piece.width ?? DEFAULT_W;
  const height = piece.height ?? DEFAULT_H;
  const id = piece.id;
  const label = piece.label ?? id;

  const renameLabel = (next: string) => {
    board.setSections((sections) =>
      sections.map((s) =>
        s.id === sectionId
          ? { ...s, pieces: s.pieces.map((p) => (p.id === id ? { ...p, label: next } : p)) }
          : s,
      ),
    );
  };

  const reorder = (nextOrder: string[]) => {
    board.setSections((sections) =>
      sections.map((s) => {
        if (s.id !== sectionId) return s;
        const byId = new Map(s.pieces.map((p) => [p.id, p]));
        return { ...s, pieces: nextOrder.map((k) => byId.get(k)!).filter(Boolean) };
      }),
    );
  };

  const remove = () => {
    board.setSections((sections) =>
      sections.map((s) =>
        s.id === sectionId ? { ...s, pieces: s.pieces.filter((p) => p.id !== id) } : s,
      ),
    );
  };

  const doExport = (kind: ExportKind) => {
    board.onExport?.(id, kind);
    if (!cardRef.current) return;
    exportPiece(cardRef.current, width, height, exportName(piece.label, id), kind).catch((e) =>
      // eslint-disable-next-line no-console
      console.error("[fancy-artboard] export failed:", e),
    );
  };

  const focus = () => board.setFocus(id);

  // Live drag-reorder: dragged card sticks to the cursor; siblings slide into
  // their would-be slots via transforms; DOM order commits only on drop.
  const onGripDown = (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const me = slotRef.current;
    if (!me) return;
    // translateX is in local (pre-scale) space but pointer deltas + rect.left
    // are screen-space — divide by the live zoom so it tracks the cursor.
    const scale = me.getBoundingClientRect().width / me.offsetWidth || 1;
    const peers = Array.from(
      document.querySelectorAll<HTMLElement>(
        `[data-fa-section="${CSS.escape(sectionId)}"] [data-fa-piece]`,
      ),
    );
    const homes = peers.map((el) => ({
      el,
      id: el.dataset.faPiece as string,
      x: el.getBoundingClientRect().left,
    }));
    const slotXs = homes.map((h) => h.x);
    const startIdx = order.indexOf(id);
    const startX = e.clientX;
    let liveOrder = order.slice();
    me.classList.add("fa-dragging");

    const layout = () => {
      for (const h of homes) {
        if (h.id === id) continue;
        const slot = liveOrder.indexOf(h.id);
        h.el.style.transform = `translateX(${(slotXs[slot] - h.x) / scale}px)`;
      }
    };

    const move = (ev: PointerEvent) => {
      const dx = ev.clientX - startX;
      me.style.transform = `translateX(${dx / scale}px)`;
      const cur = homes[startIdx].x + dx;
      let nearest = 0;
      let best = Infinity;
      for (let i = 0; i < slotXs.length; i++) {
        const d = Math.abs(slotXs[i] - cur);
        if (d < best) {
          best = d;
          nearest = i;
        }
      }
      if (liveOrder.indexOf(id) !== nearest) {
        liveOrder = order.filter((k) => k !== id);
        liveOrder.splice(nearest, 0, id);
        layout();
      }
    };

    const up = () => {
      document.removeEventListener("pointermove", move);
      document.removeEventListener("pointerup", up);
      const finalSlot = liveOrder.indexOf(id);
      me.classList.remove("fa-dragging");
      me.style.transform = `translateX(${(slotXs[finalSlot] - homes[startIdx].x) / scale}px)`;
      // After the settle transition, kill transitions + clear transforms +
      // commit in the same frame so there's no snap-back flash.
      setTimeout(() => {
        for (const h of homes) {
          h.el.style.transition = "none";
          h.el.style.transform = "";
        }
        if (liveOrder.join("|") !== order.join("|")) reorder(liveOrder);
        requestAnimationFrame(() =>
          requestAnimationFrame(() => {
            for (const h of homes) h.el.style.transition = "";
          }),
        );
      }, 180);
    };

    document.addEventListener("pointermove", move);
    document.addEventListener("pointerup", up);
  };

  const cardStyle: CSSProperties = {
    width,
    height,
  };

  return (
    <div ref={slotRef} className="fa-slot" data-fa-piece={id}>
      <div
        className="fa-header"
        data-fa-chrome=""
        onPointerDown={(e) => e.stopPropagation()}
      >
        <div className="fa-labelrow">
          <span
            className="fa-grip"
            onPointerDown={onGripDown}
            title="Drag to reorder"
            aria-label="Drag to reorder"
          >
            <svg width="9" height="13" viewBox="0 0 9 13" fill="currentColor" aria-hidden>
              <circle cx="2" cy="2" r="1.1" />
              <circle cx="7" cy="2" r="1.1" />
              <circle cx="2" cy="6.5" r="1.1" />
              <circle cx="7" cy="6.5" r="1.1" />
              <circle cx="2" cy="11" r="1.1" />
              <circle cx="7" cy="11" r="1.1" />
            </svg>
          </span>
          <span className="fa-labeltext" onClick={focus} title="Click to focus">
            <InlineEditor
              value={label}
              onChange={renameLabel}
              onClick={(e) => e.stopPropagation()}
              style={{ fontSize: 15, fontWeight: 500, lineHeight: 1 }}
            />
          </span>
        </div>
        <div className="fa-btns">
          <Dropdown placement="bottom-start">
            <Dropdown.Trigger>
              <Tooltip content="More">
                <Action variant="ghost" size="sm" icon="more-horizontal" aria-label="More" />
              </Tooltip>
            </Dropdown.Trigger>
            <Dropdown.Items className="fa-menu">
              <Dropdown.Item
                onClick={() => {
                  setConfirming(false);
                  doExport("png");
                }}
              >
                Download PNG
              </Dropdown.Item>
              <Dropdown.Item
                onClick={() => {
                  setConfirming(false);
                  doExport("html");
                }}
              >
                Download HTML
              </Dropdown.Item>
              <Dropdown.Separator />
              <Dropdown.Item
                danger
                onClick={() => {
                  if (confirming) {
                    setConfirming(false);
                    remove();
                  } else {
                    setConfirming(true);
                  }
                }}
              >
                {confirming ? "Click again to delete" : "Delete"}
              </Dropdown.Item>
            </Dropdown.Items>
          </Dropdown>
          <Tooltip content="Focus">
            <Action variant="ghost" size="sm" icon="maximize" onClick={focus} aria-label="Focus" />
          </Tooltip>
        </div>
      </div>
      <div
        ref={cardRef}
        className={cx("fa-card", piece.pending && "fa-pending")}
        style={cardStyle}
      >
        <PieceContent piece={piece} />
        {piece.pending && <span className="fa-pending-badge">proposed</span>}
      </div>
    </div>
  );
}

/** Renders the piece content inline so it scales crisply under the world transform. */
function PieceContent({ piece }: { piece: ArtPieceData }) {
  const board = useArtBoard();
  const c = piece.content;
  if (c.kind === "image") {
    return (
      <img
        src={c.src}
        alt={c.alt ?? piece.label ?? piece.id}
        style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
      />
    );
  }
  if (c.kind === "html") {
    return (
      <div
        style={{ width: "100%", height: "100%" }}
        dangerouslySetInnerHTML={{ __html: c.html }}
      />
    );
  }
  // kind: "node" — the JSX child the human authored.
  const node = board.nodes.get(piece.id);
  return <>{node ?? null}</>;
}

import {
  Children,
  Fragment,
  isValidElement,
  useCallback,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactElement,
  type ReactNode,
} from "react";
import type {
  ArtBoardValue,
  ArtPieceData,
  ArtSectionData,
  Viewport,
} from "../../types";
import { ArtBoardContext, type ArtBoardCtx } from "./context";
import { ViewportEngine } from "./Viewport";
import { Section, SectionView, type SectionProps } from "./Section";
import { ArtPiece, type ArtPieceProps } from "../ArtPiece/ArtPiece";
import { Note } from "../Note/Note";
import { FocusOverlay } from "../FocusOverlay/FocusOverlay";

const DEFAULT_VIEWPORT: Viewport = { x: 0, y: 0, zoom: 1 };

export type ArtBoardProps = {
  value?: ArtBoardValue;
  defaultValue?: ArtBoardValue;
  onChange?: (v: ArtBoardValue) => void;
  viewport?: Viewport;
  defaultViewport?: Viewport;
  onViewportChange?: (v: Viewport) => void;
  focus?: string | null;
  onFocusChange?: (pieceId: string | null) => void;
  minZoom?: number;
  maxZoom?: number;
  onExport?: (pieceId: string, kind: "png" | "html") => void;
  /** `<ArtBoard.Section>` / `<ArtPiece>` authoring sugar. */
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
};

// Recursively unwrap fragments so <>...</> grouping doesn't hide children.
function flatten(children: ReactNode): ReactNode[] {
  const out: ReactNode[] = [];
  Children.forEach(children, (c) => {
    if (isValidElement(c) && c.type === Fragment) {
      out.push(...flatten((c.props as { children?: ReactNode }).children));
    } else {
      out.push(c);
    }
  });
  return out;
}

type Compiled = { value: ArtBoardValue; nodes: Map<string, ReactNode> };

/** Walk Section/ArtPiece children into an ArtBoardValue + JSX node registry. */
function compileChildren(children: ReactNode): Compiled {
  const sections: ArtSectionData[] = [];
  const nodes = new Map<string, ReactNode>();

  flatten(children).forEach((sec) => {
    if (!isValidElement(sec) || sec.type !== Section) return;
    const sp = sec.props as SectionProps;
    const sid = sp.id ?? sp.title;
    if (!sid) return;
    const pieces: ArtPieceData[] = [];
    flatten(sp.children).forEach((pc) => {
      if (!isValidElement(pc) || pc.type !== ArtPiece) return;
      const pp = (pc as ReactElement).props as ArtPieceProps;
      if (!pp.id) return;
      const content = pp.content ?? { kind: "node" as const };
      if (content.kind === "node") nodes.set(pp.id, pp.children);
      pieces.push({
        id: pp.id,
        label: pp.label,
        width: pp.width,
        height: pp.height,
        content,
        pending: pp.pending,
      });
    });
    sections.push({ id: sid, title: sp.title, subtitle: sp.subtitle, pieces });
  });

  return { value: { sections }, nodes };
}

/**
 * Figma-style design canvas. Controlled (or uncontrolled) pan/zoom board of
 * `ArtPiece`s grouped into `ArtBoard.Section`s. Composes react-fancy chrome and
 * emits no agent events itself — a bridge layer owns presence/undo.
 */
function ArtBoardRoot({
  value,
  defaultValue,
  onChange,
  viewport,
  defaultViewport,
  onViewportChange,
  focus,
  onFocusChange,
  minZoom = 0.1,
  maxZoom = 8,
  onExport,
  children,
  className,
  style,
}: ArtBoardProps) {
  // children -> value + node registry (one source of truth). Recomputed each
  // render so authored JSX stays live, but only used to seed uncontrolled state.
  const compiled = useMemo(() => compileChildren(children), [children]);

  // value: controlled if `value` defined, else internal seeded from
  // defaultValue ?? compiled-from-children.
  const [internalValue, setInternalValue] = useState<ArtBoardValue>(
    () => defaultValue ?? compiled.value,
  );
  const resolvedValue = value ?? internalValue;

  const setValue = useCallback(
    (next: ArtBoardValue) => {
      if (value === undefined) setInternalValue(next);
      onChange?.(next);
    },
    [value, onChange],
  );

  const setSections = useCallback(
    (fn: (sections: ArtSectionData[]) => ArtSectionData[]) => {
      const cur = value ?? internalValueRef.current;
      setValue({ sections: fn(cur.sections) });
    },
    // setValue depends on value/onChange; cur is read via ref to stay fresh.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [setValue, value],
  );
  // Keep latest internal value reachable from the stable setSections closure.
  const internalValueRef = useRef(internalValue);
  internalValueRef.current = internalValue;

  // viewport: controlled or internal.
  const [internalVp, setInternalVp] = useState<Viewport>(
    () => defaultViewport ?? DEFAULT_VIEWPORT,
  );
  const resolvedVp = viewport ?? internalVp;
  const setVp = useCallback(
    (next: Viewport) => {
      if (viewport === undefined) setInternalVp(next);
      onViewportChange?.(next);
    },
    [viewport, onViewportChange],
  );

  // focus: controlled or internal.
  const [internalFocus, setInternalFocus] = useState<string | null>(null);
  const resolvedFocus = focus !== undefined ? focus : internalFocus;
  const setFocus = useCallback(
    (next: string | null) => {
      if (focus === undefined) setInternalFocus(next);
      onFocusChange?.(next);
    },
    [focus, onFocusChange],
  );

  // The node registry: when controlled by `value`, JSX nodes still come from
  // children (the value JSON can't carry React nodes). Merge children-derived
  // nodes regardless of the value source.
  const ctx: ArtBoardCtx = useMemo(
    () => ({
      value: resolvedValue,
      nodes: compiled.nodes,
      patchValue: setValue,
      setSections,
      focus: resolvedFocus,
      setFocus,
      onExport,
    }),
    [resolvedValue, compiled.nodes, setValue, setSections, resolvedFocus, setFocus, onExport],
  );

  return (
    <ArtBoardContext.Provider value={ctx}>
      <ViewportEngine
        viewport={resolvedVp}
        onViewportChange={setVp}
        minZoom={minZoom}
        maxZoom={maxZoom}
        className={className}
        style={style}
      >
        {resolvedValue.sections.map((section) => (
          <SectionView key={section.id} section={section} />
        ))}
        {/* Free-floating notes authored as direct children (outside sections). */}
        {flatten(children).filter((c) => isValidElement(c) && c.type === Note)}
      </ViewportEngine>
      {resolvedFocus != null && <FocusOverlay />}
    </ArtBoardContext.Provider>
  );
}

export const ArtBoard = Object.assign(ArtBoardRoot, {
  Section,
  Note,
});

import { type ReactNode } from "react";
import type { ArtSectionData } from "../../types";
import { useArtBoard } from "./context";
import { InlineEditor } from "../InlineEditor";
import { PieceFrame } from "../ArtPiece/PieceFrame";

export type SectionProps = {
  /** Stable handle. */
  id: string;
  title: string;
  subtitle?: string;
  /** `<ArtPiece>` children (authoring sugar). Ignored when `value` drives the board. */
  children?: ReactNode;
};

/**
 * Authoring marker for a section. Renders nothing on its own — `<ArtBoard>`
 * compiles `<ArtBoard.Section>` + `<ArtPiece>` children into the value. The
 * live section (titled head + horizontal piece row) is rendered by
 * `SectionView` from the controlled value.
 */
export function Section(_props: SectionProps): null {
  return null;
}
Section.displayName = "ArtBoard.Section";

/** The rendered section — head + horizontal row of piece frames in order. */
export function SectionView({ section }: { section: ArtSectionData }) {
  const board = useArtBoard();
  const order = section.pieces.map((p) => p.id);

  const patchTitle = (next: string) => {
    board.setSections((sections) =>
      sections.map((s) => (s.id === section.id ? { ...s, title: next } : s)),
    );
  };

  return (
    <div className="fa-section" data-fa-section={section.id}>
      <div className="fa-sectionhead-wrap">
        <div className="fa-sectionhead" data-fa-chrome="">
          <InlineEditor
            as="div"
            value={section.title}
            onChange={patchTitle}
            className="fa-sectiontitle"
          />
          {section.subtitle && <div className="fa-sectionsub">{section.subtitle}</div>}
        </div>
      </div>
      <div className="fa-row">
        {section.pieces.map((piece) => (
          <PieceFrame key={piece.id} sectionId={section.id} piece={piece} order={order} />
        ))}
      </div>
    </div>
  );
}

import {
  useCallback,
  useEffect,
  useRef,
  type CSSProperties,
  type ReactNode,
} from "react";
import type { Viewport } from "../../types";

type ViewportEngineProps = {
  viewport: Viewport;
  onViewportChange: (v: Viewport) => void;
  minZoom: number;
  maxZoom: number;
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
};

const GRID_COLOR = "rgba(0,0,0,0.06)";
const gridSvg = `url("data:image/svg+xml,%3Csvg width='120' height='120' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M120 0H0v120' fill='none' stroke='${encodeURIComponent(
  GRID_COLOR,
)}' stroke-width='1'/%3E%3C/svg%3E")`;

/**
 * Transform-based pan/zoom engine (internal). Writes `translate3d(x,y,0)
 * scale(zoom)` straight to a DOM ref so wheel ticks bypass React; the
 * controlled `viewport` prop is the source of truth and `onViewportChange`
 * fires after each gesture frame.
 *
 * Input mapping (Figma-style):
 *   - trackpad pinch (ctrlKey wheel, non-integer delta) -> zoom
 *   - notched mouse wheel (integer |deltaY|>=40 or deltaMode!==0) -> stepped zoom
 *   - two-finger scroll -> pan
 *   - middle-drag / primary-drag on empty background -> pan
 *   - Safari gesturestart/change/end -> zoom
 *
 * Cursor-anchored zoom keeps the world point under the cursor fixed, then
 * cancels the vertical drift introduced by `--fa-inv-zoom`-driven reflow of
 * the section heads (CSS `zoom`) by re-pinning the DOM element under the
 * cursor.
 */
export function ViewportEngine({
  viewport,
  onViewportChange,
  minZoom,
  maxZoom,
  children,
  className,
  style,
}: ViewportEngineProps) {
  const vpRef = useRef<HTMLDivElement>(null);
  const worldRef = useRef<HTMLDivElement>(null);
  // Live transform state lives in a ref so high-frequency wheel/pointer events
  // don't round-trip through React. We mirror the controlled prop into it.
  const tf = useRef<Viewport>(viewport);
  const onChangeRef = useRef(onViewportChange);
  onChangeRef.current = onViewportChange;
  const limits = useRef({ minZoom, maxZoom });
  limits.current = { minZoom, maxZoom };

  // Write the live transform to the DOM + expose --fa-inv-zoom for chrome.
  const apply = useCallback(() => {
    const el = worldRef.current;
    if (!el) return;
    const { x, y, zoom } = tf.current;
    el.style.transform = `translate3d(${x}px, ${y}px, 0) scale(${zoom})`;
    el.style.setProperty("--fa-inv-zoom", String(1 / zoom));
  }, []);

  // Sync external (controlled) changes into the ref + DOM. Skip if the value
  // already matches what we wrote (our own gesture echo).
  useEffect(() => {
    const cur = tf.current;
    if (cur.x !== viewport.x || cur.y !== viewport.y || cur.zoom !== viewport.zoom) {
      tf.current = viewport;
      apply();
    }
  }, [viewport, apply]);

  // Initial paint.
  useEffect(() => {
    apply();
  }, [apply]);

  const commit = useCallback(() => {
    onChangeRef.current({ ...tf.current });
  }, []);

  useEffect(() => {
    const vp = vpRef.current;
    if (!vp) return;

    const zoomAt = (cx: number, cy: number, factor: number) => {
      const r = vp.getBoundingClientRect();
      const px = cx - r.left;
      const py = cy - r.top;
      const t = tf.current;
      const next = Math.min(limits.current.maxZoom, Math.max(limits.current.minZoom, t.zoom * factor));
      const k = next / t.zoom;

      // The `--fa-inv-zoom`-driven section heads (CSS `zoom`) reflow on every
      // scale change, shifting world layout vertically. Anchor the DOM element
      // under the cursor: record its screen-Y, apply, then cancel the drift.
      let marker: Element | null = null;
      let markerY0 = 0;
      if (k !== 1) {
        const hit = document.elementFromPoint(cx, cy);
        marker = hit ? hit.closest("[data-fa-piece],[data-fa-section]") : null;
        if (marker) markerY0 = marker.getBoundingClientRect().top;
      }

      // Keep the world point under the cursor fixed.
      t.x = px - (px - t.x) * k;
      t.y = py - (py - t.y) * k;
      t.zoom = next;
      apply();

      if (marker) {
        const drift = marker.getBoundingClientRect().top - (cy + (markerY0 - cy) * k);
        if (Math.abs(drift) > 0.1) {
          t.y -= drift;
          apply();
        }
      }
    };

    // Physical wheel vs trackpad-scroll heuristic.
    const isMouseWheel = (e: WheelEvent) =>
      e.deltaMode !== 0 ||
      (e.deltaX === 0 && Number.isInteger(e.deltaY) && Math.abs(e.deltaY) >= 40);

    let isGesturing = false;

    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (isGesturing) return; // Safari gesture* owns the pinch
      if ((e.ctrlKey || e.metaKey) && !isMouseWheel(e)) {
        zoomAt(e.clientX, e.clientY, Math.exp(-e.deltaY * 0.01));
      } else if (isMouseWheel(e)) {
        zoomAt(e.clientX, e.clientY, Math.exp(-Math.sign(e.deltaY) * 0.18));
      } else {
        tf.current.x -= e.deltaX;
        tf.current.y -= e.deltaY;
        apply();
      }
      commit();
    };

    // Safari native pinch.
    let gsBase = 1;
    const onGestureStart = (e: Event) => {
      e.preventDefault();
      isGesturing = true;
      gsBase = tf.current.zoom;
    };
    const onGestureChange = (e: Event) => {
      e.preventDefault();
      const ge = e as Event & { scale: number; clientX: number; clientY: number };
      zoomAt(ge.clientX, ge.clientY, (gsBase * ge.scale) / tf.current.zoom);
      commit();
    };
    const onGestureEnd = (e: Event) => {
      e.preventDefault();
      isGesturing = false;
      commit();
    };

    // Drag-pan: middle button anywhere, or primary on empty background.
    let drag: { id: number; lx: number; ly: number } | null = null;
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Element;
      const onBg = !target.closest("[data-fa-piece], .fa-editable, [data-fa-chrome]");
      if (!(e.button === 1 || (e.button === 0 && onBg))) return;
      e.preventDefault();
      vp.setPointerCapture(e.pointerId);
      drag = { id: e.pointerId, lx: e.clientX, ly: e.clientY };
      vp.style.cursor = "grabbing";
    };
    const onPointerMove = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      tf.current.x += e.clientX - drag.lx;
      tf.current.y += e.clientY - drag.ly;
      drag.lx = e.clientX;
      drag.ly = e.clientY;
      apply();
    };
    const onPointerUp = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      vp.releasePointerCapture(e.pointerId);
      drag = null;
      vp.style.cursor = "";
      commit();
    };

    vp.addEventListener("wheel", onWheel, { passive: false });
    vp.addEventListener("gesturestart", onGestureStart as EventListener, { passive: false });
    vp.addEventListener("gesturechange", onGestureChange as EventListener, { passive: false });
    vp.addEventListener("gestureend", onGestureEnd as EventListener, { passive: false });
    vp.addEventListener("pointerdown", onPointerDown);
    vp.addEventListener("pointermove", onPointerMove);
    vp.addEventListener("pointerup", onPointerUp);
    vp.addEventListener("pointercancel", onPointerUp);
    return () => {
      vp.removeEventListener("wheel", onWheel);
      vp.removeEventListener("gesturestart", onGestureStart as EventListener);
      vp.removeEventListener("gesturechange", onGestureChange as EventListener);
      vp.removeEventListener("gestureend", onGestureEnd as EventListener);
      vp.removeEventListener("pointerdown", onPointerDown);
      vp.removeEventListener("pointermove", onPointerMove);
      vp.removeEventListener("pointerup", onPointerUp);
      vp.removeEventListener("pointercancel", onPointerUp);
    };
  }, [apply, commit]);

  return (
    <div ref={vpRef} className={"fa-viewport " + (className ?? "")} style={style}>
      <div ref={worldRef} className="fa-world">
        <div
          className="fa-grid"
          style={{ backgroundImage: gridSvg }}
          aria-hidden
        />
        {children}
      </div>
    </div>
  );
}

import { createContext, useContext, type ReactNode } from "react";
import type { ArtBoardValue, ArtSectionData } from "../../types";

/** Internal board context shared by Section / PieceFrame / FocusOverlay. */
export type ArtBoardCtx = {
  value: ArtBoardValue;
  /** JSX content for `kind:"node"` pieces, keyed by piece id. */
  nodes: Map<string, ReactNode>;
  /** Current scale (1/--fa-inv-zoom) — used by drag math to map screen px. */
  patchValue: (next: ArtBoardValue) => void;
  setSections: (fn: (sections: ArtSectionData[]) => ArtSectionData[]) => void;
  focus: string | null;
  setFocus: (pieceId: string | null) => void;
  onExport?: (pieceId: string, kind: "png" | "html") => void;
