      (date: Date) => {
        if (isDisabled(date)) return;

        if (mode === "single") {
          onChange?.(date);
        } else if (mode === "multiple") {
          const arr = (Array.isArray(value) ? value : []) as Date[];
          const exists = arr.findIndex((d) => isSameDay(d, date));
          if (exists >= 0) {
            onChange?.(arr.filter((_, i) => i !== exists));
          } else {
            onChange?.([...arr, date]);
