  maxZoom = 3,
  pannable = true,
  zoomable = true,
  showGrid = false,
  gridStyle = "dots",
  gridSize = 20,
  gridColor = "rgb(161 161 170 / 0.3)",
  snapToGrid = false,
  fitOnMount = false,
  engine: engineSpec,
  className,
  style,
}: CanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [viewport, setViewport] = useControllableState(controlledViewport, defaultViewport, onViewportChange);
  const { registerNode, unregisterNode, nodeRects, version: registryVersion } = useNodeRegistry();
  const [engineHandle, setEngineHandle] = useState<EngineHandle | null>(null);

  // Mount the chosen engine once per spec change. Default "dom" engine is a
  // no-op so this does not affect existing consumers.
  useEffect(() => {
    const host = containerRef.current;
    if (!host) return;
    const resolved = resolveEngine(engineSpec);
    let handle: EngineHandle | null = null;
    try {
      handle = resolved.mount(host, viewport);
      setEngineHandle(handle);
    } catch (err) {
