  const { containerProps } = usePanZoom({
    viewport,
    setViewport,
    minZoom,
    maxZoom,
    pannable,
    zoomable,
    containerRef,
  });

  const ctx = useMemo(
    () => ({ viewport, setViewport, registerNode, unregisterNode, nodeRects, registryVersion, containerRef, gridSize, snapToGrid, engine: engineHandle }),
    [viewport, setViewport, registerNode, unregisterNode, nodeRects, registryVersion, gridSize, snapToGrid, engineHandle],
  );

