export const DEFAULT_COLORS = [
  "#3b82f6", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6",
  "#06b6d4", "#ec4899", "#f97316",
];

export function createLinearScale(
  domain: [number, number],
  range: [number, number],
): (value: number) => number {
  const [d0, d1] = domain;
  const [r0, r1] = range;
  const span = d1 - d0 || 1;
  return (value: number) => r0 + ((value - d0) / span) * (r1 - r0);
}

export function linearPath(points: [number, number][]): string {
  if (points.length === 0) return "";
  return points.map((p, i) => `${i === 0 ? "M" : "L"}${p[0]},${p[1]}`).join(" ");
}

export function monotonePath(points: [number, number][]): string {
  if (points.length < 2) return linearPath(points);
  if (points.length === 2) return linearPath(points);

  const n = points.length;
  const dx: number[] = [];
  const dy: number[] = [];
  const m: number[] = [];

  for (let i = 0; i < n - 1; i++) {
    dx.push(points[i + 1][0] - points[i][0]);
    dy.push(points[i + 1][1] - points[i][1]);
    m.push(dy[i] / (dx[i] || 1));
  }

  // Fritsch-Carlson tangents
  const tangents: number[] = [m[0]];
  for (let i = 1; i < n - 1; i++) {
    if (m[i - 1] * m[i] <= 0) {
      tangents.push(0);
    } else {
      tangents.push((m[i - 1] + m[i]) / 2);
    }
  }
  tangents.push(m[n - 2]);

  // Clamp tangents
  for (let i = 0; i < n - 1; i++) {
    if (Math.abs(m[i]) < 1e-6) {
      tangents[i] = 0;
      tangents[i + 1] = 0;
    } else {
      const a = tangents[i] / m[i];
      const b = tangents[i + 1] / m[i];
      const s = a * a + b * b;
      if (s > 9) {
        const t = 3 / Math.sqrt(s);
        tangents[i] = t * a * m[i];
        tangents[i + 1] = t * b * m[i];
      }
    }
  }

  let d = `M${points[0][0]},${points[0][1]}`;
  for (let i = 0; i < n - 1; i++) {
    const p0 = points[i];
    const p1 = points[i + 1];
    const dxi = dx[i] / 3;
    const cp1x = p0[0] + dxi;
    const cp1y = p0[1] + tangents[i] * dxi;
    const cp2x = p1[0] - dxi;
    const cp2y = p1[1] - tangents[i + 1] * dxi;
    d += ` C${cp1x},${cp1y} ${cp2x},${cp2y} ${p1[0]},${p1[1]}`;
  }

  return d;
}

export function areaPath(points: [number, number][], baseline: number): string {
  if (points.length === 0) return "";
  const top = monotonePath(points);
  const lastPoint = points[points.length - 1];
  const firstPoint = points[0];
  return `${top} L${lastPoint[0]},${baseline} L${firstPoint[0]},${baseline} Z`;
}

export function computeTicks(min: number, max: number, count: number = 5): number[] {
  if (count < 2) return [min];
  const ticks: number[] = [];
  const step = (max - min) / (count - 1);
  for (let i = 0; i < count; i++) {
    ticks.push(min + step * i);
  }
  return ticks;
}

export function niceNum(range: number, round: boolean): number {
  const exponent = Math.floor(Math.log10(range));
  const fraction = range / Math.pow(10, exponent);
  let niceFraction: number;
  if (round) {
    if (fraction < 1.5) niceFraction = 1;
    else if (fraction < 3) niceFraction = 2;
    else if (fraction < 7) niceFraction = 5;
    else niceFraction = 10;
  } else {
    if (fraction <= 1) niceFraction = 1;
    else if (fraction <= 2) niceFraction = 2;
    else if (fraction <= 5) niceFraction = 5;
    else niceFraction = 10;
  }
  return niceFraction * Math.pow(10, exponent);
}

export function niceScale(min: number, max: number, tickCount: number = 5): { min: number; max: number; ticks: number[] } {
  if (min === max) {
    return { min: min - 1, max: max + 1, ticks: computeTicks(min - 1, max + 1, tickCount) };
  }
  const range = niceNum(max - min, false);
  const tickSpacing = niceNum(range / (tickCount - 1), true);
  const niceMin = Math.floor(min / tickSpacing) * tickSpacing;
  const niceMax = Math.ceil(max / tickSpacing) * tickSpacing;
  const ticks: number[] = [];
  for (let v = niceMin; v <= niceMax + tickSpacing * 0.5; v += tickSpacing) {
    ticks.push(Math.round(v * 1e10) / 1e10);
  }
  return { min: niceMin, max: niceMax, ticks };
}

import { type ReactNode, useCallback } from "react";
import { Icon } from "../Icon";

/**
 * ChatDrawer — tabbed, collapsible panel that sits *above* a `PromptInput`
 * (via the input's `aboveInput` slot) so the drawer and composer share one
 * rounded shell. Each tab gets a numbered chip and a content panel; only
 * one panel renders at a time.
 *
 *   <PromptInput
 *     aboveInput={
 *       <ChatDrawer
 *         tabs={[
 *           { id: "files",   label: "Files" },
 *           { id: "tools",   label: "Chat Tools" },
 *           { id: "prompts", label: "Chat Prompts" },
 *           { id: "deal",    label: "IBM Analytics Platform" },
 *         ]}
 *         activeTabId={tab}
 *         onTabChange={setTab}
 *         open={open}
 *         onToggle={setOpen}
 *       >
 *         {tab === "tools" && <ToolsGrid />}
 *         {tab === "deal"  && <DealCard />}
 *       </ChatDrawer>
 *     }
 *     budgetTokens={200_000}
 *     onSubmit={(text) => send(text)}
 *   />
 *
 * The drawer is purely presentational and slot-driven — you decide what
 * each tab shows. Tab order in the numbered chips is the order you pass.
 */

export type ChatDrawerTab = {
  /** Stable id — used as the React key and as `activeTabId`. */
  id: string;
  /** Human label rendered on the chip. */
  label: string;
  /**
   * Optional override for the numbered prefix (defaults to position +1).
   * Set to `null` to hide the number entirely (e.g. for a context-specific
   * tab like the deal one in the screenshots).
   */
  number?: number | null;
};

export interface ChatDrawerProps {
  tabs: ChatDrawerTab[];
  activeTabId: string;
  onTabChange: (id: string) => void;
  /** Body open/closed. Default true. */
  open?: boolean;
  /** Called when the chevron is clicked. */
  onToggle?: (open: boolean) => void;
  /** Body content for the active tab. */
  children?: ReactNode;
  /** Min height of the body when open, in px. Default 140. */
  minBodyHeight?: number;
  className?: string;
}

export function ChatDrawer({
  tabs,
  activeTabId,
  onTabChange,
  open = true,
  onToggle,
  children,
  minBodyHeight = 140,
  className,
}: ChatDrawerProps) {
  const handleToggle = useCallback(() => {
    onToggle?.(!open);
  }, [onToggle, open]);

  return (
    <div className={className}>
      <div className="flex items-center gap-1.5 px-2.5 py-2">
        <div className="flex flex-wrap items-center gap-1.5">
          {tabs.map((tab, i) => {
            const active = tab.id === activeTabId;
            const number = tab.number === null ? null : tab.number ?? i + 1;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => onTabChange(tab.id)}
                className={[
                  "group inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[12px] font-medium transition",
                  active
                    ? "border-violet-500 bg-violet-500 text-white"
                    : "border-zinc-200 bg-transparent text-zinc-700 hover:border-zinc-300 hover:bg-zinc-50 dark:border-zinc-700 dark:text-zinc-300 dark:hover:border-zinc-600 dark:hover:bg-zinc-800",
                ].join(" ")}
                aria-pressed={active}
              >
                {number !== null && (
                  <span
                    className={[
                      "inline-flex h-4 w-4 items-center justify-center rounded-full text-[10px] font-semibold",
                      active
                        ? "bg-white/20 text-white"
                        : "bg-zinc-200 text-zinc-600 group-hover:bg-zinc-300 dark:bg-zinc-700 dark:text-zinc-300",
                    ].join(" ")}
                  >
                    {number}
                  </span>
                )}
                <span className="truncate max-w-[180px]">{tab.label}</span>
              </button>
            );
          })}
        </div>
        <button
          type="button"
          onClick={handleToggle}
          aria-label={open ? "Collapse drawer" : "Expand drawer"}
          aria-expanded={open}
          className="ml-auto inline-flex h-6 w-6 items-center justify-center rounded-full text-zinc-400 transition hover:bg-zinc-100 hover:text-zinc-700 dark:hover:bg-zinc-800 dark:hover:text-zinc-200"
        >
          <Icon
            name={open ? "chevron-down" : "chevron-up"}
            className="h-3.5 w-3.5"
          />
        </button>
      </div>

      {open && (
        <div
          className="px-2.5 pb-2.5"
          style={{ minHeight: minBodyHeight }}
        >
          {children}
        </div>
      )}
    </div>
  );
}

import { createContext, useContext } from "react";
import type { CodeEditorContextValue } from "./CodeEditor.types";

export const CodeEditorContext = createContext<CodeEditorContextValue | null>(null);

export function useCodeEditor(): CodeEditorContextValue {
  const ctx = useContext(CodeEditorContext);
  if (!ctx) {
    throw new Error("useCodeEditor must be used within a <CodeEditor> component");
  }
