      );
    }
    return lines;
  }, [lineNumbers, lineCount, activeLine, themeColors]);

  const containerStyle: React.CSSProperties = {
    backgroundColor: themeColors.background,
    color: themeColors.foreground,
    minHeight: _minHeight,
