} from "./ContextMenu.types";

import { useCallback, useEffect, useState, type ReactNode } from "react";
import type {
    ChartElement,
    CodeElement,
    Deck,
    DeckOp,
    ImageElement,
    ShapeElement,
    ShapeKind,
    Slide as SlideData,
    SlideElement,
    TableElement,
    TextElement,
} from "../../types";
import { resolveTheme } from "../../theme/theme-utils";
import { elementId } from "../../utils/ids";
import { useDeckState } from "../../hooks/use-deck-state";
import { chartStarterOption, type ChartKind } from "../../utils/chart-presets";
import { Slide } from "../Slide";
import { SlideRail } from "../SlideRail";
import { EditorToolbar } from "../EditorToolbar";
import { ElementInspector } from "../ElementInspector";
import { SpeakerNotes } from "../SpeakerNotes";
import { defaultElementRegistry } from "../../registry";

export interface DeckEditorProps {
    /** Controlled deck — pair with `onChange`. */
    value: Deck;
    onChange: (next: Deck) => void;
    /** Called after every mutation with the op that produced it — feed into AgentPanel / audit log. */
    onOp?: (op: DeckOp) => void;
    /** Called when the user clicks Present. The host decides how to open the SlideViewer. */
    onPresent?: () => void;
    /** Controlled selected slide id. Uncontrolled by default. */
    selectedSlideId?: string | null;
    onSelectedSlideChange?: (id: string | null) => void;
    /**
     * Renderer for chart / code / table / embed elements (the elements this
     * package doesn't render natively). Defaults to the built-in
     * `defaultElementRegistry` so the editor is full out of the box; pass your
     * own to override (it wins entirely). The optional-peer hosts (chart/code)
     * load fancy-echarts/fancy-code via guarded dynamic imports, so the base
     * bundle never statically requires them.
     */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** Hide the slide rail (e.g. for embedded use). */
    hideRail?: boolean;
    /** Hide the speaker notes panel. */
    hideNotes?: boolean;
    /** Hide the toolbar. */
    hideToolbar?: boolean;
    /** Hide the inspector. */
    hideInspector?: boolean;
    /** Optional extra content on the toolbar's trailing edge. */
    toolbarExtra?: ReactNode;
    className?: string;
}

/**
 * Full deck editor — toolbar + rail + canvas + inspector + speaker notes.
 *
 * Controlled (`value` + `onChange`). State is intentionally simple: deck
 * lives in the consumer, the editor just renders a view + dispatches ops.
 * The same `DeckOp` enum that the agent bridge speaks runs through here —
 * agents and humans drive identical mutations.
 */
export function DeckEditor({
    value,
    onChange,
    onOp,
    onPresent,
    selectedSlideId: controlledSlideId,
    onSelectedSlideChange,
    renderElement = defaultElementRegistry,
    hideRail = false,
    hideNotes = false,
    hideToolbar = false,
    hideInspector = false,
    toolbarExtra,
    className,
}: DeckEditorProps) {
    const deck = value;
    const ops = useDeckState({ value: deck, onChange, onOp });

    // Slide selection — controlled or internal.
    const [internalSlideId, setInternalSlideId] = useState<string | null>(deck.slides[0]?.id ?? null);
    const isControlled = controlledSlideId !== undefined;
    const slideId = isControlled ? controlledSlideId! : internalSlideId;
    const setSlideId = useCallback(
        (id: string | null) => {
            if (!isControlled) setInternalSlideId(id);
            onSelectedSlideChange?.(id);
        },
        [isControlled, onSelectedSlideChange],
    );

    // If the selected slide disappears (deletion / agent ops), fall back to the first slide.
    useEffect(() => {
        if (slideId && !deck.slides.some((s) => s.id === slideId)) {
            setSlideId(deck.slides[0]?.id ?? null);
        } else if (!slideId && deck.slides.length > 0) {
            setSlideId(deck.slides[0]!.id);
        }
    }, [deck.slides, slideId, setSlideId]);

    const slide: SlideData | undefined = deck.slides.find((s) => s.id === slideId);

    // Element selection — internal, resets on slide change.
    const [elementIdSelected, setElementIdSelected] = useState<string | null>(null);
    useEffect(() => {
        setElementIdSelected(null);
    }, [slideId]);

    const selectedElement = slide && elementIdSelected ? slide.elements.find((e) => e.id === elementIdSelected) ?? null : null;

    // ─── Toolbar insert handlers ───────────────────────────────────────────
    const insert = useCallback(
        (element: Omit<SlideElement, "id">) => {
            if (!slide) return;
            const id = ops.addElement(slide.id, { id: elementId(), ...element });
            setElementIdSelected(id);
        },
        [slide, ops],
    );

    const insertText = useCallback(
        () =>
            insert({
                type: "text",
                x: 0.1,
                y: 0.4,
                w: 0.8,
                h: 0.2,
                content: "Click to edit",
                format: "plain",
                style: { fontSize: 36, weight: "semibold", align: "center" },
            } as Omit<TextElement, "id">),
        [insert],
    );

    const insertImage = useCallback(
        () =>
            insert({
                type: "image",
                x: 0.25,
                y: 0.25,
                w: 0.5,
                h: 0.5,
                src: "https://placehold.co/600x400?text=Image",
                fit: "contain",
            } as Omit<ImageElement, "id">),
        [insert],
    );

    const insertShape = useCallback(
        (shape: ShapeKind) =>
            insert({
                type: "shape",
                shape,
                x: 0.3,
                y: 0.3,
                w: 0.4,
                h: 0.4,
                fill: shape === "line" || shape === "arrow" ? "none" : "rgba(139,92,246,0.15)",
                stroke: "#8b5cf6",
                strokeWidth: 2,
            } as Omit<ShapeElement, "id">),
        [insert],
    );

    const insertChart = useCallback(
        (kind: ChartKind = "bar") =>
            insert({
                type: "chart",
                x: 0.1,
                y: 0.2,
                w: 0.8,
                h: 0.6,
                option: chartStarterOption(kind),
            } as Omit<ChartElement, "id">),
        [insert],
    );

    const insertCode = useCallback(
        () =>
            insert({
                type: "code",
                x: 0.15,
                y: 0.2,
                w: 0.7,
                h: 0.6,
                code: "function hello() {\n  return \"world\";\n}\n",
                language: "typescript",
                codeTheme: "dark",
            } as Omit<CodeElement, "id">),
        [insert],
    );

    const insertTable = useCallback(
        () =>
            insert({
                type: "table",
                x: 0.15,
                y: 0.25,
                w: 0.7,
                h: 0.5,
                columns: [
                    { key: "name", label: "Name" },
                    { key: "value", label: "Value" },
                ],
                rows: [
                    { name: "Alpha", value: 12 },
                    { name: "Beta", value: 34 },
                    { name: "Gamma", value: 56 },
                ],
            } as Omit<TableElement, "id">),
        [insert],
    );

    return (
        <div
            className={`fs-editor flex h-full w-full flex-col bg-zinc-100 dark:bg-zinc-950 ${className ?? ""}`}
            data-fancy-slides-editor={deck.id}
        >
            {/* Top toolbar */}
            {!hideToolbar && (
                <EditorToolbar
                    title={deck.title}
                    onTitleChange={(t) => ops.setTitle(t)}
                    themeName={deck.theme.name}
                    onApplyTheme={(t) => ops.applyTheme(t)}
                    onInsertText={insertText}
                    onInsertImage={insertImage}
                    onInsertShape={insertShape}
                    onInsertChart={insertChart}
                    onInsertCode={insertCode}
                    onInsertTable={insertTable}
                    onPresent={onPresent}
                    disabled={!slide}
                    toolbarExtra={toolbarExtra}
                />
            )}

            {/* Main editing area */}
            <div className="flex min-h-0 flex-1">
                {/* Slide rail */}
                {!hideRail && (
                    <div className="w-56 shrink-0 overflow-y-auto border-r border-zinc-200 bg-white dark:border-zinc-800 dark:bg-zinc-950">
                        <SlideRail
                            slides={deck.slides}
                            selectedId={slideId}
                            theme={deck.theme}
                            onSelect={setSlideId}
                            onAdd={(after) => {
                                const id = ops.addSlide(after !== undefined ? after : deck.slides.length);
                                setSlideId(id);
                            }}
                            onDuplicate={(id) => {
                                const newId = ops.duplicateSlide(id);
                                setSlideId(newId);
                            }}
                            onRemove={(id) => ops.removeSlide(id)}
                            onReorder={(id, toIndex) => ops.reorderSlide(id, toIndex)}
                            renderElement={renderElement}
                        />
                    </div>
                )}

                {/* Canvas + notes */}
                <div className="flex min-w-0 flex-1 flex-col">
                    <div className="flex flex-1 items-center justify-center overflow-auto p-6">
                        {slide ? (
                            <div
                                className="rounded-lg shadow-xl"
                                style={{
                                    width: "min(96%, 1280px)",
                                    aspectRatio: String(resolveTheme(deck.theme).aspectRatio ?? 16 / 9),
                                    background: "white",
                                }}
                            >
                                <Slide
                                    slide={slide}
                                    theme={deck.theme}
                                    editing
                                    onElementContentChange={(eid, content) => ops.updateElement(slide.id, eid, { content, format: "markdown" } as Partial<TextElement>)}
                                    onElementSelect={setElementIdSelected}
                                    selectedElementId={elementIdSelected}
                                    onElementMove={(eid, x, y) => ops.moveElement(slide.id, eid, x, y)}
                                    onElementResize={(eid, patch) => ops.updateElement(slide.id, eid, patch as Partial<SlideElement>)}
                                    renderElement={renderElement}
                                />
                            </div>
                        ) : (
                            <div className="grid place-items-center rounded-lg border border-dashed border-zinc-300 bg-white px-12 py-24 text-sm text-zinc-500 dark:border-zinc-700 dark:bg-zinc-950">
                                Add a slide to start editing.
                            </div>
                        )}
                    </div>

                    {/* Speaker notes */}
                    {!hideNotes && slide && (
                        <SpeakerNotes notes={slide.notes} onChange={(n) => ops.setNotes(slide.id, n)} />
                    )}
                </div>

                {/* Inspector */}
                {!hideInspector && (
                    <div className="w-72 shrink-0 overflow-y-auto">
                        <ElementInspector
                            element={selectedElement}
                            slide={slide ?? null}
                            onPatch={(patch) => slide && elementIdSelected && ops.updateElement(slide.id, elementIdSelected, patch)}
                            onDelete={() => {
                                if (!slide || !elementIdSelected) return;
                                ops.removeElement(slide.id, elementIdSelected);
                                setElementIdSelected(null);
                            }}
                            onLockToggle={(locked) => slide && elementIdSelected && ops.updateElement(slide.id, elementIdSelected, { locked } as Partial<SlideElement>)}
                            onSetTransition={(transition) => slide && ops.setTransition(slide.id, transition)}
                            onSetBackground={(background) => slide && ops.setBackground(slide.id, background)}
                            onSetLayout={(layout) => slide && ops.setLayout(slide.id, layout)}
                            onSetAnimation={(animation) => slide && elementIdSelected && ops.setAnimation(slide.id, elementIdSelected, animation)}
                            onSetElementAnimation={(eid, animation) => slide && ops.setAnimation(slide.id, eid, animation)}
                        />
                    </div>
                )}
            </div>
        </div>
    );
}

import { type CSSProperties, useCallback, useEffect, useRef, useState } from "react";
import type { Point, Stroke } from "../../types";

export type DrawingProps = {
  strokes: Stroke[];
  onStrokeStart?: (stroke: Stroke) => void;
  onStrokePoint?: (id: string, point: Point) => void;
  onStrokeEnd?: (stroke: Stroke) => void;
  color?: string;
  size?: number;
  /** SVG canvas width. Optional — auto-measures the rendered element when omitted. */
  width?: number;
  /** SVG canvas height. Optional — auto-measures the rendered element when omitted. */
  height?: number;
  enabled?: boolean;
  className?: string;
  style?: CSSProperties;
};

/**
 * Drawing — freeform pen layer. Controlled: parent owns `strokes`.
 *
 * Coordinates are in screen pixels relative to the rendered SVG. By default
 * the component auto-measures itself with a ResizeObserver so width/height
 * always match the visible area, keeping user coords 1:1 with click position.
 *
 * Streams new strokes via the callbacks so apps can broadcast them as they
 * form (live multi-user pen view).
 */
export function Drawing({
  strokes,
  onStrokeStart,
  onStrokePoint,
  onStrokeEnd,
  color = "#111827",
  size = 2,
  width,
  height,
  enabled = true,
  className,
  style,
}: DrawingProps) {
  const [active, setActive] = useState<Stroke | null>(null);
  const [measured, setMeasured] = useState({ w: width ?? 0, h: height ?? 0 });
  const ref = useRef<SVGSVGElement>(null);

  // Auto-measure rendered size so coords map 1:1 to clicks regardless of
  // CSS sizing. Skipped when caller supplied explicit width AND height.
  useEffect(() => {
    if (width != null && height != null) return;
    const el = ref.current;
    if (!el) return;
    const update = () => {
      const r = el.getBoundingClientRect();
      setMeasured({ w: Math.max(1, Math.round(r.width)), h: Math.max(1, Math.round(r.height)) });
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, [width, height]);

  const w = width ?? measured.w;
  const h = height ?? measured.h;

  const localPoint = useCallback((e: React.PointerEvent | PointerEvent): Point => {
    const rect = ref.current?.getBoundingClientRect();
    return { x: e.clientX - (rect?.left ?? 0), y: e.clientY - (rect?.top ?? 0) };
  }, []);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (!enabled || e.button !== 0) return;
      e.preventDefault();
      const id = `s_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
      const stroke: Stroke = { id, points: [localPoint(e)], color, size };
      setActive(stroke);
      onStrokeStart?.(stroke);
      const target = e.currentTarget;
      target.setPointerCapture(e.pointerId);
      const move = (ev: PointerEvent) => {
        const p = localPoint(ev);
        setActive((prev) => (prev ? { ...prev, points: [...prev.points, p] } : prev));
        onStrokePoint?.(id, p);
      };
      const up = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        setActive((prev) => {
          if (prev) onStrokeEnd?.(prev);
          return null;
        });
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
    },
    [enabled, color, size, localPoint, onStrokeStart, onStrokePoint, onStrokeEnd],
  );

  const all = active ? [...strokes, active] : strokes;

  return (
    <svg
      ref={ref}
      className={className}
      style={{ pointerEvents: enabled ? "auto" : "none", ...style }}
      width={w || undefined}
      height={h || undefined}
      onPointerDown={onPointerDown}
    >
      {/* Transparent hit-target so empty SVG area catches pointer events. */}
      {enabled && w > 0 && h > 0 && (
        <rect x={0} y={0} width={w} height={h} fill="transparent" />
      )}
      {all.map((s) => (
        <path
          key={s.id}
          d={toPath(s.points)}
          fill="none"
          stroke={s.color ?? "#111827"}
          strokeWidth={s.size ?? 2}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      ))}
    </svg>
  );
}

function toPath(points: Point[]): string {
  if (!points.length) return "";
  return points.map((p, i) => `${i === 0 ? "M" : "L"}${p.x},${p.y}`).join(" ");
}

import { createContext, useContext } from "react";
import type { DropdownContextValue } from "./Dropdown.types";

export const DropdownContext = createContext<DropdownContextValue | null>(null);

export function useDropdown(): DropdownContextValue {
  const ctx = useContext(DropdownContext);
  if (!ctx) {
    throw new Error(
      "Dropdown compound components must be used within <Dropdown>",
    );
  }
  return ctx;
}

import { useMemo, useRef, useState } from "react";
import { DropdownContext } from "./Dropdown.context";
import { DropdownTrigger } from "./DropdownTrigger";
import { DropdownItems } from "./DropdownItems";
import { DropdownItem } from "./DropdownItem";
import { DropdownSeparator } from "./DropdownSeparator";
import type { DropdownProps } from "./Dropdown.types";

function DropdownRoot({
  children,
  placement = "bottom-start",
  offset = 4,
}: DropdownProps) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const anchorRef = useRef<HTMLElement>(null);

  const ctx = useMemo(
    () => ({ open, setOpen, anchorRef, activeIndex, setActiveIndex, placement, offset }),
    [open, anchorRef, activeIndex, placement, offset],
  );

  return (
    <DropdownContext.Provider value={ctx}>{children}</DropdownContext.Provider>
  );
}

export const Dropdown = Object.assign(DropdownRoot, {
  Trigger: DropdownTrigger,
  Items: DropdownItems,
  Item: DropdownItem,
  Separator: DropdownSeparator,
});

import type { ReactNode } from "react";
import type { Placement } from "../../utils/types";

export interface DropdownContextValue {
  open: boolean;
  setOpen: (open: boolean) => void;
  anchorRef: React.RefObject<HTMLElement | null>;
  activeIndex: number;
  setActiveIndex: (index: number) => void;
  placement: Placement;
  offset: number;
}

export interface DropdownProps {
  children: ReactNode;
  placement?: Placement;
  offset?: number;
}

export interface DropdownTriggerProps {
  children: ReactNode;
}

export interface DropdownItemsProps {
  children: ReactNode;
  className?: string;
}

export interface DropdownItemProps {
  children: ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  danger?: boolean;
  className?: string;
}

export interface DropdownSeparatorProps {
  className?: string;
}

import { cn } from "../../utils/cn";
import { useDropdown } from "./Dropdown.context";
import type { DropdownItemProps } from "./Dropdown.types";

export function DropdownItem({
  children,
  onClick,
  disabled = false,
  danger = false,
  className,
}: DropdownItemProps) {
  const { setOpen } = useDropdown();

  return (
    <button
      data-react-fancy-dropdown-item=""
      type="button"
      role="menuitem"
      disabled={disabled}
      aria-disabled={disabled}
      className={cn(
        "flex w-full items-center rounded-lg px-3 py-2 text-left text-sm transition-colors",
        danger
          ? "text-red-600 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-950"
          : "text-zinc-700 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800",
        disabled && "cursor-not-allowed opacity-50",
        className,
      )}
      onClick={() => {
        if (disabled) return;
        onClick?.();
        setOpen(false);
      }}
    >
      {children}
    </button>
  );
}

DropdownItem.displayName = "DropdownItem";

import { useCallback, useEffect, useRef } from "react";
import { cn } from "../../utils/cn";
import { Portal } from "../Portal";
import { useDropdown } from "./Dropdown.context";
import { useFloatingPosition } from "../../hooks/use-floating-position";
import { useOutsideClick } from "../../hooks/use-outside-click";
import { useEscapeKey } from "../../hooks/use-escape-key";
import { useAnimation } from "../../hooks/use-animation";
import type { DropdownItemsProps } from "./Dropdown.types";

export function DropdownItems({ children, className }: DropdownItemsProps) {
  const { open, setOpen, anchorRef, activeIndex, setActiveIndex, placement, offset } =
    useDropdown();
  const floatingRef = useRef<HTMLDivElement>(null);
  const outsideRef = useRef<HTMLDivElement>(null);

  const position = useFloatingPosition(anchorRef, floatingRef, {
    placement,
    offset,
    enabled: open,
  });

  const close = useCallback(() => {
    setOpen(false);
    setActiveIndex(-1);
  }, [setOpen, setActiveIndex]);

  useOutsideClick(outsideRef, close, open, anchorRef);
  useEscapeKey(close, open);

  const { mounted, className: animClass, ref: animRef } = useAnimation({
    open,
    enterClass: "fancy-scale-in",
    exitClass: "fancy-fade-out",
  });

  useEffect(() => {
    if (!open || !floatingRef.current) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      const items = floatingRef.current?.querySelectorAll<HTMLElement>(
        '[role="menuitem"]:not([aria-disabled="true"])',
      );
      if (!items?.length) return;

      if (e.key === "ArrowDown") {
        e.preventDefault();
        const next = activeIndex < items.length - 1 ? activeIndex + 1 : 0;
        setActiveIndex(next);
        items[next]?.focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        const prev = activeIndex > 0 ? activeIndex - 1 : items.length - 1;
        setActiveIndex(prev);
        items[prev]?.focus();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [open, activeIndex, setActiveIndex]);

  if (!mounted) return null;

  return (
    <Portal>
      <div
        ref={(node) => {
          outsideRef.current = node;
          floatingRef.current = node;
          (animRef as React.MutableRefObject<HTMLElement | null>).current = node;
        }}
        data-react-fancy-dropdown=""
        role="menu"
        className={cn(
          "fixed z-50 min-w-[8rem] rounded-xl border border-zinc-200 bg-white p-1 shadow-lg dark:border-zinc-700 dark:bg-zinc-900",
          animClass,
          className,
        )}
        style={{ left: position.x, top: position.y }}
      >
        {children}
      </div>
    </Portal>
  );
}

DropdownItems.displayName = "DropdownItems";

import { cn } from "../../utils/cn";
import type { DropdownSeparatorProps } from "./Dropdown.types";

export function DropdownSeparator({ className }: DropdownSeparatorProps) {
