}

DropdownSeparator.displayName = "DropdownSeparator";

import { useDropdown } from "./Dropdown.context";
import type { DropdownTriggerProps } from "./Dropdown.types";

export function DropdownTrigger({ children }: DropdownTriggerProps) {
  const { setOpen, open, anchorRef } = useDropdown();

  return (
    <span
      ref={anchorRef as React.RefObject<HTMLSpanElement>}
      data-react-fancy-dropdown-trigger=""
      className="inline-flex"
      onClick={() => setOpen(!open)}
      aria-expanded={open}
      aria-haspopup="menu"
    >
      {children}
    </span>
  );
}

DropdownTrigger.displayName = "DropdownTrigger";

export { Dropdown } from "./Dropdown";
export { useDropdown } from "./Dropdown.context";
export type {
  DropdownProps,
  DropdownTriggerProps,
  DropdownItemsProps,
  DropdownItemProps,
  DropdownSeparatorProps,
  DropdownContextValue,
} from "./Dropdown.types";

import React, { forwardRef, useMemo } from "react";
import type { EChartsOption } from "echarts";
import { useECharts } from "../hooks/use-echarts";
import type {
  EChartComponentProps,
  SeriesComponentProps,
  ChartDivProps,
} from "../types";

const DEFAULT_STYLE: React.CSSProperties = { width: "100%", height: 400 };

/** Base EChart component — accepts any ECharts option. */
const EChartBase = forwardRef<HTMLDivElement, EChartComponentProps>(
  (
    {
