export function Emoji({ name, emoji, tone, size = "md", className }: EmojiProps) {
  const base = emoji ?? (name ? resolve(name) : undefined);
  if (!base) return null;

  const resolved = tone ? applyTone(base, tone) : base;

  const sizeClass = {
    sm: "text-base",
    md: "text-2xl",
    lg: "text-4xl",
    xl: "text-6xl",
  }[size];

  return (
    <span
      role="img"
      aria-label={name ?? resolved}
      data-react-fancy-emoji=""
      className={cn("inline-block leading-none", sizeClass, className)}
    >
      {resolved}
    </span>
  );
}

import type { SkinTone } from "../../data/emoji-utils";

export interface EmojiProps {
  name?: string;
  emoji?: string;
  tone?: SkinTone;
  size?: "sm" | "md" | "lg" | "xl";
  className?: string;
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { cn } from "../../utils/cn";
import { useControllableState } from "../../hooks/use-controllable-state";
import { EMOJI_CATEGORY_ORDER, EMOJI_DATA, type EmojiCategoryKey, type EmojiEntry } from "../../data/emoji-data";
import { applyTone, SKIN_TONES, type SkinTone } from "../../data/emoji-utils";
import type { EmojiSelectProps } from "./EmojiSelect.types";

const TONE_STORAGE_KEY = "fancy:emoji-tone";
const LONG_PRESS_MS = 400;
const HOVER_INTENT_MS = 120;
const HOVER_LEAVE_GRACE_MS = 220;

type ToneTarget = {
  emoji: EmojiEntry;
  rect: { left: number; top: number; width: number };
};

// Deliberately no hover-capability gate. We use `pointerType` on pointer events so touch
// inputs never trigger the hover path (they go through long-press instead), and mouse/pen
// inputs always work regardless of what `(hover: hover)` resolves to in the current env.

function readStoredTone(): SkinTone | null {
  if (typeof window === "undefined") return null;
  try {
    const v = window.localStorage?.getItem(TONE_STORAGE_KEY);
    return (SKIN_TONES as readonly string[]).includes(v ?? "") ? (v as SkinTone) : null;
  } catch {
    return null;
  }
}

export function EmojiSelect({ value, defaultValue, onChange, placeholder = "Search emojis...", className }: EmojiSelectProps) {
  const [selected, setSelected] = useControllableState(value, defaultValue ?? "", onChange);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState<EmojiCategoryKey>("smileys");
  const [tone, setToneState] = useState<SkinTone | null>(() => readStoredTone());
  const [toneTarget, setToneTarget] = useState<ToneTarget | null>(null);
  const leaveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const setTone = useCallback((t: SkinTone | null) => {
    setToneState(t);
    if (typeof window === "undefined") return;
    try {
      if (t) window.localStorage?.setItem(TONE_STORAGE_KEY, t);
      else window.localStorage?.removeItem(TONE_STORAGE_KEY);
    } catch {}
  }, []);

  const filtered = useMemo(() => {
    if (!query) return null;
    const lower = query.toLowerCase();
    const hits: EmojiEntry[] = [];
    for (const group of Object.values(EMOJI_DATA)) {
      for (const e of group.emojis) {
        if (e.name.includes(lower)) hits.push(e);
      }
    }
    return hits;
  }, [query]);

  const closePicker = useCallback(() => setToneTarget(null), []);

  const openPicker = useCallback((target: ToneTarget) => {
    if (leaveTimer.current) {
      clearTimeout(leaveTimer.current);
      leaveTimer.current = null;
    }
    setToneTarget(target);
  }, []);

  const scheduleClose = useCallback(() => {
    if (leaveTimer.current) clearTimeout(leaveTimer.current);
    leaveTimer.current = setTimeout(closePicker, HOVER_LEAVE_GRACE_MS);
  }, [closePicker]);

  const cancelClose = useCallback(() => {
    if (leaveTimer.current) {
      clearTimeout(leaveTimer.current);
      leaveTimer.current = null;
    }
  }, []);

  const pick = (emoji: EmojiEntry) => {
    const char = emoji.skinTones && tone ? applyTone(emoji.char, tone) : emoji.char;
    setSelected(char);
    setOpen(false);
    setQuery("");
    closePicker();
  };

  const pickTone = (emoji: EmojiEntry, t: SkinTone) => {
    setTone(t);
    const char = applyTone(emoji.char, t);
    setSelected(char);
    setOpen(false);
    setQuery("");
    closePicker();
  };

  useEffect(() => {
    if (!open) closePicker();
  }, [open, closePicker]);

  return (
    <div className={cn("relative inline-block", className)} data-react-fancy-emoji-select="">
      <button
        type="button"
        className="flex items-center gap-2 rounded-lg border border-zinc-300 px-3 py-2 text-sm transition-[border-color,box-shadow] duration-150 dark:border-zinc-700 dark:bg-[#1e1e24]"
        onClick={() => setOpen((v) => !v)}
      >
        {selected ? <span className="text-xl">{selected}</span> : <span className="text-zinc-400">Pick emoji</span>}
      </button>

      {open && (
        <div className="absolute z-50 mt-1 w-80 rounded-lg border border-zinc-200 bg-white p-2 shadow-lg dark:border-zinc-700 dark:bg-zinc-800 fancy-fade-in">
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={placeholder}
            className="mb-2 w-full rounded-md border border-zinc-200 px-2 py-1 text-sm transition-[border-color,box-shadow] duration-150 dark:border-zinc-700 dark:bg-[#1e1e24] dark:text-zinc-100"
            autoFocus
          />

          {!query && (
            <div className="mb-2 flex gap-1 overflow-x-auto border-b border-zinc-100 pb-2 dark:border-zinc-700">
              {EMOJI_CATEGORY_ORDER.map((key) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setActiveCategory(key)}
                  className={cn(
                    "shrink-0 rounded p-1 text-lg hover:bg-zinc-100 dark:hover:bg-zinc-700",
                    activeCategory === key && "bg-zinc-100 dark:bg-zinc-700",
                  )}
                  aria-label={EMOJI_DATA[key].label}
                >
                  {EMOJI_DATA[key].icon}
                </button>
              ))}
            </div>
          )}

          <div className="max-h-64 overflow-y-auto">
            {query ? (
              <EmojiGrid
                emojis={filtered ?? []}
                tone={tone}
                openPicker={openPicker}
                scheduleClose={scheduleClose}
                cancelClose={cancelClose}
                onPick={pick}
              />
            ) : (
              <div>
                <div className="px-1 py-1 text-xs font-semibold uppercase text-zinc-500">
                  {EMOJI_DATA[activeCategory].label}
                </div>
                <EmojiGrid
                  emojis={EMOJI_DATA[activeCategory].emojis}
                  tone={tone}
                  openPicker={openPicker}
                  scheduleClose={scheduleClose}
                  cancelClose={cancelClose}
                  onPick={pick}
                />
              </div>
            )}
          </div>
        </div>
      )}

      {toneTarget && typeof document !== "undefined" &&
        createPortal(
          <TonePopover
            target={toneTarget}
            onPickBase={() => pick(toneTarget.emoji)}
            onPickTone={(t) => pickTone(toneTarget.emoji, t)}
            onMouseEnter={cancelClose}
            onMouseLeave={scheduleClose}
          />,
          document.body,
        )}
    </div>
  );
}

type GridProps = {
  emojis: EmojiEntry[];
  tone: SkinTone | null;
  openPicker: (target: ToneTarget) => void;
  scheduleClose: () => void;
  cancelClose: () => void;
  onPick: (emoji: EmojiEntry) => void;
};

function EmojiGrid({ emojis, tone, openPicker, scheduleClose, cancelClose, onPick }: GridProps) {
  return (
    <div className="grid grid-cols-8 gap-0.5">
      {emojis.map((emoji) => (
        <EmojiCell
          key={emoji.char}
          emoji={emoji}
          tone={tone}
          openPicker={openPicker}
          scheduleClose={scheduleClose}
          cancelClose={cancelClose}
          onPick={() => onPick(emoji)}
        />
      ))}
    </div>
  );
}

type CellProps = {
  emoji: EmojiEntry;
  tone: SkinTone | null;
  openPicker: (target: ToneTarget) => void;
  scheduleClose: () => void;
  cancelClose: () => void;
  onPick: () => void;
};

function EmojiCell({ emoji, tone, openPicker, scheduleClose, cancelClose, onPick }: CellProps) {
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hoverTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressed = useRef(false);

  const tonable = !!emoji.skinTones;
  const displayChar = tonable && tone ? applyTone(emoji.char, tone) : emoji.char;

  useEffect(() => () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
    if (hoverTimer.current) clearTimeout(hoverTimer.current);
  }, []);

  const triggerOpen = () => {
    const node = buttonRef.current;
    if (!node) return;
    const r = node.getBoundingClientRect();
    openPicker({ emoji, rect: { left: r.left, top: r.top, width: r.width } });
  };

  const handlePointerEnter = (e: React.PointerEvent) => {
    if (!tonable || e.pointerType === "touch") return;
    cancelClose();
    if (hoverTimer.current) clearTimeout(hoverTimer.current);
    hoverTimer.current = setTimeout(triggerOpen, HOVER_INTENT_MS);
  };

  const handlePointerLeave = (e: React.PointerEvent) => {
    if (e.pointerType === "touch") return;
    if (hoverTimer.current) {
      clearTimeout(hoverTimer.current);
      hoverTimer.current = null;
    }
    if (tonable) scheduleClose();
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!tonable || e.pointerType !== "touch") return;
    longPressed.current = false;
    longPressTimer.current = setTimeout(() => {
      longPressed.current = true;
      triggerOpen();
    }, LONG_PRESS_MS);
  };
  const handlePointerUp = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
    longPressTimer.current = null;
  };

  const handleClick = () => {
    if (longPressed.current) {
      longPressed.current = false;
      return;
    }
    onPick();
  };

  return (
    <button
      ref={buttonRef}
      type="button"
      onClick={handleClick}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      className="relative rounded p-1 text-xl hover:bg-zinc-100 dark:hover:bg-zinc-700"
      aria-label={emoji.name}
      title={emoji.name}
    >
      {displayChar}
      {tonable && (
        <span className="absolute right-0.5 bottom-0.5 h-1 w-1 rounded-full bg-amber-400" aria-hidden />
      )}
    </button>
  );
}

type PopoverProps = {
  target: ToneTarget;
  onPickBase: () => void;
  onPickTone: (tone: SkinTone) => void;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
};

function TonePopover({ target, onPickBase, onPickTone, onMouseEnter, onMouseLeave }: PopoverProps) {
  const { emoji, rect } = target;
  if (!emoji.skinTones) return null;

  const centerX = rect.left + rect.width / 2;
  const top = rect.top;
  const POPOVER_HEIGHT_APPROX = 44;
  const flipDown = top < POPOVER_HEIGHT_APPROX + 8;

  const style: React.CSSProperties = flipDown
    ? { position: "fixed", left: centerX, top: top + 32, transform: "translateX(-50%)" }
    : { position: "fixed", left: centerX, top: top - 4, transform: "translate(-50%, -100%)" };

  return (
    <div
      style={{ ...style, zIndex: 9999 }}
      className="flex gap-0.5 rounded-md border border-zinc-200 bg-white p-1 shadow-lg dark:border-zinc-700 dark:bg-zinc-800"
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      <button
        type="button"
        onClick={onPickBase}
        className="rounded p-1 text-lg hover:bg-zinc-100 dark:hover:bg-zinc-700"
        aria-label={`${emoji.name} (no tone)`}
      >
        {emoji.char}
      </button>
      {SKIN_TONES.map((t, i) => (
        <button
          key={t}
          type="button"
          onClick={() => onPickTone(t)}
          className="rounded p-1 text-lg hover:bg-zinc-100 dark:hover:bg-zinc-700"
          aria-label={`${emoji.name} ${t} skin tone`}
        >
          {emoji.skinTones![i]}
        </button>
      ))}
    </div>
  );
}

export interface EmojiSelectProps {
  value?: string;
  defaultValue?: string;
  onChange?: (emoji: string) => void;
  placeholder?: string;
  className?: string;
}

/**
 * Babylon engine adapter for `@particle-academy/fancy-3d`'s <Canvas>.
 *
 * Mounts a Babylon `Engine` + `Scene` + camera into a `<canvas>` element
 * overlaid on the Canvas DOM container, then exposes the live `Scene` via
 * `EngineHandle.root` so child components can register meshes alongside the
 * 2D node graph.
 *
 *   import { Canvas } from "@particle-academy/fancy-3d";
 *   import { babylonEngine } from "@particle-academy/fancy-3d-babylon/engine";
 *
 *   <Canvas engine={babylonEngine} style={{ height: 480 }} />
 */
import type { CanvasEngine, EngineHandle, ViewportState } from "@particle-academy/fancy-3d";

// Declare a CJS-style `require` so the dts compiler doesn't reject the lazy
// load below. Browsers don't have `require`, but this whole engine adapter
// only runs when a host bundler (vite/webpack) replaces the call with its own
// lazy-module shim, or under node-side SSR where the global exists.
declare const require: (specifier: string) => unknown;

export const babylonEngine: CanvasEngine = {
  name: "babylon",
  mount(host: HTMLElement, viewport: ViewportState): EngineHandle {
    // Lazy require so non-babylon Canvas users don't pay the parse cost.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const BABYLON: any = require("@babylonjs/core");

    const overlay = document.createElement("canvas");
    overlay.style.position = "absolute";
    overlay.style.inset = "0";
    overlay.style.width = "100%";
    overlay.style.height = "100%";
    overlay.style.pointerEvents = "none";
    overlay.dataset.fancy3dCanvasEngine = "babylon";
    host.appendChild(overlay);

    const engine = new BABYLON.Engine(overlay, true, { preserveDrawingBuffer: true, stencil: true });
    const scene = new BABYLON.Scene(engine);
    scene.clearColor = new BABYLON.Color4(0, 0, 0, 0);

    const camera = new BABYLON.ArcRotateCamera(
      "fancy3d-canvas-camera",
      Math.PI / 2,
      Math.PI / 2.5,
      8,
      BABYLON.Vector3.Zero(),
      scene,
    );
    camera.attachControl(overlay, false);
    new BABYLON.HemisphericLight("fancy3d-canvas-light", new BABYLON.Vector3(0, 1, 0), scene);

    const observer = engine.runRenderLoop(() => scene.render());

    function updateViewport(_v: ViewportState) {
      // Default: 6DoF camera owns view; 2D viewport changes are observed
      // but don't move the Babylon camera. Consumers can override by
      // attaching their own observers to the scene.
    }

    function dispose() {
      try { engine.stopRenderLoop(observer as any); } catch {}
      scene.dispose();
      engine.dispose();
      if (overlay.parentElement === host) host.removeChild(overlay);
    }

    return {
      name: "babylon",
      root: scene,
      updateViewport,
      dispose,
    };
  },
};

/**
 * three.js engine adapter for `@particle-academy/fancy-3d`'s <Canvas>.
 *
 * Mounts a three `WebGLRenderer` + `Scene` + camera into a `<canvas>` overlaid
 * on the Canvas DOM container, then exposes the live `Scene` via
 * `EngineHandle.root` so child components can register meshes alongside the 2D
 * node graph.
 *
 *   import { Canvas } from "@particle-academy/fancy-3d";
 *   import { threeEngine } from "@particle-academy/fancy-3d-three/engine";
 *
 *   <Canvas engine={threeEngine} style={{ height: 480 }} />
 */
import * as THREE from "three";
import type { CanvasEngine, EngineHandle, ViewportState } from "@particle-academy/fancy-3d";

export const threeEngine: CanvasEngine = {
  name: "three",
  mount(host: HTMLElement, _viewport: ViewportState): EngineHandle {
    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, preserveDrawingBuffer: true });
    renderer.setPixelRatio(window.devicePixelRatio || 1);
    const overlay = renderer.domElement;
    overlay.style.position = "absolute";
    overlay.style.inset = "0";
    overlay.style.width = "100%";
    overlay.style.height = "100%";
    overlay.style.pointerEvents = "none"; // the 2D node graph owns interaction
    overlay.dataset.fancy3dCanvasEngine = "three";
    host.appendChild(overlay);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(50, 1, 0.1, 1000);
    camera.position.set(0, 0, 8);
    camera.lookAt(0, 0, 0);

    const hemi = new THREE.HemisphereLight(0xb3c6ff, 0x1a1a2e, 1.0);
    scene.add(hemi);

    const resize = () => {
      const w = host.clientWidth || 1;
      const h = host.clientHeight || 1;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(host);

    let raf = 0;
    const loop = () => {
      raf = requestAnimationFrame(loop);
      renderer.render(scene, camera);
    };
    loop();

    function updateViewport(_v: ViewportState) {
      // The 3D camera owns its own view; 2D viewport changes are observed but
      // don't move the camera. Consumers can drive the camera off the scene.
    }

    function dispose() {
      cancelAnimationFrame(raf);
      ro.disconnect();
      renderer.dispose();
      if (overlay.parentElement === host) host.removeChild(overlay);
    }

    return {
      name: "three",
      root: scene,
      updateViewport,
      dispose,
    };
  },
};

import { useEffect, lazy, Suspense, type ComponentType, type ReactNode } from "react";
import { Toast } from "@particle-academy/react-fancy";

/**
 * fancy-screens is an OPTIONAL peer. Importing `ScreenSystem` statically
 * would put `@particle-academy/fancy-screens` in the base import graph, so
 * any bundler resolving `fancy-inertia` would hard-fail when it isn't
 * installed — even for consumers who only use `<FancyAppRoot withScreens={false}>`.
 * Load it lazily instead, and degrade to a passthrough if it's absent.
 */
const Passthrough = ({ children }: { children?: ReactNode }) => <>{children}</>;

const SCREENS_MISSING =
  "[fancy-inertia] `withScreens` is on but @particle-academy/fancy-screens is not available — rendering children without the ScreenSystem provider. Pass `withScreens={false}` to silence this.";

const ScreenSystemLazy = lazy<ComponentType<{ children?: ReactNode }>>(() =>
  import("@particle-academy/fancy-screens")
    .then((m) => {
      const Comp = (m as { ScreenSystem?: ComponentType<{ children?: ReactNode }> })?.ScreenSystem;
      // A bundler resolving an ABSENT optional peer can hand back an
      // export-less stub ({ default: undefined }) instead of rejecting — so a
      // reject-only `.catch` misses it and React.lazy gets `{ default: undefined }`
      // (React #306). Guard the resolved export, not just rejection.
      if (!Comp) {
        console.warn(SCREENS_MISSING);
        return { default: Passthrough };
      }
      return { default: Comp };
    })
    .catch((err) => {
      console.warn(SCREENS_MISSING, err);
      return { default: Passthrough };
    }),
);

export interface FancyAppRootProps {
  children: ReactNode;

  /** Toast position. Default `"bottom-right"`. */
  toastPosition?: "top-left" | "top-right" | "bottom-left" | "bottom-right";

  /**
   * Mount fancy-screens' `<Screen.System>` provider. Default `true`. Set
   * `false` if your app doesn't use fancy-screens — the optional peer is
   * never imported in that case.
   */
  withScreens?: boolean;

  /**
   * Auto-register echarts modules + built-in themes on mount. Default
   * `true`. Disable if you call `registerCharts(...)` yourself for
   * tree-shaking control, or if fancy-echarts isn't installed.
   */
  withECharts?: boolean;
}

/**
 * Composite top-level provider for the fancy UI set under Inertia.
 *
 * Mount once in your Inertia app entry, ABOVE the `<Inertia App>` outlet.
 * Subsequent page swaps preserve the providers — toasts survive
 * navigation, the screen registry persists, and echarts modules don't
 * have to re-register.
 *
 *   import { createInertiaApp } from "@inertiajs/react";
 *   import { FancyAppRoot } from "@particle-academy/fancy-inertia";
 *
 *   createInertiaApp({
 *     setup({ App, props, el }) {
 *       createRoot(el).render(
 *         <FancyAppRoot>
 *           <App {...props} />
 *         </FancyAppRoot>
 *       );
 *     },
 *   });
 *
 * `fancy-screens` and `fancy-echarts` are optional peers, loaded lazily
 * only when `withScreens` / `withECharts` are enabled — the base bundle
 * depends on nothing but `react-fancy`.
 */
export function FancyAppRoot({
  children,
  toastPosition = "bottom-right",
  withScreens = true,
  withECharts = true,
}: FancyAppRootProps) {
  useEffect(() => {
    if (!withECharts) return;
    let cancelled = false;
    void (async () => {
      try {
        const echarts = await import("@particle-academy/fancy-echarts");
        if (cancelled) return;
        echarts.registerAll?.();
        echarts.registerBuiltinThemes?.();
      } catch (err) {
        console.warn(
          "[fancy-inertia] `withECharts` is on but @particle-academy/fancy-echarts is not installed — skipping chart registration. Pass `withECharts={false}` to silence this.",
          err,
        );
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [withECharts]);

  const Inner = withScreens ? (
    <Suspense fallback={null}>
      <ScreenSystemLazy>{children}</ScreenSystemLazy>
    </Suspense>
  ) : (
    <>{children}</>
  );

  return <Toast.Provider position={toastPosition}>{Inner}</Toast.Provider>;
}

FancyAppRoot.displayName = "FancyAppRoot";

import {
  forwardRef,
  useCallback,
  useImperativeHandle,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { Button, Badge, Card, Separator } from "@particle-academy/react-fancy";
import { resolveSource } from "../diff/source";
import { mergeResult } from "../diff/merge";
import type {
  AcceptanceState,
  AcceptanceStatus,
  Diff,
  DiffSegment,
  Hunk,
} from "../diff/types";
import { emitHunkActivity } from "../activity";
import type {
  FancyDiffProps,
  DiffViewMode,
  MergedResult,
  HunkRenderArgs,
  ToolbarRenderArgs,
  GutterRenderArgs,
} from "./FancyDiff.types";

/** Imperative handle exposed via ref. */
export interface FancyDiffHandle {
  /** Compute the merged result from the current acceptance state. */
  getMergedResult: () => MergedResult;
  /** The resolved diffs (one per file). */
  getDiffs: () => Diff[];
  /** Current acceptance state. */
  getAcceptance: () => AcceptanceState;
}

const statusBadge: Record<AcceptanceStatus, { color: string; label: string }> = {
  accepted: { color: "emerald", label: "accepted" },
  rejected: { color: "rose", label: "rejected" },
  pending: { color: "amber", label: "pending" },
};

function cx(...parts: (string | false | undefined | null)[]): string {
  return parts.filter(Boolean).join(" ");
}

export const FancyDiff = forwardRef<FancyDiffHandle, FancyDiffProps>(
  function FancyDiff(props, ref) {
    const {
      source,
      value,
      onChange,
      defaultValue,
      defaultStatus = "pending",
      mode: modeProp,
      onModeChange,
      pendingMode = false,
      onProposal,
      onResult,
      renderHunk,
      renderToolbar,
      renderGutter,
      tokenizer,
      actor,
      activity,
      showToolbar = true,
      showGutter = true,
      className,
      theme = "auto",
      header,
    } = props;

    // Resolve source -> diffs. Memoized on identity of source + tokenizer.
    const diffs = useMemo(
      () => resolveSource(source, { tokenizer }),
      [source, tokenizer],
    );

    // Controlled / uncontrolled acceptance state.
    const [internal, setInternal] = useState<AcceptanceState>(
      () => defaultValue ?? {},
    );
    const acceptance = value ?? internal;

    // Controlled / uncontrolled view mode.
    const [internalMode, setInternalMode] = useState<DiffViewMode>(
      modeProp ?? "split",
    );
    const mode = modeProp ?? internalMode;
    const setMode = useCallback(
      (m: DiffViewMode) => {
        if (modeProp === undefined) setInternalMode(m);
        onModeChange?.(m);
      },
      [modeProp, onModeChange],
    );

    const allHunks = useMemo(() => {
      const list: { hunk: Hunk; fileIndex: number }[] = [];
      diffs.forEach((d, fi) =>
        d.hunks.forEach((h) => {
          if (h.type !== "equal") list.push({ hunk: h, fileIndex: fi });
        }),
      );
      return list;
    }, [diffs]);

    const statusOf = useCallback(
      (id: string): AcceptanceStatus => acceptance[id] ?? defaultStatus,
      [acceptance, defaultStatus],
    );

    const computeMerged = useCallback(
      (state: AcceptanceState): MergedResult => {
        const files = diffs.map((d) => ({
          meta: d.file,
          merged: mergeResult(d, state, { defaultStatus }),
        }));
        return { files, text: files[0]?.merged ?? "" };
      },
      [diffs, defaultStatus],
    );

    const apply = useCallback(
      (hunkId: string, status: AcceptanceStatus, action: string, fileIndex?: number) => {
        if (pendingMode) {
          onProposal?.({ hunkId, proposedStatus: status, actor });
        }
        const next: AcceptanceState = { ...acceptance, [hunkId]: status };

        emitHunkActivity({
          action: status === "accepted" ? "diff_accept_hunk" : "diff_reject_hunk",
          hunkId,
          fileId: fileIndex !== undefined ? diffs[fileIndex]?.file?.newPath : undefined,
          actor,
          emitter: activity,
        });

        if (value === undefined) setInternal(next);
        onChange?.(next, { hunkId, status, action });
        onResult?.(computeMerged(next));
      },
      [acceptance, pendingMode, onProposal, actor, activity, value, onChange, onResult, computeMerged, diffs],
    );

    const setAll = useCallback(
      (status: AcceptanceStatus, action: string) => {
        const next: AcceptanceState = { ...acceptance };
        for (const { hunk } of allHunks) next[hunk.id] = status;
        emitHunkActivity({
          action: status === "accepted" ? "diff_accept_all" : "diff_reject_all",
          actor,
          emitter: activity,
        });
        if (value === undefined) setInternal(next);
        onChange?.(next, { hunkId: "*", status, action });
        onResult?.(computeMerged(next));
      },
      [acceptance, allHunks, actor, activity, value, onChange, onResult, computeMerged],
    );

    useImperativeHandle(
      ref,
      () => ({
        getMergedResult: () => computeMerged(acceptance),
        getDiffs: () => diffs,
        getAcceptance: () => acceptance,
      }),
      [computeMerged, acceptance, diffs],
    );

    const counts = useMemo(() => {
      let accepted = 0;
      let rejected = 0;
      let pending = 0;
      for (const { hunk } of allHunks) {
        const s = statusOf(hunk.id);
        if (s === "accepted") accepted++;
        else if (s === "rejected") rejected++;
        else pending++;
      }
      return { total: allHunks.length, accepted, rejected, pending };
    }, [allHunks, statusOf]);

    // ---- Toolbar ----
    const defaultToolbar: ReactNode = showToolbar ? (
      <div
        data-fancy-diff-toolbar=""
        role="toolbar"
        aria-label="Diff actions"
        className="flex items-center gap-2 flex-wrap px-3 py-2"
      >
        <Badge color="zinc" variant="soft" size="sm">
          {counts.total} change{counts.total === 1 ? "" : "s"}
        </Badge>
        <Badge color="emerald" variant="soft" size="sm">
          {counts.accepted} accepted
        </Badge>
        <Badge color="amber" variant="soft" size="sm">
          {counts.pending} pending
        </Badge>
        <span className="flex-1" />
        <Button
          size="sm"
          variant="ghost"
          icon={mode === "split" ? "columns" : "list"}
          onClick={() => setMode(mode === "split" ? "inline" : "split")}
          data-fancy-diff-mode-toggle=""
        >
          {mode === "split" ? "Split" : "Inline"}
        </Button>
        <Separator orientation="vertical" className="h-5" />
        <Button
          size="sm"
          variant="ghost"
          icon="check"
          onClick={() => setAll("accepted", "accept-all")}
          data-fancy-diff-accept-all=""
        >
          Accept all
        </Button>
        <Button
          size="sm"
          variant="ghost"
          icon="x"
          onClick={() => setAll("rejected", "reject-all")}
          data-fancy-diff-reject-all=""
        >
          Reject all
        </Button>
      </div>
    ) : null;

    const toolbar: ReactNode = renderToolbar
      ? renderToolbar({
          acceptAll: () => setAll("accepted", "accept-all"),
          rejectAll: () => setAll("rejected", "reject-all"),
          counts,
          mode,
          setMode,
          defaultNode: defaultToolbar,
        })
      : defaultToolbar;

    const renderGutterCell = (args: GutterRenderArgs): ReactNode => {
      if (renderGutter) return renderGutter(args);
      return (
        <span className="select-none tabular-nums text-zinc-400 dark:text-zinc-600 text-[11px] pr-2 text-right inline-block min-w-[2.5rem]">
          {args.side === "after"
            ? args.afterLineNo ?? ""
            : args.beforeLineNo ?? args.afterLineNo ?? ""}
        </span>
      );
    };

    return (
      <Card
        variant="outlined"
        padding="none"
        className={cx(
          "fancy-diff overflow-hidden font-mono text-[13px]",
          theme === "dark" && "dark",
          className,
        )}
        data-fancy-diff=""
        data-fancy-diff-mode={mode}
      >
        {header}
        {toolbar}
        {(header || toolbar) && <Separator />}
        <div data-fancy-diff-body="" role="table" aria-label="Diff">
          {diffs.map((diff, fileIndex) => (
            <FileBlock
              key={fileIndex}
              diff={diff}
              fileIndex={fileIndex}
              mode={mode}
              statusOf={statusOf}
              pendingMode={pendingMode}
              showGutter={showGutter}
              renderGutterCell={renderGutterCell}
              renderHunk={renderHunk}
              accept={(id) => apply(id, "accepted", "accept", fileIndex)}
              reject={(id) => apply(id, "rejected", "reject", fileIndex)}
            />
          ))}
        </div>
      </Card>
    );
  },
);

interface FileBlockProps {
  diff: Diff;
  fileIndex: number;
  mode: DiffViewMode;
  statusOf: (id: string) => AcceptanceStatus;
  pendingMode: boolean;
  showGutter: boolean;
  renderGutterCell: (args: GutterRenderArgs) => ReactNode;
  renderHunk?: FancyDiffProps["renderHunk"];
  accept: (id: string) => void;
  reject: (id: string) => void;
}

function FileBlock({
  diff,
  fileIndex,
  mode,
  statusOf,
  pendingMode,
  showGutter,
  renderGutterCell,
  renderHunk,
  accept,
  reject,
}: FileBlockProps) {
  const label = diff.file?.newPath ?? diff.file?.oldPath;
  return (
    <div data-fancy-diff-file={fileIndex} role="rowgroup">
      {label && (
        <div className="flex items-center gap-2 px-3 py-1.5 bg-zinc-50 dark:bg-zinc-800/60 border-b border-zinc-200 dark:border-zinc-700 text-xs">
          <span className="font-semibold text-zinc-700 dark:text-zinc-300">{label}</span>
          {diff.file?.partial && (
            <Badge color="amber" variant="soft" size="sm" title="Unified diff: only changed hunks + context are present">
              partial
            </Badge>
          )}
        </div>
      )}
      {diff.hunks.map((hunk) => {
        const status = statusOf(hunk.id);
        const defaultNode = (
          <HunkRow
            hunk={hunk}
            mode={mode}
            status={status}
            pendingMode={pendingMode}
            showGutter={showGutter}
            renderGutterCell={renderGutterCell}
            accept={() => accept(hunk.id)}
            reject={() => reject(hunk.id)}
          />
        );
        if (renderHunk && hunk.type !== "equal") {
          const args: HunkRenderArgs = {
            hunk,
            fileIndex,
            status,
            mode,
            pending: pendingMode && status === "pending",
            accept: () => accept(hunk.id),
            reject: () => reject(hunk.id),
            defaultNode,
          };
          const custom = renderHunk(args);
          return <div key={hunk.id}>{custom ?? defaultNode}</div>;
        }
        return <div key={hunk.id}>{defaultNode}</div>;
      })}
    </div>
  );
}

interface HunkRowProps {
  hunk: Hunk;
  mode: DiffViewMode;
  status: AcceptanceStatus;
  pendingMode: boolean;
  showGutter: boolean;
  renderGutterCell: (args: GutterRenderArgs) => ReactNode;
  accept: () => void;
  reject: () => void;
}

const sideBg: Record<string, string> = {
  add: "bg-emerald-50 dark:bg-emerald-950/30",
  remove: "bg-rose-50 dark:bg-rose-950/30",
  replaceBefore: "bg-rose-50 dark:bg-rose-950/30",
  replaceAfter: "bg-emerald-50 dark:bg-emerald-950/30",
};

function HunkRow({
  hunk,
  mode,
  status,
  pendingMode,
  showGutter,
  renderGutterCell,
  accept,
  reject,
}: HunkRowProps) {
  const isChange = hunk.type !== "equal";
  const dimmed = isChange && status === "rejected";

  return (
    <div
      data-fancy-diff-hunk={hunk.id}
      data-fancy-diff-hunk-type={hunk.type}
      data-fancy-diff-hunk-status={isChange ? status : undefined}
      role="row"
      className={cx(
        "group relative",
        dimmed && "opacity-50",
        isChange && "border-l-2",
        isChange && status === "accepted" && "border-emerald-400",
        isChange && status === "rejected" && "border-rose-300",
        isChange && status === "pending" && "border-amber-300",
        !isChange && "border-l-2 border-transparent",
      )}
    >
      {mode === "split" && hunk.type === "replace" ? (
        <SplitReplace hunk={hunk} showGutter={showGutter} renderGutterCell={renderGutterCell} />
      ) : mode === "split" ? (
        <SplitSimple hunk={hunk} showGutter={showGutter} renderGutterCell={renderGutterCell} />
      ) : (
        <Inline hunk={hunk} showGutter={showGutter} renderGutterCell={renderGutterCell} />
      )}

      {isChange && (
        <div
          data-fancy-diff-hunk-actions=""
          className="absolute right-1.5 top-1/2 -translate-y-1/2 flex gap-1 opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-opacity"
        >
          <Button
            size="xs"
            variant="circle"
            icon="check"
            color={status === "accepted" ? "emerald" : undefined}
            checked={status === "accepted"}
            aria-label={pendingMode ? "Propose accept" : "Accept change"}
            title={pendingMode ? "Propose accept" : "Accept change"}
            onClick={accept}
            data-fancy-diff-accept={hunk.id}
          />
          <Button
            size="xs"
            variant="circle"
            icon="x"
            warn={status === "rejected"}
            aria-label={pendingMode ? "Propose reject" : "Reject change"}
            title={pendingMode ? "Propose reject" : "Reject change"}
            onClick={reject}
            data-fancy-diff-reject={hunk.id}
          />
        </div>
      )}
    </div>
  );
}

function gutterArgs(
  side: "before" | "after" | "both",
  beforeLineNo?: number,
  afterLineNo?: number,
): GutterRenderArgs {
  return { side, beforeLineNo, afterLineNo };
}

/** Split view for add/remove/equal hunks (no intra-line segments). */
function SplitSimple({
  hunk,
  showGutter,
  renderGutterCell,
}: {
  hunk: Hunk;
  showGutter: boolean;
  renderGutterCell: (a: GutterRenderArgs) => ReactNode;
}) {
  return (
    <>
      {hunk.lines.map((line, i) => {
        const leftText = line.side === "before" || line.side === "both" ? line.text : "";
        const rightText = line.side === "after" || line.side === "both" ? line.text : "";
        const leftFilled = line.side === "before" || line.side === "both";
        const rightFilled = line.side === "after" || line.side === "both";
        return (
          <div key={i} className="grid grid-cols-2" role="row">
            <div
              className={cx(
                "flex items-start gap-1 px-2 py-0.5 whitespace-pre-wrap break-words min-h-[1.4em] border-r border-zinc-100 dark:border-zinc-800",
                line.side === "before" && sideBg.remove,
              )}
            >
              {showGutter && renderGutterCell(gutterArgs("before", line.beforeLineNo))}
              {line.side === "before" && <span className="text-rose-500 select-none">-</span>}
              <span>{leftFilled ? leftText : ""}</span>
            </div>
            <div
              className={cx(
                "flex items-start gap-1 px-2 py-0.5 whitespace-pre-wrap break-words min-h-[1.4em]",
                line.side === "after" && sideBg.add,
              )}
            >
              {showGutter && renderGutterCell(gutterArgs("after", undefined, line.afterLineNo))}
              {line.side === "after" && <span className="text-emerald-500 select-none">+</span>}
              <span>{rightFilled ? rightText : ""}</span>
            </div>
          </div>
        );
      })}
    </>
  );
}

/** Split view for replace hunks, pairing before/after rows with segment highlights. */
function SplitReplace({
  hunk,
  showGutter,
  renderGutterCell,
}: {
  hunk: Hunk;
  showGutter: boolean;
  renderGutterCell: (a: GutterRenderArgs) => ReactNode;
}) {
  const before = hunk.lines.filter((l) => l.side === "before");
  const after = hunk.lines.filter((l) => l.side === "after");
  const rows = Math.max(before.length, after.length);
  const segs = hunk.segments ?? [];

  return (
    <>
      {Array.from({ length: rows }).map((_, i) => {
        const b = before[i];
        const a = after[i];
        const seg = segs.find((s) => s.pairIndex === i);
        return (
          <div key={i} className="grid grid-cols-2" role="row">
            <div
              className={cx(
                "flex items-start gap-1 px-2 py-0.5 whitespace-pre-wrap break-words min-h-[1.4em] border-r border-zinc-100 dark:border-zinc-800",
                b && sideBg.replaceBefore,
              )}
            >
              {showGutter && renderGutterCell(gutterArgs("before", b?.beforeLineNo))}
              {b && <span className="text-rose-500 select-none">-</span>}
              <span>{b ? (seg ? renderSegments(seg.before, "remove") : b.text) : ""}</span>
            </div>
            <div
              className={cx(
                "flex items-start gap-1 px-2 py-0.5 whitespace-pre-wrap break-words min-h-[1.4em]",
                a && sideBg.replaceAfter,
              )}
            >
              {showGutter && renderGutterCell(gutterArgs("after", undefined, a?.afterLineNo))}
              {a && <span className="text-emerald-500 select-none">+</span>}
              <span>{a ? (seg ? renderSegments(seg.after, "add") : a.text) : ""}</span>
            </div>
          </div>
        );
      })}
    </>
  );
}

/** Inline (single-column) view. */
function Inline({
  hunk,
  showGutter,
  renderGutterCell,
}: {
  hunk: Hunk;
  showGutter: boolean;
  renderGutterCell: (a: GutterRenderArgs) => ReactNode;
}) {
  const segs = hunk.segments ?? [];
  let removeIdx = 0;
  let addIdx = 0;
  return (
    <>
      {hunk.lines.map((line, i) => {
        const sign = line.side === "before" ? "-" : line.side === "after" ? "+" : " ";
        const bg =
          line.side === "before"
            ? sideBg.remove
            : line.side === "after"
              ? sideBg.add
              : "";
        let content: ReactNode = line.text;
        if (hunk.type === "replace") {
          if (line.side === "before") {
            const seg = segs.find((s) => s.pairIndex === removeIdx++);
            if (seg) content = renderSegments(seg.before, "remove");
          } else if (line.side === "after") {
            const seg = segs.find((s) => s.pairIndex === addIdx++);
            if (seg) content = renderSegments(seg.after, "add");
          }
        }
        return (
          <div
            key={i}
            role="row"
            className={cx(
              "flex items-start gap-1 px-2 py-0.5 whitespace-pre-wrap break-words min-h-[1.4em]",
              bg,
            )}
          >
            {showGutter &&
              renderGutterCell(
                gutterArgs(line.side, line.beforeLineNo, line.afterLineNo),
              )}
            <span
              className={cx(
                "select-none w-3",
                sign === "-" && "text-rose-500",
                sign === "+" && "text-emerald-500",
              )}
            >
              {sign}
            </span>
            <span>{content}</span>
          </div>
        );
      })}
    </>
  );
}

/** Render intra-line segments with add/remove emphasis. */
function renderSegments(segments: DiffSegment[], emphasis: "add" | "remove"): ReactNode {
  return segments.map((s, i) => {
    if (s.op === "equal") return <span key={i}>{s.text}</span>;
    const cls =
      emphasis === "add"
        ? "bg-emerald-200/70 dark:bg-emerald-700/50 rounded-sm"
        : "bg-rose-200/70 dark:bg-rose-700/50 rounded-sm";
    return (
      <span key={i} className={cls} data-fancy-diff-seg={s.op}>
        {s.text}
      </span>
    );
  });
}

import { type CSSProperties, type ReactNode, useCallback, useEffect, useState } from "react";
import { StickyNote as FancyStickyNote } from "@particle-academy/react-fancy";
import type { StickyNoteItem } from "../../types";

export type StickyNoteProps = {
  item: StickyNoteItem;
  onChange?: (next: StickyNoteItem) => void;
  onSelect?: (id: string) => void;
  selected?: boolean;
  readOnly?: boolean;
  /** Smallest size resize will allow (default 80×60). */
  minWidth?: number;
  minHeight?: number;
  className?: string;
  style?: CSSProperties;
  /** When provided, replaces the default editable note body. */
  children?: ReactNode;
};

/**
 * StickyNote — draggable, resizable board note.
 *
 * The note's paper look and inline text editing come from react-fancy's shared
 * `<StickyNote>` primitive; this wrapper owns the board concerns: absolute
 * positioning, drag-to-move, corner resize, and selection.
 *
 * Interactions:
 *   • Drag anywhere on the note to move it.
 *   • Click (without dragging) — or double-click — to edit; click outside to commit.
 *   • Drag the bottom-right corner handle to resize.
 *
 * Controlled via `item` + `onChange`.
 */
export function StickyNote({
  item,
  onChange,
  onSelect,
  selected,
  readOnly,
  minWidth = 80,
  minHeight = 60,
  className,
  style,
  children,
}: StickyNoteProps) {
  const [editing, setEditing] = useState(false);
  const [dragging, setDragging] = useState(false);
  const [resizing, setResizing] = useState(false);

  // Deselected by parent → leave edit mode.
  useEffect(() => {
    if (!selected && editing) setEditing(false);
  }, [selected, editing]);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (readOnly || !onChange || editing) return;
      if (e.button !== 0 || e.altKey) return;
      onSelect?.(item.id);
      const start = { x: e.clientX, y: e.clientY };
      const origin = { x: item.x, y: item.y };
      const target = e.currentTarget;
      target.setPointerCapture(e.pointerId);
      let moved = false;
      const move = (ev: PointerEvent) => {
        if (!moved && Math.hypot(ev.clientX - start.x, ev.clientY - start.y) < 4) return;
        if (!moved) setDragging(true);
        moved = true;
        onChange({ ...item, x: origin.x + ev.clientX - start.x, y: origin.y + ev.clientY - start.y });
      };
      const up = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        setDragging(false);
        // Click without drag → enter edit mode (more discoverable than double-click).
        if (!moved && !readOnly) setEditing(true);
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
    },
    [item, onChange, onSelect, readOnly, editing],
  );

  const onResizePointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (readOnly || !onChange) return;
      e.stopPropagation();
      e.preventDefault();
      const start = { x: e.clientX, y: e.clientY };
      const origin = { w: item.width, h: item.height };
      const target = e.currentTarget;
      target.setPointerCapture(e.pointerId);
      setResizing(true);
      const move = (ev: PointerEvent) => {
        const w = Math.max(minWidth, origin.w + ev.clientX - start.x);
        const h = Math.max(minHeight, origin.h + ev.clientY - start.y);
        onChange({ ...item, width: w, height: h });
      };
      const up = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        setResizing(false);
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
    },
    [item, onChange, readOnly, minWidth, minHeight],
  );

  return (
    <div
      className={[
        "fw-item fw-sticky",
        dragging ? "fw-item--dragging" : "",
        resizing ? "fw-item--resizing" : "",
        selected ? "fw-sticky--selected" : "",
        editing ? "fw-sticky--editing" : "",
        className ?? "",
      ]
        .filter(Boolean)
        .join(" ")}
      style={{ left: item.x, top: item.y, width: item.width, height: item.height, zIndex: item.z, ...style }}
      onPointerDown={onPointerDown}
      onDoubleClick={() => {
        if (!readOnly) setEditing(true);
      }}
    >
      <FancyStickyNote
        className="h-full w-full"
        color={item.color ?? "yellow"}
        value={item.text}
        editable={!readOnly && editing}
        autoFocus
        onChange={(text) => onChange?.({ ...item, text })}
      >
        {children}
      </FancyStickyNote>
      {!readOnly && onChange && (
        <div className="fw-sticky__resize" onPointerDown={onResizePointerDown} aria-label="Resize note" />
      )}
    </div>
  );
}

import { forwardRef, useLayoutEffect, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import type { FauxClientProps } from "./FauxClient.types";

const DOT_COLORS = ["bg-rose-300", "bg-amber-300", "bg-green-300"];

/**
 * A frame that mimics a browser window or device, rendering **real UI** inside.
 * With a logical `width` + `scale="fit"` it renders a full-size page/app and
 * scales it down to fit any container (live thumbnails, device mockups) — the
 * content is real and interactive, just zoomed.
 *
 * Omit `width` for chrome around natural-size content (e.g. a code/preview card).
 */
export const FauxClient = forwardRef<HTMLDivElement, FauxClientProps>(
  (
    {
      variant = "browser",
      url,
      meta,
      dots = true,
      width,
      scale = "fit",
      className,
      barClassName,
      bodyClassName,
      children,
      ...rest
    },
    ref,
  ) => {
    const scaled = typeof width === "number";
    const viewportRef = useRef<HTMLDivElement>(null);
    const stageRef = useRef<HTMLDivElement>(null);
    const [s, setS] = useState(typeof scale === "number" ? scale : 1);
    const [contentHeight, setContentHeight] = useState<number | undefined>(undefined);

    useLayoutEffect(() => {
      if (!scaled) return;
      const viewport = viewportRef.current;
      const stage = stageRef.current;
      if (!viewport || !stage) return;
      if (typeof ResizeObserver === "undefined") return;

      const measure = () => {
        const avail = viewport.clientWidth;
        const next = scale === "fit" ? (width && width > 0 ? avail / width : 1) : scale;
        // offsetHeight is the pre-transform layout height (CSS transforms don't affect it).
        const naturalHeight = stage.offsetHeight;
        setS(next);
        setContentHeight(naturalHeight * next);
      };

      measure();
      const ro = new ResizeObserver(measure);
      ro.observe(viewport);
      ro.observe(stage);
      return () => ro.disconnect();
    }, [scaled, scale, width]);

    const isBrowser = variant === "browser";
    const isDevice = variant === "device";

    return (
      <div
        ref={ref}
        data-react-fancy-faux-client=""
        className={cn(
          "overflow-hidden bg-white dark:bg-zinc-900",
          isBrowser && "rounded-2xl border border-zinc-200 shadow-xl dark:border-zinc-800",
          isDevice && "rounded-[2rem] border-[10px] border-zinc-800 shadow-2xl dark:border-zinc-700",
          variant === "bare" && "rounded-lg border border-zinc-200 dark:border-zinc-800",
          className,
        )}
        {...rest}
      >
        {isBrowser && (
          <div
            className={cn(
              "flex items-center gap-2 border-b border-zinc-200 bg-zinc-50 px-3.5 py-2.5 font-mono text-[11.5px] text-zinc-500 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-400",
              barClassName,
            )}
          >
            {dots && (
              <div className="mr-1.5 flex gap-[5px]">
                {DOT_COLORS.map((color, i) => (
                  <span key={i} className={cn("h-[9px] w-[9px] rounded-full", color)} />
                ))}
              </div>
            )}
            {url != null && <span className="min-w-0 flex-1 truncate">{url}</span>}
            {meta != null && <span className="shrink-0 text-zinc-400 dark:text-zinc-500">{meta}</span>}
          </div>
        )}

        <div
          ref={viewportRef}
          className={cn("relative overflow-hidden", bodyClassName)}
          style={scaled ? { height: contentHeight } : undefined}
        >
          {scaled ? (
            <div
              ref={stageRef}
              className="absolute left-0 top-0 origin-top-left"
              style={{ width, transform: `scale(${s})` }}
            >
              {children}
            </div>
          ) : (
            children
          )}
        </div>
      </div>
    );
  },
);

FauxClient.displayName = "FauxClient";

import type { HTMLAttributes, ReactNode } from "react";

export interface FauxClientProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** Chrome style: a browser window, a device bezel, or no chrome. */
  variant?: "browser" | "device" | "bare";
  /** Address-bar / title text (browser variant). */
  url?: ReactNode;
  /** Right-aligned meta text in the bar (browser variant). */
  meta?: ReactNode;
  /** Show the macOS traffic-light dots (browser variant). */
  dots?: boolean;
  /**
   * Logical content width in px. When set, children render at this width and are
   * scaled to fit (see {@link FauxClientProps.scale}) — for downscaled previews
   * of full pages/apps. Omit to render children at natural size (chrome only).
   */
  width?: number;
  /** `"fit"` scales the logical {@link FauxClientProps.width} to the frame; a number is a fixed scale. */
  scale?: number | "fit";
  className?: string;
  /** Class for the browser bar. */
  barClassName?: string;
  /** Class for the content viewport. */
  bodyClassName?: string;
  children?: ReactNode;
}

