          <button
            type="button"
            onClick={() => removeFile(i)}
            className="shrink-0 text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-300"
            aria-label={`Remove ${file.name}`}
          >
            <X size={14} />
          </button>
        </li>
      ))}
    </ul>
  );
}

