import { Popover } from "../Popover";
import { Button } from "../Button";

/**
 * ReasonTag — wraps any value with a small affordance that reveals the
 * agent's reasoning, sources, and confidence on hover or click.
 *
 *   <ReasonTag
 *     value="$1.4M"
 *     reason="Projected Q3 ARR after stacking renewals."
 *     confidence={0.91}
 *     sources={[{ label: "Q2 actuals · CRM export" }]}
 *     by="Forecaster"
 *   />
 *
 * Three visual styles:
 *   • "dot"       — value with a tiny coloured dot (default, subtle)
 *   • "underline" — dotted underline + trailing "?"
 *   • "chip"      — full coloured pill (loud)
 *
 * Confidence drives the colour via three tiers (high / medium / low),
 * so a quick visual scan tells the human which suggestions deserve a
 * second look without opening any tooltips.
 *
 * `pinned` swaps the popover for an inline annotation slot — useful
 * when explainability should always be visible, not buried in a hover.
 */
export type ReasonTagSource = { label: string; href?: string };

export type ReasonTagTheme = "dot" | "underline" | "chip";

export interface ReasonTagProps {
  /** The value the tag wraps — usually a number, label, or short phrase. */
  value: React.ReactNode;
  /** Free-text rationale shown in the popover / inline annotation. */
  reason: string;
  /** 0..1 confidence. Drives the tier colour. Defaults to 1. */
  confidence?: number;
  /** Optional list of sources (label + optional href). */
  sources?: ReasonTagSource[];
  /** Optional author / agent name shown in the popover header. */
  by?: string;
  /** Visual treatment for the trigger. */
  theme?: ReasonTagTheme;
  /**
   * When true, the popover is replaced with an always-visible inline
   * annotation below the value.
   */
  pinned?: boolean;
  /** Called when the user hits the "ask follow-up" action. */
  onFollowUp?: () => void;
  /** Optional className applied to the trigger element. */
  className?: string;
}

const CONFIDENCE_TIERS: Array<{ min: number; color: string; label: string }> = [
  { min: 0.85, color: "#10b981", label: "high" },
  { min: 0.6, color: "#f59e0b", label: "medium" },
  { min: 0, color: "#ef4444", label: "low" },
];

function tier(c: number) {
  return CONFIDENCE_TIERS.find((t) => c >= t.min) ?? CONFIDENCE_TIERS[2];
}

export function ReasonTag({
  value,
  reason,
  confidence = 1,
  sources = [],
  by,
  theme = "dot",
  pinned = false,
  onFollowUp,
  className,
}: ReasonTagProps) {
  const t = tier(confidence);

  const trigger =
    theme === "chip" ? (
      <span
        className={`inline-flex cursor-help items-center gap-1 rounded-full px-2 py-0.5 text-[12px] font-medium ${className ?? ""}`}
        style={{ backgroundColor: t.color + "22", color: t.color }}
      >
        <span
          className="h-1.5 w-1.5 rounded-full"
          style={{ backgroundColor: t.color }}
        />
        {value}
        <span className="text-[10px] opacity-70">?</span>
      </span>
    ) : theme === "underline" ? (
      <span
        className={`cursor-help underline decoration-dotted underline-offset-2 ${className ?? ""}`}
        style={{ textDecorationColor: t.color }}
      >
        {value}
        <span
          className="ml-0.5 font-mono text-[10px]"
          style={{ color: t.color }}
        >
          ?
        </span>
      </span>
    ) : (
      <span className={`inline-flex cursor-help items-baseline gap-1 ${className ?? ""}`}>
        <span className="font-medium">{value}</span>
        <span
          className="inline-block h-1.5 w-1.5 rounded-full align-middle"
          style={{ backgroundColor: t.color }}
          title="reason available"
        />
      </span>
    );

  if (pinned) {
    return (
      <span className="inline-flex flex-col items-start gap-0.5 align-top">
        {trigger}
        <span
          className="block max-w-[280px] rounded border-l-2 pl-2 text-[11px] leading-snug text-zinc-600 dark:text-zinc-300"
          style={{ borderColor: t.color }}
        >
          {reason}
        </span>
      </span>
    );
  }

  return (
    <Popover hover>
      <Popover.Trigger>{trigger}</Popover.Trigger>
      <Popover.Content>
        <div className="w-72 space-y-2 text-sm">
          <div className="flex items-baseline gap-2">
            <span
              className="text-[10px] font-semibold uppercase tracking-wider"
              style={{ color: t.color }}
            >
              {t.label} confidence · {(confidence * 100).toFixed(0)}%
            </span>
            {by && (
              <span className="ml-auto font-mono text-[10px] text-zinc-400">
                @{by}
              </span>
            )}
          </div>
          <p className="text-[13px] leading-snug text-zinc-700 dark:text-zinc-200">
            {reason}
          </p>
          {sources.length > 0 && (
            <div>
              <div className="text-[10px] uppercase tracking-wider text-zinc-400">
                sources
              </div>
              <ul className="mt-0.5 space-y-0.5 text-[12px]">
                {sources.map((s, i) => (
                  <li key={i}>
                    {s.href ? (
                      <a className="text-violet-600 hover:underline" href={s.href}>
                        {s.label}
                      </a>
                    ) : (
                      <span className="text-zinc-600 dark:text-zinc-300">
                        {s.label}
                      </span>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          )}
          {onFollowUp && (
            <div className="flex justify-end pt-1">
              <Button size="sm" variant="ghost" onClick={onFollowUp}>
                ask follow-up
              </Button>
            </div>
          )}
        </div>
      </Popover.Content>
    </Popover>
  );
}

import type {
  ExecutorRegistry,
  FlowEdge,
  FlowGraph,
  FlowNode,
  NodeExecutor,
  RunEvent,
} from "../types";

export type RunOptions = {
  /** Stop the run after this many ms. Default: no timeout. */
  timeoutMs?: number;
  /** Abort signal — host can cancel the run. */
  signal?: AbortSignal;
  /** Initial inputs supplied to entry-point nodes (no incoming edges). */
  initialInputs?: Record<string, Record<string, unknown>>;
};

export type RunResult = {
  ok: boolean;
  /** Outputs collected per node, keyed by node id. */
  outputs: Record<string, unknown>;
  /** Error captured if any node threw. */
  error?: string;
};

/**
 * runFlow — topological execution of a FlowGraph against an ExecutorRegistry.
 *
 * Each node runs once, when all upstream nodes have produced outputs on the
 * connected ports. Decision nodes (or any executor that returns `{ branch:
 * 'true' }`) can short-circuit specific output ports — only edges leaving
 * an "active" port propagate to downstream nodes.
 *
 * Cycles are detected and abort the run with an error.
 *
 * The `onEvent` callback receives a stream of `RunEvent`s — wire it to a
 * status feed, log panel, or store.
 */
export async function runFlow(
  graph: FlowGraph,
  executors: ExecutorRegistry,
  onEvent: (event: RunEvent) => void = () => {},
  options: RunOptions = {},
): Promise<RunResult> {
  const { signal, initialInputs = {}, timeoutMs } = options;
  const outputs: Record<string, unknown> = {};
  const portValues = new Map<string, unknown>(); // key: `${nodeId}:${portId}`
  const completed = new Set<string>();
  const errors: string[] = [];

  // Topological order via Kahn's algorithm. We allow nodes to run as soon
  // as their incoming edges' source ports have produced values, so the
  // order here is just a deterministic baseline used for cycle detection.
  const order = topoSort(graph);
  if (order === null) {
    const msg = "Cycle detected in flow graph — aborting.";
    onEvent({ type: "run-error", error: msg });
    return { ok: false, outputs, error: msg };
  }

  const incomingByNode = indexIncoming(graph.edges);
  const timer = timeoutMs ? setTimeout(() => errors.push(`Run timed out after ${timeoutMs}ms`), timeoutMs) : null;

  onEvent({ type: "run-start" });

  try {
    for (const node of order) {
      if (signal?.aborted) throw new Error("aborted");
      if (errors.length) break;

      const incoming = incomingByNode.get(node.id) ?? [];

      // Skip nodes whose upstream wasn't activated (e.g. a Decision routed
      // to a different branch).
      if (incoming.length > 0) {
        const allActive = incoming.every((e) => portValues.has(`${e.source}:${e.sourceHandle ?? "out"}`));
        if (!allActive) {
          onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "skipped" });
          continue;
        }
      }

      // Note nodes are annotations — never executed.
      if (node.type === "note") {
        onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "annotation" });
        continue;
      }

      onEvent({ type: "node-status", nodeId: node.id, status: "running" });

      const inputs = collectInputs(node, incoming, portValues, initialInputs);
      const exec = pickExecutor(executors, node);
      if (!exec) {
        const msg = `No executor registered for kind=${node.type}`;
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }

      try {
        const result = await Promise.resolve(
          exec({
            node,
            inputs,
            abort: (reason) => { throw new Error(reason ?? "aborted"); },
            emit: onEvent,
          }),
        );
        outputs[node.id] = result;

        // Decide which output ports were activated. Three conventions:
        //  1) If result is `{ __port: "out", value: x }`, only that port emits.
        //  2) If result has `branch: <portId>`, only that port emits (decision sugar).
        //  3) Otherwise, the value is published on every declared output port.
        const activated = activatedPorts(node, result);
        for (const portId of activated.ports) {
          portValues.set(`${node.id}:${portId}`, activated.value);
          onEvent({ type: "node-output", nodeId: node.id, portId, value: activated.value });
        }
        completed.add(node.id);
        onEvent({ type: "node-status", nodeId: node.id, status: "done" });
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }
    }
  } finally {
    if (timer) clearTimeout(timer);
  }

  const ok = errors.length === 0;
  onEvent({ type: "run-end", ok });
  return ok ? { ok, outputs } : { ok, outputs, error: errors[0] };
}

function indexIncoming(edges: FlowEdge[]): Map<string, FlowEdge[]> {
  const map = new Map<string, FlowEdge[]>();
  for (const e of edges) {
    const list = map.get(e.target) ?? [];
    list.push(e);
    map.set(e.target, list);
  }
  return map;
}

function topoSort(graph: FlowGraph): FlowNode[] | null {
  const inDegree = new Map<string, number>();
  for (const n of graph.nodes) inDegree.set(n.id, 0);
  for (const e of graph.edges) inDegree.set(e.target, (inDegree.get(e.target) ?? 0) + 1);
  const queue: string[] = [];
  for (const [id, d] of inDegree) if (d === 0) queue.push(id);
  const ordered: string[] = [];
  while (queue.length) {
    const id = queue.shift()!;
    ordered.push(id);
    for (const e of graph.edges) {
      if (e.source !== id) continue;
      const next = (inDegree.get(e.target) ?? 0) - 1;
      inDegree.set(e.target, next);
      if (next === 0) queue.push(e.target);
    }
  }
  if (ordered.length !== graph.nodes.length) return null;
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  return ordered.map((id) => byId.get(id)!).filter(Boolean);
}

function collectInputs(
  node: FlowNode,
  incoming: FlowEdge[],
  portValues: Map<string, unknown>,
  initial: Record<string, Record<string, unknown>>,
): Record<string, unknown> {
  const inputs: Record<string, unknown> = { ...(initial[node.id] ?? {}) };
  for (const e of incoming) {
    const portId = e.targetHandle ?? "in";
    const val = portValues.get(`${e.source}:${e.sourceHandle ?? "out"}`);
    inputs[portId] = val;
  }
  return inputs;
}

function pickExecutor(
  executors: ExecutorRegistry,
  node: FlowNode,
): NodeExecutor | undefined {
  if (executors[node.id]) return executors[node.id];
  if (node.type && executors[node.type]) return executors[node.type];
  return executors["*"];
}

function activatedPorts(node: FlowNode, result: unknown): { ports: string[]; value: unknown } {
  if (result && typeof result === "object") {
    const r = result as Record<string, unknown>;
    if (typeof r.__port === "string") {
      return { ports: [r.__port], value: r.value };
    }
    if (typeof r.branch === "string") {
      return { ports: [r.branch], value: r.value ?? r };
    }
  }
  const declared = node.data.outputs?.map((p) => p.id) ?? ["out"];
  return { ports: declared, value: result };
}

/**
 * Engine-agnostic scene description.
 *
 * A scene is plain JSON-serializable data. Adapters consume it to render the
 * scene into a concrete engine — DOM, BabylonJS, three.js, native canvas, etc.
 * The same `Scene` should produce a recognizably similar result on every
 * supported engine.
 */

export type WidgetSpec =
  | KpiSpec
  | ChartSpec
  | KanbanSpec
  | TableSpec
  | ProfileSpec
  | CalloutSpec
  | FormSpec
  | ActionSpec
  | TimelineSpec
  | CodeSpec
  | ImageSpec
  | TextSpec
  | DemoPageSpec
  | ScreenSpec;

export interface KpiSpec {
  kind: "kpi";
  label: string;
  value: string;
  delta?: string;
  trend?: "up" | "down" | "flat";
}

export interface ChartSpec {
  kind: "chart";
  title: string;
  variant: "line" | "bar" | "area";
  series: number[];
  color?: string;
}

export interface KanbanSpec {
  kind: "kanban";
  columns: { title: string; cards: string[] }[];
}

export interface TableSpec {
  kind: "table";
  title: string;
  columns: string[];
  rows: (string | number)[][];
}

export interface ProfileSpec {
  kind: "profile";
  name: string;
  role: string;
  initials: string;
  status?: "online" | "away" | "offline";
}

export interface CalloutSpec {
  kind: "callout";
  tone: "info" | "success" | "warning" | "danger";
  title: string;
  body: string;
}

export interface FormSpec {
  kind: "form";
  title: string;
  fields: { id: string; label: string; type: "text" | "switch" | "number" }[];
}

export interface ActionSpec {
  kind: "action";
  title: string;
  buttons: { label: string; variant?: "primary" | "secondary" | "ghost" }[];
}

export interface TimelineSpec {
  kind: "timeline";
  title: string;
  events: { at: string; label: string }[];
}

export interface CodeSpec {
  kind: "code";
  title: string;
  language: string;
  code: string;
}

export interface ImageSpec {
  kind: "image";
  src: string;
  alt: string;
  caption?: string;
}

export interface TextSpec {
  kind: "text";
  heading: string;
  body: string;
}

export interface DemoPageSpec {
  kind: "demoPage";
  name: string;
  description: string;
  path: string;
  accent: string;
  category: string;
}

/**
 * A 3D-native widget — a screen-shaped panel with a bezel frame, status LED,
 * and optional 2D content drawn into the screen surface. Designed to feel
 * like a hardware display in a 3D scene.
 */
export interface ScreenSpec {
  kind: "screen";
  /** Screen contents — either a static label or a paint callback that draws
   *  onto a 2D context sized to the screen's inner area. */
  content:
    | { type: "label"; title: string; subtitle?: string }
    | { type: "image"; src: string; alt?: string }
    | { type: "paint"; paint: (ctx: CanvasRenderingContext2D, w: number, h: number) => void };
  /** Bezel color (CSS hex). Defaults to a dark frame. */
  bezel?: string;
  /** Bezel thickness in pixels, scaled with the screen's pixel size. */
  bezelThickness?: number;
  /** Power state — controls the LED + screen brightness. */
  on?: boolean;
  /** Background fill color when the content does not fill the screen. */
  background?: string;
  /** Brightness multiplier, 0..1. Defaults to 1 when on, 0.05 when off. */
  brightness?: number;
}

export interface SceneNode {
  id: string;
  position: { x: number; y: number; z?: number };
  size?: { w: number; h: number };
  widget: WidgetSpec;
}

export interface SceneEdge {
  id: string;
  from: string;
  to: string;
  label?: string;
  curve?: "bezier" | "step" | "straight";
  animated?: boolean;
}

export interface Scene {
  nodes: SceneNode[];
  edges: SceneEdge[];
}

/**
 * A WidgetAdapter renders one WidgetSpec for one engine. Each engine ships
 * its own adapter; the scene data does not change.
 *
 * The DOM adapter returns a React element. A BabylonJS adapter returns a
 * `Mesh`. A three.js adapter would return an `Object3D`.
 */
export interface WidgetAdapter<T> {
  render(spec: WidgetSpec, ctx: AdapterContext): T;
}

export interface AdapterContext {
  /** Notify the host when the widget requests selection. */
  onSelect?: (id: string) => void;
  /** The id of the node this widget belongs to. */
  nodeId: string;
  /** Whether the node is currently selected — adapters may render an outline. */
  selected: boolean;
}

let _seq = 1000;
export function nextId(prefix: string): string {
  _seq += 1;
  return `${prefix}-${_seq}`;
}

/**
 * Convenience: walk a Scene and call the adapter on every node.
 *
 * Engine-agnostic — every adapter (DOM, Babylon, three) can share it. The
 * host is responsible for placing the returned render results inside its
 * scene graph.
 */
export function renderScene<T>(
  scene: Scene,
  adapter: WidgetAdapter<T>,
  ctxFor: (node: SceneNode) => AdapterContext
): { node: SceneNode; rendered: T }[] {
  return scene.nodes.map((node) => ({ node, rendered: adapter.render(node.widget, ctxFor(node)) }));
}

import { useEffect, useMemo, type CSSProperties, type ReactNode } from "react";
import { ScreenContext, type ScreenContextValue } from "./Screen.context";
import { useScreenSystem } from "./ScreenSystem.context";
import { ScreenSystem } from "./ScreenSystem";
import { renderSchema } from "./schema";
import type { ScreenBodyProps, ScreenProps } from "./Screen.types";

function ScreenBody({ children, className }: ScreenBodyProps) {
  return <div data-fancy-screens-body="" className={className}>{children}</div>;
}
ScreenBody.displayName = "Screen.Body";

/**
 * Containerized application surface. Registers with the enclosing
 * `<Screen.System>` so agents and presence layers can enumerate and
 * target it.
 *
 * Supports two render modes:
 *   - JSX children  — pass any React tree
 *   - schema prop   — agent-emitted JSON, rendered via the schema registry
 *
 * Children win if both are provided.
 */
function ScreenRoot({ id, title, children, schema, className }: ScreenProps) {
  const system = useScreenSystem();

  useEffect(() => {
    system.registerScreen({
      id,
      title,
      lifecycle: "active",
      storeKeys: [],
      lastActiveAt: Date.now(),
    });
    return () => system.unregisterScreen(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  // Patch title without remounting the registry entry.
  useEffect(() => {
    if (title !== undefined) system.updateScreen(id, { title });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, title]);

  // Read the live agentActivity for this screen so we can apply a CSS
  // class while it's set. Subscribers (e.g. agent-integrations) push
  // updates via system.updateScreen(id, { agentActivity }).
  const meta = system.registry.get(id);
  const agentActivity = meta?.agentActivity;

  const ctx = useMemo<ScreenContextValue>(
    () => ({ id, title, lifecycle: "active" }),
    [id, title],
  );

  const classes = [
    className,
    agentActivity ? "agent-focused-element" : null,
  ].filter(Boolean).join(" ");

  const style: CSSProperties | undefined = agentActivity?.agentColor
    ? ({ ["--agent-color" as unknown as keyof CSSProperties]: agentActivity.agentColor } as CSSProperties)
    : undefined;

  const body = children ?? (schema ? renderSchema(schema) : null);

  return (
    <ScreenContext.Provider value={ctx}>
      <div
        data-fancy-screens-screen=""
        data-screen-id={id}
        className={classes || undefined}
        style={style}
      >
        {body}
      </div>
    </ScreenContext.Provider>
  );
}

ScreenRoot.displayName = "Screen";

export const Screen = Object.assign(ScreenRoot, {
  Body: ScreenBody,
  System: ScreenSystem,
});

export type { ScreenProps, ScreenBodyProps } from "./Screen.types";

import { useMemo, useRef, useState, type ReactNode } from "react";
import { ScreenSystemContext, type ScreenSystemValue } from "./ScreenSystem.context";
import type { RegisteredStore, ScreenMeta } from "./Screen.types";

interface ScreenSystemProps {
  children?: ReactNode;
}

/**
 * Root provider for fancy-screens. Wrap your app once. Owns the screen
 * registry and a Map of registered Zustand stores. Without this,
 * `<Screen>` and `useScreens()` will throw.
 */
export function ScreenSystem({ children }: ScreenSystemProps) {
  const registryRef = useRef<Map<string, ScreenMeta>>(new Map());
  const storesRef = useRef<Map<string, RegisteredStore>>(new Map());
  const [registryVersion, setRegistryVersion] = useState(0);

  const value = useMemo<ScreenSystemValue>(() => {
    const bump = () => setRegistryVersion((v) => v + 1);
    return {
      registry: registryRef.current,
      registryVersion,
      stores: storesRef.current,
      registerScreen: (meta) => {
        registryRef.current.set(meta.id, meta);
        bump();
      },
      updateScreen: (id, patch) => {
        const existing = registryRef.current.get(id);
        if (!existing) return;
        registryRef.current.set(id, { ...existing, ...patch });
        bump();
      },
      unregisterScreen: (id) => {
        registryRef.current.delete(id);
        // Drop any stores registered to this screen so the maps don't drift.
        const prefix = `${id}.`;
        for (const key of storesRef.current.keys()) {
          if (key.startsWith(prefix)) storesRef.current.delete(key);
        }
        bump();
      },
      registerStore: (key, store) => {
        storesRef.current.set(key, store);
        // Patch the storeKeys array on the owning screen so consumers can
        // enumerate stores without scanning the global map.
        const [screenId, storeName] = key.split(".");
        if (screenId && storeName) {
          const existing = registryRef.current.get(screenId);
          if (existing && !existing.storeKeys.includes(storeName)) {
            registryRef.current.set(screenId, {
              ...existing,
              storeKeys: [...existing.storeKeys, storeName],
            });
          }
        }
        bump();
        return () => {
          storesRef.current.delete(key);
          if (screenId && storeName) {
            const existing = registryRef.current.get(screenId);
            if (existing) {
              registryRef.current.set(screenId, {
                ...existing,
                storeKeys: existing.storeKeys.filter((n) => n !== storeName),
              });
            }
          }
          bump();
        };
      },
    };
  }, [registryVersion]);

  return (
    <ScreenSystemContext.Provider value={value}>{children}</ScreenSystemContext.Provider>
  );
}

ScreenSystem.displayName = "ScreenSystem";

