export interface SeparatorProps {
  /** Separator direction */
  orientation?: "horizontal" | "vertical";
  /** Optional centered label text */
  label?: string;
  /** Additional CSS classes */
  className?: string;
}

import { type CSSProperties, useState } from "react";
import type { ShapeItem } from "../../types";

export type ShapeProps = {
  item: ShapeItem;
  onChange?: (next: ShapeItem) => void;
  onSelect?: (id: string) => void;
  selected?: boolean;
  readOnly?: boolean;
  className?: string;
  style?: CSSProperties;
};

const DEFAULT_FILL = "rgba(248, 250, 252, 0.85)";
const DEFAULT_STROKE = "#334155";
const DEFAULT_STROKE_W = 2;

/**
 * Shape — basic whiteboard primitives. All shapes share a bounding-box model
 * (x, y, width, height); the `shape` discriminator picks the renderer.
 *
 * Supported kinds: rect, rounded-rect, ellipse, diamond, triangle, line,
 * arrow, text. Drag-to-move is built in.
 */
export function Shape({
  item,
  onChange,
  onSelect,
  selected,
  readOnly,
  className,
  style,
}: ShapeProps) {
  const [dragging, setDragging] = useState(false);

  const onPointerDown = (e: React.PointerEvent) => {
    if (readOnly || !onChange) return;
    if (e.button !== 0 || e.altKey) return;
    onSelect?.(item.id);
    const start = { x: e.clientX, y: e.clientY };
    const origin = { x: item.x, y: item.y };
    const target = e.currentTarget;
    target.setPointerCapture(e.pointerId);
    let moved = false;
    const move = (ev: PointerEvent) => {
      if (!moved) setDragging(true);
      moved = true;
      onChange({ ...item, x: origin.x + ev.clientX - start.x, y: origin.y + ev.clientY - start.y });
    };
    const up = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      setDragging(false);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };

  const baseStyle: CSSProperties = {
    left: item.x,
    top: item.y,
    width: item.width,
    height: item.height,
    zIndex: item.z,
    ...style,
  };

  const cls = [
    "fw-item fw-shape",
    dragging ? "fw-item--dragging" : "",
    selected ? "fw-shape--selected" : "",
    className ?? "",
  ].filter(Boolean).join(" ");

  if (item.shape === "text") {
    return (
      <div
        className={`${cls} fw-shape--text`}
        style={baseStyle}
        onPointerDown={onPointerDown}
      >
        {item.text ?? ""}
      </div>
    );
  }

  return (
    <svg
      className={cls}
      style={{ ...baseStyle, overflow: "visible" }}
      width={item.width}
      height={item.height}
      onPointerDown={onPointerDown}
    >
      <ShapeGeometry item={item} />
      {item.text && item.shape !== "line" && item.shape !== "arrow" && (
        <text
          x={item.width / 2}
          y={item.height / 2}
          textAnchor="middle"
          dominantBaseline="middle"
          fontFamily="ui-sans-serif, system-ui, sans-serif"
          fontSize={14}
          fill="#1f2937"
          style={{ pointerEvents: "none" }}
        >
          {item.text}
        </text>
      )}
    </svg>
  );
}

/**
 * Compute the from/to local-coord endpoints for line and arrow shapes,
 * honoring `flipX`/`flipY` so the shape preserves the drag direction
 * the user actually drew.
 */
function lineEndpoints(item: ShapeItem): [{ x: number; y: number }, { x: number; y: number }] {
  const { width: w, height: h, flipX, flipY } = item;
  const fromX = flipX ? w : 0;
  const fromY = flipY ? h : 0;
  const toX = flipX ? 0 : w;
  const toY = flipY ? 0 : h;
  return [{ x: fromX, y: fromY }, { x: toX, y: toY }];
}

function ShapeGeometry({ item }: { item: ShapeItem }) {
  const { width: w, height: h } = item;
  const fill = item.fill ?? DEFAULT_FILL;
  const stroke = item.stroke ?? DEFAULT_STROKE;
  const sw = DEFAULT_STROKE_W;
  const inset = sw / 2 + 0.5;

  switch (item.shape) {
    case "rect":
      return (
        <rect
          x={inset}
          y={inset}
          width={Math.max(0, w - inset * 2)}
          height={Math.max(0, h - inset * 2)}
          fill={fill}
          stroke={stroke}
          strokeWidth={sw}
        />
      );
    case "rounded-rect":
      return (
        <rect
          x={inset}
          y={inset}
          width={Math.max(0, w - inset * 2)}
          height={Math.max(0, h - inset * 2)}
          rx={Math.min(16, Math.min(w, h) / 4)}
          ry={Math.min(16, Math.min(w, h) / 4)}
          fill={fill}
          stroke={stroke}
          strokeWidth={sw}
        />
      );
    case "ellipse":
      return (
        <ellipse
          cx={w / 2}
          cy={h / 2}
          rx={Math.max(0, w / 2 - inset)}
          ry={Math.max(0, h / 2 - inset)}
          fill={fill}
          stroke={stroke}
          strokeWidth={sw}
        />
      );
    case "diamond": {
      const pts = `${w / 2},${inset} ${w - inset},${h / 2} ${w / 2},${h - inset} ${inset},${h / 2}`;
      return <polygon points={pts} fill={fill} stroke={stroke} strokeWidth={sw} />;
    }
    case "triangle": {
      const pts = `${w / 2},${inset} ${w - inset},${h - inset} ${inset},${h - inset}`;
      return <polygon points={pts} fill={fill} stroke={stroke} strokeWidth={sw} />;
    }
    case "line": {
      const [from, to] = lineEndpoints(item);
      return (
        <line
          x1={from.x}
          y1={from.y}
          x2={to.x}
          y2={to.y}
          stroke={stroke}
          strokeWidth={sw}
          strokeLinecap="round"
        />
      );
    }
    case "arrow": {
      const [from, to] = lineEndpoints(item);
      const headSize = Math.max(8, sw * 5);
      const dx = to.x - from.x;
      const dy = to.y - from.y;
      const len = Math.hypot(dx, dy) || 1;
      const ux = dx / len;
      const uy = dy / len;
      const baseX = to.x - ux * headSize;
      const baseY = to.y - uy * headSize;
      const perpX = -uy;
      const perpY = ux;
      const leftX = baseX + perpX * headSize * 0.5;
      const leftY = baseY + perpY * headSize * 0.5;
      const rightX = baseX - perpX * headSize * 0.5;
      const rightY = baseY - perpY * headSize * 0.5;
      return (
        <g>
          <line x1={from.x} y1={from.y} x2={baseX} y2={baseY} stroke={stroke} strokeWidth={sw} strokeLinecap="round" />
          <polygon points={`${to.x},${to.y} ${leftX},${leftY} ${rightX},${rightY}`} fill={stroke} stroke={stroke} strokeWidth={sw} strokeLinejoin="round" />
        </g>
      );
    }
    default:
      return null;
  }
}

import type { ShapeElement, Theme } from "../../../types";
import { resolveTheme } from "../../../theme/theme-utils";

export interface ShapeElementRendererProps {
    element: ShapeElement;
    theme?: Theme;
    slideWidthPx: number;
}

/**
 * SVG-rendered shape primitive. Sized to fill its element box; the box
 * decides world position via the parent Slide's positioning wrapper.
 */
export function ShapeElementRenderer({ element, theme, slideWidthPx }: ShapeElementRendererProps) {
    const t = resolveTheme(theme);
    const designWidth = t.slideWidth ?? 1920;
    const scale = slideWidthPx / designWidth;

    const fill = element.fill ?? "rgba(139, 92, 246, 0.15)";
    const stroke = element.stroke ?? t.colors?.accent ?? "#8b5cf6";
    const strokeWidth = (element.strokeWidth ?? 2) * scale;
    const dasharray = element.dashed ? `${6 * scale} ${4 * scale}` : undefined;

    // SVG uses a 0..100 viewBox so radius/strokeWidth are in box-relative units
    // and resolution-independent at render time.
    return (
        <svg
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            style={{ width: "100%", height: "100%", display: "block", overflow: "visible" }}
        >
            {renderShape(element, { fill, stroke, strokeWidth, dasharray })}
        </svg>
    );
}

interface ShapeStyle {
    fill: string;
    stroke: string;
    strokeWidth: number;
    dasharray?: string;
}

function renderShape(el: ShapeElement, s: ShapeStyle) {
    // vectorEffect="non-scaling-stroke" keeps the visible stroke at the
    // pixel width we asked for, regardless of how the parent SVG's
    // `preserveAspectRatio="none"` stretches the viewBox. Without this,
    // narrow arrow / line boxes shrink the stroke into invisibility because
    // the y-axis is squashed.
    const common = {
        fill: s.fill,
        stroke: s.stroke,
        strokeWidth: s.strokeWidth,
        strokeDasharray: s.dasharray,
        vectorEffect: "non-scaling-stroke" as const,
    };
    switch (el.shape) {
        case "rect":
            return <rect x="0" y="0" width="100" height="100" {...common} />;
        case "rounded-rect": {
            const r = el.radius ?? 8;
            return <rect x="0" y="0" width="100" height="100" rx={r} ry={r} {...common} />;
        }
        case "ellipse":
            return <ellipse cx="50" cy="50" rx="50" ry="50" {...common} />;
        case "triangle":
            return <polygon points="50,0 100,100 0,100" {...common} />;
        case "line":
            return <line x1="0" y1="50" x2="100" y2="50" {...common} fill="none" />;
        case "arrow":
            // Render the arrow as a polyline shaft + an inline triangular
            // head built from the same SVG geometry. Avoids SVG markers,
            // which scale with stroke-width and turn into specks at tile
            // sizes.
            return (
                <g>
                    <line x1="0" y1="50" x2="85" y2="50" {...common} fill="none" />
                    <polygon points="100,50 80,30 80,70" fill={s.stroke} stroke="none" />
                </g>
            );
        default:
            return null;
    }
}

import { type CSSProperties, useState } from "react";
import type { SessionDescriptor } from "../../sharing/token";
import { buildShareConfig, buildShareUrl } from "../../sharing/token";

export type ShareControlsProps = {
  /** The active session, or null when not sharing yet. */
  session: SessionDescriptor | null;
  onStart: () => void;
  onStop: () => void;
  /** Optional connection-state badge text. */
  status?: string;
  /** Override the URL base used in the share URL. */
  shareBaseUrl?: string;
  className?: string;
  style?: CSSProperties;
};

type Tab = "url" | "json" | "curl";

/**
 * ShareControls — the host-facing UI for turning sharing on/off and
 * surfacing the resulting connection details (URL / JSON / cURL).
 */
export function ShareControls({
  session,
  onStart,
  onStop,
  status,
  shareBaseUrl,
  className,
  style,
}: ShareControlsProps) {
  const [tab, setTab] = useState<Tab>("url");

  if (!session) {
    return (
      <div className={["fai-share fai-share--idle", className ?? ""].filter(Boolean).join(" ")} style={style}>
        <button type="button" className="fai-share__start" onClick={onStart}>
          Start shared session
        </button>
        <p className="fai-share__hint">
          Generates a session id + secret token. Share the URL with humans, or hand the JSON config to an MCP-capable agent.
        </p>
      </div>
    );
  }

  const url = buildShareUrl(session, shareBaseUrl);
  const config = buildShareConfig(session);
  const curl = buildCurlRecipe(session);

  return (
    <div className={["fai-share fai-share--active", className ?? ""].filter(Boolean).join(" ")} style={style}>
      <div className="fai-share__header">
        <div>
          <strong>Sharing</strong>
          <span className="fai-share__id">
            session <code>{session.id}</code> · token <code>{session.display}…</code>
          </span>
        </div>
        <div className="fai-share__header-actions">
          {status && <span className="fai-share__status">{status}</span>}
          <button type="button" className="fai-share__stop" onClick={onStop}>
            Stop
          </button>
        </div>
      </div>

      <div className="fai-share__tabs" role="tablist">
        <TabButton tab="url" active={tab} setTab={setTab}>URL</TabButton>
        <TabButton tab="json" active={tab} setTab={setTab}>JSON</TabButton>
        <TabButton tab="curl" active={tab} setTab={setTab}>cURL recipe</TabButton>
      </div>

      <div className="fai-share__panel">
        {tab === "url" && <CopyBox label="Open this URL in another tab to join the session" value={url} />}
        {tab === "json" && (
          <CopyBox
            label="Paste into Claude Desktop / Cline MCP server config"
            value={JSON.stringify(config, null, 2)}
          />
        )}
        {tab === "curl" && (
          <CopyBox
            label="Connect from a terminal (verifies the relay is reachable)"
            value={curl}
            multiline
          />
        )}
      </div>
    </div>
  );
}

function TabButton({ tab, active, setTab, children }: { tab: Tab; active: Tab; setTab: (t: Tab) => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      role="tab"
      aria-selected={tab === active}
      className={`fai-share__tab${tab === active ? " is-active" : ""}`}
      onClick={() => setTab(tab)}
    >
      {children}
    </button>
  );
}

function CopyBox({ label, value, multiline }: { label: string; value: string; multiline?: boolean }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 1200);
    } catch {
      // ignore
    }
  };
  return (
    <div>
      <div className="fai-share__panel-label">{label}</div>
      <div className="fai-share__copy">
        <pre className={`fai-share__pre${multiline ? " is-multi" : ""}`}>{value}</pre>
        <button type="button" className="fai-share__copy-btn" onClick={copy}>
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
    </div>
  );
}

/** Build a copy-paste cURL recipe for connecting an external MCP client. */
function buildCurlRecipe(session: SessionDescriptor): string {
  const base =
    typeof window !== "undefined"
      ? `${window.location.protocol}//${window.location.host}`
      : "http://localhost";
  const inbox = `${base}/whiteboard-share/${session.id}/inbox?token=${session.token}`;
  const events = `${base}/whiteboard-share/${session.id}/events?token=${session.token}`;
  return [
    `# 1) In one terminal, subscribe to server-pushed frames (SSE)`,
    `curl -N "${events}"`,
    ``,
    `# 2) In another terminal, send an initialize handshake`,
    `curl -X POST "${inbox}" \\`,
    `  -H 'content-type: application/json' \\`,
    `  -d '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}'`,
    ``,
    `# 3) List the tools the bridge exposes`,
    `curl -X POST "${inbox}" \\`,
    `  -H 'content-type: application/json' \\`,
    `  -d '{"jsonrpc":"2.0","id":2,"method":"tools/list"}'`,
    ``,
    `# 4) Add a sticky note`,
    `curl -X POST "${inbox}" \\`,
    `  -H 'content-type: application/json' \\`,
    `  -d '{"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":"whiteboard_add_sticky","arguments":{"x":300,"y":300,"text":"hello from curl"}}}'`,
  ].join("\n");
}

