    /** Called when an element is clicked — host-driven selection. */
    onElementSelect?: (elementId: string | null) => void;
    /** Selected element id — adds a focus ring and shows resize handles when editing. */
    selectedElementId?: string | null;
    /** Called when the user drags an element body to a new position (slide-relative 0..1). */
    onElementMove?: (elementId: string, x: number, y: number) => void;
    /** Called when the user resizes via a corner / edge handle (slide-relative 0..1). */
    onElementResize?: (elementId: string, patch: { x: number; y: number; w: number; h: number }) => void;
    /** Optional override renderer for a custom element type (or to replace one of the built-ins). */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    className?: string;
    style?: CSSProperties;
}

/**
 * Slide — the shared renderer. Used by SlideViewer, DeckEditor canvas,
 * SlideThumbnail, and the agent bridge's preview tools. All resolution-
 * independence lives here: child elements get a `slideWidthPx` so they can
 * scale font sizes / stroke widths to the rendered slide size.
 *
 * In `editing` mode this component grows two extra affordances:
 *   - pointer-drag on an element body moves it
 *   - selected elements show 8 resize handles (4 corners, 4 edges)
 *
 * Both fire through `onElementMove` / `onElementResize` so the host owns
 * the state — Slide stays a pure renderer.
 */
export function Slide({
    slide,
    theme,
    width,
    aspectRatio,
    editing = false,
    buildStep,
    onElementContentChange,
    onElementSelect,
    selectedElementId,
    onElementMove,
    onElementResize,
    renderElement,
    className,
    style,
}: SlideProps) {
    const t = resolveTheme(theme);
    const ratio = aspectRatio ?? t.aspectRatio ?? 16 / 9;
    const ref = useRef<HTMLDivElement>(null);
    const [measured, setMeasured] = useState<number>(width ?? 0);

    // Auto-measure when width isn't pinned.
    useEffect(() => {
        if (width !== undefined) {
            setMeasured(width);
            return;
        }
        const el = ref.current;
        if (!el) return;
        const ro = new ResizeObserver((entries) => {
            for (const e of entries) {
                setMeasured(e.contentRect.width);
            }
        });
        ro.observe(el);
        return () => ro.disconnect();
    }, [width]);

    const slideWidthPx = measured || 1;
    const slideHeightPx = slideWidthPx / ratio;

    const bg = slide.background;
    // The effective background colour used both for the slide div's `background`
    // and for the dark-theme heuristic exposed via SlideContext.
    const effectiveBg =
        bg?.color ?? t.colors?.background ?? "#ffffff";
    const backgroundStyle: CSSProperties = {
        background: bg?.gradient
            ? bg.gradient
            : bg?.image
                ? `${bg.color ?? "transparent"} url(${bg.image}) center/${bg.imageFit ?? "cover"} no-repeat`
                : effectiveBg,
    };

    const slideContext = useMemo<SlideContextValue>(
        () => ({
            theme: t,
            isDark: isDarkColor(effectiveBg),
            slideWidthPx,
        }),
        [t, effectiveBg, slideWidthPx],
    );

    // ─── Build (entrance-animation) bookkeeping ─────────────────────────────
    // In editing mode builds never hide anything — authors must see/position
    // every element. Otherwise we resolve each animated element's reveal step
    // and the per-element entrance delay for the step currently firing.
    const buildInfo = useMemo(() => {
        if (editing) return null;
        const steps = buildSteps(slide);
        if (steps.length === 0) return null;
        const revealStep = new Map<string, number>(); // element id → FIRST 1-based step it reveals on
        steps.forEach((step, i) => {
            for (const b of step.builds) {
                // By-paragraph elements appear across multiple steps; the
                // element box becomes visible on its earliest paragraph's step.
                if (!revealStep.has(b.element.id)) revealStep.set(b.element.id, i + 1);
            }
        });
        // When `buildStep` is omitted (thumbnails, exports) the slide renders
        // fully built with NO entrance animation. When provided, the firing
        // step's elements animate in.
        const driven = buildStep !== undefined;
        const currentStep = driven ? buildStep : steps.length;
        const firing = driven ? steps[currentStep - 1] : undefined;
        const delays = firing ? stepDelays(firing.builds) : new Map<string, number>();
        // Per-element paragraph reveal state (by-paragraph text builds). When
        // undriven, every paragraph is revealed (fully-built, no animation).
        const paraReveals = driven
            ? paragraphReveals(slide, currentStep)
            : new Map<string, ParaReveal>();
        return { revealStep, currentStep, delays, paraReveals, driven };
    }, [editing, slide, buildStep]);

    return (
        <SlideContext.Provider value={slideContext}>
            <div
                ref={ref}
                className={cn("fs-slide", className)}
                style={{
                    width: width ? `${width}px` : "100%",
                    height: width ? `${width / ratio}px` : `${slideHeightPx}px`,
                    position: "relative",
                    overflow: "hidden",
                    color: t.colors?.text,
                    ...backgroundStyle,
                    ...style,
                }}
                data-fancy-slides-slide={slide.id}
                onClick={(e) => {
                    if (e.target === e.currentTarget && onElementSelect) onElementSelect(null);
                }}
            >
                {buildInfo && <style>{BUILD_KEYFRAMES}</style>}
                {orderedElements(slide.elements).map((element) => {
                    // Resolve build visibility / entrance animation for this element.
                    let buildHidden = false;
                    let buildAnimation: ElementAnimation | undefined;
                    let buildDelay = 0;
                    // By-paragraph reveal state for this element (text builds only).
                    const paraReveal = buildInfo?.paraReveals.get(element.id);
                    if (buildInfo) {
                        const step = buildInfo.revealStep.get(element.id);
                        if (step !== undefined) {
                            if (buildInfo.currentStep < step) {
                                buildHidden = true; // not yet built
                            } else if (paraReveal) {
                                // By-paragraph element: the box stays mounted from its
                                // first paragraph onward; individual paragraphs hide /
                                // animate inside the text renderer. No whole-box effect.
                            } else if (buildInfo.currentStep === step && element.animation) {
                                // Revealing on the step that just fired → play the effect.
                                buildAnimation = element.animation;
                                buildDelay = buildInfo.delays.get(element.id) ?? 0;
                            }
                        }
                    }
                    if (buildHidden) return null;
                    return (
                        <SlideElementHost
                            key={element.id}
                            element={element}
                            theme={t}
                            slideWidthPx={slideWidthPx}
                            slideHeightPx={slideHeightPx}
                            editing={editing}
                            selected={selectedElementId === element.id}
                            onContentChange={onElementContentChange}
                            onSelect={onElementSelect}
                            onMove={onElementMove}
                            onResize={onElementResize}
                            renderElement={renderElement}
                            buildAnimation={buildAnimation}
                            buildDelay={buildDelay}
                            paraReveal={paraReveal}
                        />
                    );
                })}
            </div>
        </SlideContext.Provider>
    );
}

interface SlideElementHostProps {
    element: SlideElement;
    theme: Theme;
    slideWidthPx: number;
    slideHeightPx: number;
    editing: boolean;
    selected: boolean;
    onContentChange?: (elementId: string, content: string) => void;
    onSelect?: (elementId: string | null) => void;
    onMove?: (elementId: string, x: number, y: number) => void;
    onResize?: (elementId: string, patch: { x: number; y: number; w: number; h: number }) => void;
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** Entrance build animation to play (only set on the step the element reveals on). */
    buildAnimation?: ElementAnimation;
    /** Effective entrance delay (ms) resolved for with-prev / after-prev chaining. */
    buildDelay?: number;
    /** Per-paragraph reveal state for a by-paragraph text build (text elements only). */
    paraReveal?: ParaReveal;
}

/** Smallest allowed element size, as a fraction of the slide. */
const MIN_DIM = 0.02;

/** Drag distance below which we treat the gesture as a click. */
const CLICK_DRAG_THRESHOLD_PX = 3;

type ResizeAnchor = "nw" | "n" | "ne" | "e" | "se" | "s" | "sw" | "w";

interface DragState {
    mode: "move" | ResizeAnchor;
    startClientX: number;
    startClientY: number;
    startX: number;
    startY: number;
    startW: number;
    startH: number;
    didMove: boolean;
}

function SlideElementHost({
    element,
    theme,
    slideWidthPx,
    slideHeightPx,
    editing,
    selected,
    onContentChange,
    onSelect,
    onMove,
    onResize,
    renderElement,
    buildAnimation,
    buildDelay = 0,
    paraReveal,
}: SlideElementHostProps) {
    const dragRef = useRef<DragState | null>(null);

    if (element.hidden) return null;

    const left = element.x * slideWidthPx;
    const top = element.y * slideHeightPx;
    const width = element.w * slideWidthPx;
    const height = element.h * slideHeightPx;

    const interactive = editing && !element.locked;
    const canMove = interactive && !!onMove;
    const canResize = interactive && !!onResize && selected;

    const startDrag = (mode: DragState["mode"]) => (e: ReactPointerEvent<HTMLElement>) => {
        e.stopPropagation();
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        dragRef.current = {
            mode,
            startClientX: e.clientX,
            startClientY: e.clientY,
            startX: element.x,
            startY: element.y,
            startW: element.w,
            startH: element.h,
            didMove: false,
        };
    };

    const onPointerMove = (e: ReactPointerEvent<HTMLElement>) => {
        const drag = dragRef.current;
        if (!drag) return;
        const dxPx = e.clientX - drag.startClientX;
        const dyPx = e.clientY - drag.startClientY;
        if (Math.hypot(dxPx, dyPx) >= CLICK_DRAG_THRESHOLD_PX) drag.didMove = true;
        const dx = dxPx / slideWidthPx;
        const dy = dyPx / slideHeightPx;
        if (drag.mode === "move") {
            if (!onMove) return;
            const maxX = 1 - element.w;
            const maxY = 1 - element.h;
            const nextX = clamp(drag.startX + dx, 0, Math.max(0, maxX));
            const nextY = clamp(drag.startY + dy, 0, Math.max(0, maxY));
            onMove(element.id, nextX, nextY);
            return;
        }
        if (!onResize) return;
        const patch = computeResize(drag, dx, dy);
        onResize(element.id, patch);
    };

    const endDrag = (e: ReactPointerEvent<HTMLElement>) => {
        const drag = dragRef.current;
        if (!drag) return;
        try {
            (e.target as HTMLElement).releasePointerCapture(e.pointerId);
        } catch {
            /* element may have unmounted; ignore */
        }
        const wasMove = drag.didMove;
        dragRef.current = null;
        if (!wasMove && onSelect) onSelect(element.id);
    };

    const box: CSSProperties = {
        position: "absolute",
        left: `${left}px`,
        top: `${top}px`,
        width: `${width}px`,
        height: `${height}px`,
        transform: element.rotation ? `rotate(${element.rotation}deg)` : undefined,
        transformOrigin: "center center",
        zIndex: element.z ?? "auto",
        outline: selected ? "2px solid #8b5cf6" : undefined,
        outlineOffset: selected ? 2 : undefined,
        cursor: canMove ? "move" : interactive ? "pointer" : "default",
        touchAction: canMove ? "none" : undefined,
        ...(buildAnimation ? buildEnterStyle(buildAnimation, buildDelay) : null),
    };

    const rendered =
        renderInner({ element, theme, slideWidthPx, editing, selected, onContentChange, paraReveal })
        ?? renderElement?.(element, slideWidthPx)
        ?? elementPlaceholder(element);

    // Whole-element hyperlink — a click target in the viewer (never while
    // editing, so the link doesn't swallow selection). Fills the element box.
    const inner =
        element.href && !editing ? (
            <a
                href={element.href}
                target="_blank"
                rel="noreferrer"
                style={{ display: "block", width: "100%", height: "100%", color: "inherit", textDecoration: "inherit" }}
                data-fancy-slides-href=""
            >
                {rendered}
            </a>
        ) : (
            rendered
        );

    return (
        <div
            className={buildAnimation ? "fs-build-enter" : undefined}
            style={box}
            data-fancy-slides-element={element.id}
            data-fancy-slides-element-type={element.type}
            data-fancy-slides-build={buildAnimation ? "" : undefined}
            onPointerDown={canMove ? startDrag("move") : undefined}
            onPointerMove={canMove ? onPointerMove : undefined}
            onPointerUp={canMove ? endDrag : undefined}
            onPointerCancel={canMove ? endDrag : undefined}
            onClick={(e) => {
                // Click fallback for non-pointer environments / non-movable elements.
                if (!onSelect || canMove) return;
                e.stopPropagation();
                onSelect(element.id);
            }}
        >
            {inner}
            {canResize && (
                <ResizeHandles
                    onStart={(anchor) => startDrag(anchor)}
                    onMove={onPointerMove}
                    onEnd={endDrag}
                />
            )}
        </div>
    );
}

interface ResizeHandlesProps {
    onStart: (anchor: ResizeAnchor) => (e: ReactPointerEvent<HTMLElement>) => void;
    onMove: (e: ReactPointerEvent<HTMLElement>) => void;
    onEnd: (e: ReactPointerEvent<HTMLElement>) => void;
}

function ResizeHandles({ onStart, onMove, onEnd }: ResizeHandlesProps) {
    const anchors: Array<{ anchor: ResizeAnchor; style: CSSProperties; cursor: string }> = [
        { anchor: "nw", style: { left: -5, top: -5 }, cursor: "nwse-resize" },
        { anchor: "n", style: { left: "calc(50% - 5px)", top: -5 }, cursor: "ns-resize" },
        { anchor: "ne", style: { right: -5, top: -5 }, cursor: "nesw-resize" },
        { anchor: "e", style: { right: -5, top: "calc(50% - 5px)" }, cursor: "ew-resize" },
        { anchor: "se", style: { right: -5, bottom: -5 }, cursor: "nwse-resize" },
        { anchor: "s", style: { left: "calc(50% - 5px)", bottom: -5 }, cursor: "ns-resize" },
        { anchor: "sw", style: { left: -5, bottom: -5 }, cursor: "nesw-resize" },
        { anchor: "w", style: { left: -5, top: "calc(50% - 5px)" }, cursor: "ew-resize" },
    ];
    return (
        <>
            {anchors.map(({ anchor, style, cursor }) => (
                <div
                    key={anchor}
                    style={{
                        position: "absolute",
                        width: 10,
                        height: 10,
                        background: "#ffffff",
                        border: "1.5px solid #8b5cf6",
                        borderRadius: 2,
                        cursor,
                        touchAction: "none",
                        boxShadow: "0 1px 2px rgba(0,0,0,0.15)",
                        ...style,
                    }}
                    data-fancy-slides-resize-handle={anchor}
                    onPointerDown={onStart(anchor)}
                    onPointerMove={onMove}
                    onPointerUp={onEnd}
                    onPointerCancel={onEnd}
                />
            ))}
        </>
    );
}

interface RenderInnerArgs {
    element: SlideElement;
    theme: Theme;
    slideWidthPx: number;
    editing: boolean;
    selected: boolean;
    onContentChange?: (elementId: string, content: string) => void;
    paraReveal?: ParaReveal;
}

function renderInner({ element, theme, slideWidthPx, editing, selected, onContentChange, paraReveal }: RenderInnerArgs): ReactNode | undefined {
    switch (element.type) {
        case "text":
            return (
                <TextElementRenderer
                    element={element}
                    theme={theme}
                    slideWidthPx={slideWidthPx}
                    editing={editing}
                    selected={selected}
                    onContentChange={onContentChange ? (c) => onContentChange(element.id, c) : undefined}
                    paraReveal={paraReveal}
                />
            );
        case "image":
            return <ImageElementRenderer element={element} />;
        case "shape":
            return <ShapeElementRenderer element={element} theme={theme} slideWidthPx={slideWidthPx} />;
        case "chart":
        case "code":
        case "table":
        case "embed":
            // These render via consumer-provided `renderElement` so we don't
            // pull fancy-echarts / fancy-code / etc. into the package's static
            // graph. Hosts opt into the default registry from
            // `@particle-academy/fancy-slides/registry`.
            return undefined;
        default:
            return null;
    }
}

/**
 * Built-in fallback for the optional element types (chart / code / table /
 * embed) when the host hasn't wired a `renderElement` (or it returned
 * undefined). Without this the element would render blank, making the
 * toolbar's Insert buttons look broken. The placeholder keeps every insert
 * visible and nudges the dev toward the default registry. Hosts that want the
 * real chart/code/table render pass `renderElement` from
 * `@particle-academy/fancy-slides/registry`.
 */
function elementPlaceholder(element: SlideElement): ReactNode {
    if (element.type !== "chart" && element.type !== "code" && element.type !== "table" && element.type !== "embed") {
        return null;
    }
    const label = element.type.charAt(0).toUpperCase() + element.type.slice(1);
    return (
        <div
            style={{
                width: "100%",
                height: "100%",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                gap: "0.35em",
                textAlign: "center",
                padding: "0.5em",
                boxSizing: "border-box",
                border: "1px dashed currentColor",
                borderRadius: 8,
                opacity: 0.55,
                overflow: "hidden",
            }}
        >
            <span style={{ fontWeight: 600 }}>{label}</span>
            <span style={{ fontSize: "0.7em", opacity: 0.8 }}>Pass renderElement to render</span>
        </div>
    );
}

function orderedElements(elements: SlideElement[]): SlideElement[] {
    // Elements without a `z` keep their array order; explicit z overrides win.
    return [...elements].sort((a, b) => {
        const az = a.z ?? -1;
        const bz = b.z ?? -1;
        if (az === bz) return 0;
        return az < bz ? -1 : 1;
    });
}

function clamp(v: number, min: number, max: number): number {
    return Math.max(min, Math.min(max, v));
}

/**
 * Given a drag delta + which anchor is being dragged, compute the patch
 * `{ x, y, w, h }` to apply. Clamps so dimensions stay >= MIN_DIM and the
 * element stays within the slide. Opposite edges stay fixed (e.g. dragging
 * the W handle moves the left edge but not the right).
 */
function computeResize(drag: DragState, dx: number, dy: number): { x: number; y: number; w: number; h: number } {
    let { startX: x, startY: y, startW: w, startH: h } = drag;
    const right = drag.startX + drag.startW;
    const bottom = drag.startY + drag.startH;
    const anchor = drag.mode as ResizeAnchor;

    if (anchor.includes("w")) {
        const newX = clamp(drag.startX + dx, 0, right - MIN_DIM);
        x = newX;
        w = right - newX;
    } else if (anchor.includes("e")) {
        w = clamp(drag.startW + dx, MIN_DIM, 1 - drag.startX);
    }
    if (anchor.includes("n")) {
        const newY = clamp(drag.startY + dy, 0, bottom - MIN_DIM);
        y = newY;
        h = bottom - newY;
    } else if (anchor.includes("s")) {
        h = clamp(drag.startH + dy, MIN_DIM, 1 - drag.startY);
    }
    return { x, y, w, h };
}

/**
 * Pure-CSS entrance animations for element builds. Mirrors the slide-level
 * transition approach in `SlideViewer`: a set of keyframes wrapped in a
 * `prefers-reduced-motion: no-preference` guard, plus a helper that picks the
 * right `animation-name` + timing for a given element animation.
 *
 * No runtime deps — keyframes are injected via a `<style>` tag by `<Slide>`.
 */

import type { CSSProperties } from "react";
import type { ElementAnimation } from "../../types";

const DEFAULT_BUILD_DURATION = 500;
const EASE = "cubic-bezier(0.16, 1, 0.3, 1)"; // ease-out

/**
 * Inline style that plays an element's entrance build. `delay` is the
 * *effective* delay already resolved for with-prev / after-prev chaining.
 * Under reduced-motion the keyframes are disabled in CSS, so the element
 * simply appears at its final frame.
 */
export function buildEnterStyle(animation: ElementAnimation, effectiveDelay: number): CSSProperties {
    const duration = animation.duration ?? DEFAULT_BUILD_DURATION;
    const dir = animation.direction ?? "left";
    let name: string;
    switch (animation.effect) {
        case "fade":
            name = "fs-build-fade";
            break;
        case "zoom":
            name = "fs-build-zoom";
            break;
        case "fly-in":
            name = `fs-build-fly-${dir}`;
            break;
        case "wipe":
            name = `fs-build-wipe-${dir}`;
            break;
        default:
            name = "fs-build-fade";
    }
    return {
        animationName: name,
        animationDuration: `${duration}ms`,
        animationDelay: `${effectiveDelay}ms`,
        animationTimingFunction: EASE,
        animationFillMode: "both",
    };
}

/**
 * Keyframes for every build effect. `fly-in` translates from the named
 * direction; `wipe` reveals via a `clip-path` inset growing from that edge.
 * Reduced-motion users get no animation — `animation-fill-mode: both` would
 * otherwise pin the `from` frame, so we disable the build animations entirely
 * (the elements are still gated on clicks, they just appear instantly).
 */
export const BUILD_KEYFRAMES = `
@media (prefers-reduced-motion: reduce) {
    .fs-build-enter { animation: none !important; }
}
@media (prefers-reduced-motion: no-preference) {
    @keyframes fs-build-fade {
        from { opacity: 0; }
        to { opacity: 1; }
    }
    @keyframes fs-build-zoom {
        from { opacity: 0; transform: scale(0.8); }
        to { opacity: 1; transform: scale(1); }
    }
    @keyframes fs-build-fly-left {
        from { opacity: 0; transform: translateX(-24%); }
        to { opacity: 1; transform: translateX(0); }
    }
    @keyframes fs-build-fly-right {
        from { opacity: 0; transform: translateX(24%); }
        to { opacity: 1; transform: translateX(0); }
    }
    @keyframes fs-build-fly-up {
        from { opacity: 0; transform: translateY(24%); }
        to { opacity: 1; transform: translateY(0); }
    }
    @keyframes fs-build-fly-down {
        from { opacity: 0; transform: translateY(-24%); }
        to { opacity: 1; transform: translateY(0); }
    }
    /* wipe: clip-path inset reveals from the named edge toward the opposite one.
       inset(top right bottom left) — start fully clipped on the far side. */
    @keyframes fs-build-wipe-left {
        from { clip-path: inset(0 100% 0 0); }
        to { clip-path: inset(0 0 0 0); }
    }
    @keyframes fs-build-wipe-right {
        from { clip-path: inset(0 0 0 100%); }
        to { clip-path: inset(0 0 0 0); }
    }
    @keyframes fs-build-wipe-up {
        from { clip-path: inset(100% 0 0 0); }
        to { clip-path: inset(0 0 0 0); }
    }
    @keyframes fs-build-wipe-down {
        from { clip-path: inset(0 0 100% 0); }
        to { clip-path: inset(0 0 0 0); }
    }
}
`;

import { createContext, useContext } from "react";
import type { Theme } from "../../types";

/**
 * What the surrounding <Slide> knows about itself. Exposed to children
 * (including `renderElement` callbacks and registry hosts like chart-host)
 * via React context so they can react to the deck's theme without the
 * renderElement signature having to carry it around.
 */
export interface SlideContextValue {
    /** Fully-resolved theme (merged with defaults). */
    theme: Theme;
    /**
     * Heuristic: true when the resolved background is dark enough that
     * native-rendered widgets (charts, code blocks) should use a dark variant.
     * Computed once from `theme.colors.background` luminance.
     */
    isDark: boolean;
    /** Slide width in CSS pixels at the current render size. */
    slideWidthPx: number;
}

export const SlideContext = createContext<SlideContextValue | null>(null);

/**
 * Read the surrounding <Slide>'s context. Returns null when called outside
 * a Slide — chart-host / code-host can use that signal to fall back to
 * a sensible default (light theme, no resize anchor).
 */
export function useSlideContext(): SlideContextValue | null {
    return useContext(SlideContext);
}

/**
 * Convenience: returns the resolved theme, or undefined when the caller
 * isn't inside a Slide.
 */
export function useSlideTheme(): Theme | undefined {
    return useContext(SlideContext)?.theme;
}

/**
 * Convenience: returns true when the surrounding slide's background reads
 * as "dark enough" — useful for charts/code blocks that ship a dark variant.
 */
export function useIsDarkSlide(): boolean {
    return useContext(SlideContext)?.isDark ?? false;
}

/** Compute `isDark` from a hex/rgb colour. Used by Slide when building the context. */
export function isDarkColor(color: string): boolean {
    // Normalise #rgb / #rrggbb / rgb()/rgba() to a triple.
    const m = color.match(/^#([0-9a-f]{3,8})$/i);
    if (m) {
        let hex = m[1];
        if (hex.length === 3) {
            hex = hex.split("").map((c) => c + c).join("");
        }
        if (hex.length >= 6) {
            const r = parseInt(hex.slice(0, 2), 16);
            const g = parseInt(hex.slice(2, 4), 16);
            const b = parseInt(hex.slice(4, 6), 16);
            return relativeLuminance(r, g, b) < 0.5;
        }
    }
    const rgb = color.match(/rgba?\(([^)]+)\)/i);
    if (rgb) {
        const [r, g, b] = rgb[1].split(",").map((s) => parseInt(s.trim(), 10));
        if (!Number.isNaN(r) && !Number.isNaN(g) && !Number.isNaN(b)) {
            return relativeLuminance(r, g, b) < 0.5;
        }
    }
    return false;
}

function relativeLuminance(r: number, g: number, b: number): number {
    // Standard sRGB → relative luminance.
    const toLinear = (c: number) => {
        const v = c / 255;
        return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * toLinear(r) + 0.7152 * toLinear(g) + 0.0722 * toLinear(b);
}

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import type { Deck, SlideElement, SlideTransition } from "../../types";
import { resolveTheme } from "../../theme/theme-utils";
import { Slide } from "../Slide";
import { useSlideKeyboard } from "../../hooks/use-slide-keyboard";
import { totalBuildSteps } from "../../utils/builds";
import { cn } from "../../utils/cn";
import { defaultElementRegistry } from "../../registry";

export interface SlideViewerProps {
    /** Deck to play. */
    deck: Deck;
    /** Controlled current slide index. Use with `onIndexChange`. */
    index?: number;
    /** Default current slide index (uncontrolled). */
    defaultIndex?: number;
    /** Called when the viewer advances. */
    onIndexChange?: (index: number) => void;
    /** Called when the viewer exits (Esc). */
    onExit?: () => void;
    /** Auto-advance interval in ms — kiosk mode. Omit to disable. */
    autoAdvanceMs?: number;
    /** Hide the bottom progress bar + slide counter. */
    hideChrome?: boolean;
    /**
     * Custom renderer for element types Slide doesn't render natively
     * (chart/code/table/embed). Defaults to the built-in
     * `defaultElementRegistry` so decks play fully out of the box; pass your
     * own to override.
     */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** Extra classes on the viewer wrapper. */
    className?: string;
}

/**
 * Read-only deck viewer. Renders one slide at a time at the maximum size
 * that fits the container while preserving the theme's aspect ratio.
 * Keyboard nav is built in; expand a fullscreen-ready container around
 * `<SlideViewer>` to get the F11-style experience.
 */
export function SlideViewer({
    deck,
    index: controlledIndex,
    defaultIndex,
    onIndexChange,
    onExit,
    autoAdvanceMs,
    hideChrome = false,
    renderElement = defaultElementRegistry,
    className,
}: SlideViewerProps) {
    const isControlled = controlledIndex !== undefined;
    const [internalIndex, setInternalIndex] = useState(defaultIndex ?? 0);
    const index = isControlled ? controlledIndex! : internalIndex;

    const goTo = useCallback(
        (i: number) => {
            const clamped = Math.max(0, Math.min(deck.slides.length - 1, i));
            if (!isControlled) setInternalIndex(clamped);
            onIndexChange?.(clamped);
        },
        [deck.slides.length, isControlled, onIndexChange],
    );

    const [blanked, setBlanked] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    // Track nav direction so `slide` transitions default sensibly: advancing
    // forward enters from the right, going back enters from the left.
    const prevIndexRef = useRef(index);
    const forward = index >= prevIndexRef.current;

    // ─── Intra-slide build (entrance-animation) step-through ────────────────
    // 0 = nothing built yet on the current slide. Each forward advance fires
    // the next step until `totalBuildSteps`, after which we move to the next
    // slide. Going backward lands on the previous slide fully built.
    const slide = deck.slides[index];
    const totalSteps = totalBuildSteps(slide);
    const [buildStep, setBuildStep] = useState(0);

    // Reset the build step on slide change. Only a forward advance INTO the next
    // slide replays builds from 0; every other landing (retreat, Home/End,
    // digit jump, external control) shows the slide fully built. `nextFreshRef`
    // flags the one forward-advance case.
    const nextFreshRef = useRef(false);
    useEffect(() => {
        if (index === prevIndexRef.current) return;
        prevIndexRef.current = index;
        const fresh = nextFreshRef.current;
        nextFreshRef.current = false;
        setBuildStep(fresh ? 0 : totalBuildSteps(deck.slides[index]));
    }, [index, deck.slides]);

    const advance = useCallback(() => {
        if (buildStep < totalSteps) {
            setBuildStep((s) => s + 1);
        } else if (index < deck.slides.length - 1) {
            nextFreshRef.current = true; // next slide starts with nothing built
            goTo(index + 1);
        }
    }, [buildStep, totalSteps, index, deck.slides.length, goTo]);

    const retreat = useCallback(() => {
        // v1: reversing individual builds is out of scope — step back a whole
        // slide, showing it fully built (handled by the reset effect).
        if (index > 0) goTo(index - 1);
    }, [index, goTo]);

    useSlideKeyboard({
        total: deck.slides.length,
        index,
        goTo,
        onAdvance: advance,
        onRetreat: retreat,
        onExit,
        onBlank: () => setBlanked((b) => !b),
        onFullscreen: () => {
            const el = containerRef.current;
            if (!el) return;
            if (document.fullscreenElement) document.exitFullscreen();
            else el.requestFullscreen?.();
        },
    });

    // Auto-advance loop for kiosk mode — steps through builds then slides.
    useEffect(() => {
        if (!autoAdvanceMs || deck.slides.length <= 1) return;
        const t = setTimeout(() => {
            if (buildStep < totalSteps) {
                setBuildStep((s) => s + 1);
            } else {
                nextFreshRef.current = true;
                goTo(index + 1 < deck.slides.length ? index + 1 : 0);
            }
        }, autoAdvanceMs);
        return () => clearTimeout(t);
    }, [autoAdvanceMs, index, deck.slides.length, goTo, buildStep, totalSteps]);
    const theme = resolveTheme(deck.theme);
    const aspectRatio = theme.aspectRatio ?? 16 / 9;

    // Resolve the incoming slide's entrance transition (slide → theme default → none).
    const transition: SlideTransition | undefined = slide?.transition ?? theme.defaultTransition;
    const enterStyle = transitionEnterStyle(transition, forward);

    return (
        <div
            ref={containerRef}
            className={cn("fs-viewer", className)}
            style={{
                position: "relative",
                width: "100%",
                height: "100%",
                background: blanked ? "#000000" : theme.colors?.background ?? "#000000",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                overflow: "hidden",
            }}
            tabIndex={0}
            data-fancy-slides-viewer={deck.id}
            data-fancy-slides-build-step={buildStep}
            onClick={() => {
                if (blanked) return;
                advance();
            }}
        >
            {/* Keyframes for slide entrance transitions. Pure CSS — no runtime deps.
                Gated behind prefers-reduced-motion so animations vanish entirely
                for users who ask for less motion. */}
            <style>{TRANSITION_KEYFRAMES}</style>

            {!blanked && slide && (
                <div
                    style={{
                        // Box that fits the slide while preserving aspect ratio.
                        width: "min(100%, calc(100vh * var(--fs-ratio)))",
                        aspectRatio: String(aspectRatio),
                        // CSS var lets us inline-style the aspect ratio so it works in any container.
                        ["--fs-ratio" as keyof React.CSSProperties as string]: aspectRatio.toString(),
                        boxShadow: "0 8px 30px rgba(0,0,0,0.35)",
                    } as React.CSSProperties}
                >
                    {/* Keyed by index so React remounts on every slide change and the
                        enter animation replays from its first frame. */}
                    <div key={index} className="fs-slide-enter" style={enterStyle}>
                        <Slide slide={slide} theme={theme} buildStep={buildStep} renderElement={renderElement} />
                    </div>
                </div>
            )}

            {!hideChrome && !blanked && (
                <div
                    style={{
                        position: "absolute",
                        bottom: 16,
                        right: 16,
                        padding: "4px 10px",
                        borderRadius: 999,
                        background: "rgba(15, 23, 42, 0.6)",
                        color: "#f8fafc",
                        fontSize: 12,
                        fontFamily: theme.fonts?.mono,
                        backdropFilter: "blur(6px)",
                    }}
                    aria-label="Slide counter"
                >
                    {index + 1} / {deck.slides.length}
                </div>
            )}
        </div>
    );
}

// ─── Transitions ─────────────────────────────────────────────────────────────

const DEFAULT_DURATION = 400;
const EASE = "cubic-bezier(0.16, 1, 0.3, 1)"; // ease-out

/**
 * Build the inline style that drives a slide's entrance animation. The actual
 * keyframes live in {@link TRANSITION_KEYFRAMES}; here we just pick the right
 * `animation-name` + duration. `prefers-reduced-motion: reduce` is handled in
 * CSS (the keyframe-bearing rules are wrapped in a media query), so a reduced-
 * motion user simply sees the final frame with no movement.
 */
function transitionEnterStyle(transition: SlideTransition | undefined, forward: boolean): React.CSSProperties {
    const kind = transition?.kind ?? "none";
    if (kind === "none") return { width: "100%", height: "100%" };

    const duration = transition?.duration ?? DEFAULT_DURATION;
    let name: string;
    switch (kind) {
        case "fade":
            name = "fs-fade-in";
            break;
        case "zoom":
            name = "fs-zoom-in";
            break;
        case "slide": {
            const dir = transition?.direction ?? (forward ? "right" : "left");
            name = `fs-slide-in-${dir}`;
            break;
        }
        default:
            return { width: "100%", height: "100%" };
    }

    return {
        width: "100%",
        height: "100%",
        animationName: name,
        animationDuration: `${duration}ms`,
        animationTimingFunction: EASE,
        animationFillMode: "both",
    };
}

/**
 * Keyframes for every transition kind. Wrapped in
 * `@media (prefers-reduced-motion: no-preference)` so that reduced-motion users
 * get no animation at all — `animation-fill-mode: both` would otherwise pin the
 * element at its `from` frame, so we disable the animation entirely instead.
 */
const TRANSITION_KEYFRAMES = `
@media (prefers-reduced-motion: reduce) {
    .fs-slide-enter { animation: none !important; }
}
@media (prefers-reduced-motion: no-preference) {
    @keyframes fs-fade-in {
        from { opacity: 0; }
        to { opacity: 1; }
    }
    @keyframes fs-zoom-in {
        from { opacity: 0; transform: scale(0.92); }
        to { opacity: 1; transform: scale(1); }
    }
    @keyframes fs-slide-in-right {
        from { opacity: 0; transform: translateX(8%); }
        to { opacity: 1; transform: translateX(0); }
    }
    @keyframes fs-slide-in-left {
        from { opacity: 0; transform: translateX(-8%); }
        to { opacity: 1; transform: translateX(0); }
    }
    @keyframes fs-slide-in-up {
        from { opacity: 0; transform: translateY(8%); }
        to { opacity: 1; transform: translateY(0); }
    }
    @keyframes fs-slide-in-down {
        from { opacity: 0; transform: translateY(-8%); }
        to { opacity: 1; transform: translateY(0); }
    }
}
`;

import { forwardRef, useEffect, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import type { StickyNoteColor, StickyNoteProps } from "./StickyNote.types";

// Preset paper colors → bg + text classes. An arbitrary CSS color string
// falls through to an inline `background` (text stays a dark ink tone).
const colorClasses: Record<StickyNoteColor, string> = {
  yellow: "bg-amber-100 text-amber-950 dark:bg-amber-200 dark:text-amber-950",
  blue: "bg-sky-100 text-sky-950 dark:bg-sky-200 dark:text-sky-950",
  green: "bg-emerald-100 text-emerald-950 dark:bg-emerald-200 dark:text-emerald-950",
  pink: "bg-pink-100 text-pink-950 dark:bg-pink-200 dark:text-pink-950",
  violet: "bg-violet-100 text-violet-950 dark:bg-violet-200 dark:text-violet-950",
};

const isPreset = (c: string): c is StickyNoteColor => c in colorClasses;

/**
 * A sticky note — paper-styled, with optional inline text editing.
 *
 * Presentational primitive only: it owns the note's look and its editable
 * text. Positioning, dragging, resizing, and z-order are the consumer's job
 * (e.g. `fancy-whiteboard`'s `<Board>` places it in world space;
 * `fancy-artboard`'s `<ArtBoard.Note>` positions it absolutely).
 *
 *   <StickyNote value={text} onChange={setText} color="yellow" rotate={-2} />
 */
export const StickyNote = forwardRef<HTMLDivElement, StickyNoteProps>(
  (
    {
      value,
      defaultValue,
      onChange,
      color = "yellow",
      rotate = 0,
      width = 180,
      height = "auto",
      selected = false,
      editable = true,
      autoFocus = false,
      id,
      children,
      className,
      style,
    },
    ref,
  ) => {
    const isControlled = value !== undefined;
    const [internal, setInternal] = useState(defaultValue ?? "");
    const text = isControlled ? value : internal;
    const editRef = useRef<HTMLDivElement>(null);

    // Push text into the contentEditable node only when it differs AND the node
    // isn't focused — editing in place must not yank the caret to the start.
    useEffect(() => {
      const el = editRef.current;
      if (el && document.activeElement !== el && el.textContent !== text) {
        el.textContent = text ?? "";
      }
    }, [text]);

    // Focus + caret-to-end when editing turns on (consumer "enter edit" gesture).
    useEffect(() => {
      if (!editable || !autoFocus) return;
      const el = editRef.current;
      if (!el) return;
      el.focus();
      const range = document.createRange();
      range.selectNodeContents(el);
      range.collapse(false);
      const sel = window.getSelection();
      sel?.removeAllRanges();
      sel?.addRange(range);
    }, [editable, autoFocus]);

    const commit = () => {
      const next = editRef.current?.textContent ?? "";
      if (next === text) return;
      if (!isControlled) setInternal(next);
      onChange?.(next);
    };

    const preset = isPreset(color);
    const content =
      children != null ? (
        children
      ) : editable ? (
        <div
          ref={editRef}
          contentEditable
          suppressContentEditableWarning
          spellCheck={false}
          role="textbox"
          aria-multiline="true"
          className="outline-none whitespace-pre-wrap break-words min-h-[1.4em]"
          onBlur={commit}
          onKeyDown={(e) => {
            if (e.key === "Escape") e.currentTarget.blur();
          }}
        >
          {text}
        </div>
      ) : (
        <div className="whitespace-pre-wrap break-words">{text}</div>
      );

    return (
      <div
        ref={ref}
        id={id}
        data-react-fancy-sticky=""
        className={cn(
          "rounded-sm p-3.5 text-sm leading-relaxed shadow-[0_2px_8px_rgba(0,0,0,0.12),0_1px_2px_rgba(0,0,0,0.08)]",
          preset ? colorClasses[color] : "text-zinc-900",
          selected && "ring-2 ring-blue-500 ring-offset-1",
          className,
        )}
        style={{
          width,
          height,
          transform: rotate ? `rotate(${rotate}deg)` : undefined,
          ...(preset ? null : { background: color }),
          ...style,
        }}
      >
        {content}
      </div>
    );
  },
);

StickyNote.displayName = "StickyNote";

import type { CSSProperties, ReactNode } from "react";

/** Built-in paper colors. Any CSS color string is also accepted. */
export type StickyNoteColor = "yellow" | "blue" | "green" | "pink" | "violet";

export interface StickyNoteProps {
  /** Note text (controlled). */
  value?: string;
  /** Initial text when uncontrolled. */
  defaultValue?: string;
  /** Fires when the edited text is committed (on blur). */
  onChange?: (text: string) => void;
  /** Paper color — one of the presets, or any CSS color string. Default `"yellow"`. */
  color?: StickyNoteColor | (string & {});
  /** Rotation in degrees. Default `0`. */
  rotate?: number;
  /** Width as px number or any CSS length. Default `180`. */
  width?: number | string;
  /** Height as px number or any CSS length. Default `"auto"`. */
  height?: number | string;
  /** Selected styling (focus ring). */
  selected?: boolean;
  /** Allow inline editing of the text. Default `true`. */
  editable?: boolean;
  /**
   * Focus the editable region (caret at end) when it becomes editable. Lets a
   * consumer's "enter edit mode" gesture drop straight into typing. Default `false`.
   */
  autoFocus?: boolean;
  /**
   * Stable handle — also emitted as the element `id`. Lets agents and
   * selectors target a specific note without guessing the DOM.
   */
  id?: string;
  /** Static content; when provided, overrides the editable text. */
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

import { createContext, useContext } from "react";
import type { TableContextValue } from "./Table.types";

export const TableContext = createContext<TableContextValue | null>(null);

export function useTable(): TableContextValue {
  const ctx = useContext(TableContext);
  if (!ctx) {
    throw new Error("Table compound components must be used within <Table>");
  }
  return ctx;
}

import { Children, isValidElement, useCallback, useMemo, useState } from "react";
import type { ReactNode } from "react";
import { cn } from "../../utils/cn";
import { TableContext } from "./Table.context";
import { TableHead } from "./TableHead";
import { TableBody } from "./TableBody";
import { TableRow } from "./TableRow";
import { TableCell } from "./TableCell";
import { TableColumn } from "./TableColumn";
import { TablePagination } from "./TablePagination";
import { TableSearch } from "./TableSearch";
import { TableTray } from "./TableTray";
import { TableRowTray } from "./TableRowTray";
import type { TableProps, TableContextValue } from "./Table.types";

function TableRoot({ children, className }: TableProps) {
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<"asc" | "desc">("asc");
  const [page, setPage] = useState(0);
  const [searchQuery, setSearchQuery] = useState("");

  const toggleSort = useCallback(
    (key: string) => {
      if (sortKey === key) {
        setSortDir((d) => (d === "asc" ? "desc" : "asc"));
      } else {
        setSortKey(key);
        setSortDir("asc");
      }
    },
    [sortKey],
  );

  const ctx = useMemo<TableContextValue>(
    () => ({
      sortKey,
      sortDir,
      toggleSort,
      page,
      setPage,
      pageSize: 10,
      totalRows: 0,
      searchQuery,
      setSearchQuery,
    }),
    [sortKey, sortDir, toggleSort, page, searchQuery],
  );

  return (
    <TableContext.Provider value={ctx}>
      <div data-react-fancy-table="" className={cn("overflow-hidden rounded-lg border border-zinc-200 dark:border-zinc-700", className)}>
        {splitTableChildren(children)}
      </div>
    </TableContext.Provider>
  );
}

function splitTableChildren(children: ReactNode): ReactNode {
  const before: ReactNode[] = [];
  const inside: ReactNode[] = [];
  const after: ReactNode[] = [];
  let seenTableContent = false;

  Children.forEach(children, (child) => {
    if (isValidElement(child) && (child.type === TableHead || child.type === TableBody)) {
      inside.push(child);
      seenTableContent = true;
      return;
    }
    (seenTableContent ? after : before).push(child);
  });

  return (
    <>
      {before}
      {inside.length > 0 && <table className="w-full border-collapse">{inside}</table>}
      {after}
    </>
  );
}

export const Table = Object.assign(TableRoot, {
  Head: TableHead,
  Body: TableBody,
  Row: TableRow,
  Cell: TableCell,
  Column: TableColumn,
  Pagination: TablePagination,
  Search: TableSearch,
  Tray: TableTray,
  RowTray: TableRowTray,
});

import type { ReactNode } from "react";

export interface TableColumn<T = any> {
  key: string;
  label: string;
  sortable?: boolean;
  render?: (value: any, row: T) => ReactNode;
}

export interface TableContextValue {
  sortKey: string | null;
  sortDir: "asc" | "desc";
  toggleSort: (key: string) => void;
  page: number;
  setPage: (page: number) => void;
  pageSize: number;
  totalRows: number;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
}

export interface TableProps {
  children: ReactNode;
  className?: string;
}

export interface TableHeadProps {
  children: ReactNode;
  className?: string;
}

export interface TableBodyProps {
  children: ReactNode;
  className?: string;
}

export interface TableRowProps {
  children: ReactNode;
  className?: string;
  onClick?: () => void;
  tray?: ReactNode;
