        const lh = style.lineHeight ?? 1.4;
        const editScope = scopeId;
        return (
            <div
                data-fs-edit-scope={editScope}
                style={{
                    width: "100%",
                    height: "100%",
                    pointerEvents: "auto",
                    cursor: "text",
                    textAlign: style.align ?? "left",
                    color: style.color ?? t.colors?.text,
                    fontFamily: style.fontFamily ?? t.fonts?.body,
                }}
