                            data-fancy-slides-paragraph={i}
                        >
                            {renderChunk(para)}
                        </div>
                    );
                })}
            </div>
        );
    }

    if (format === "plain") {
        return <div style={css}>{element.content}</div>;
    }

    return (
        <div data-fs-text-scope={scopeId} style={css}>
            {proseStyle}
            <ContentRenderer value={element.content} format={format === "html" ? "html" : "markdown"} />
        </div>
    );
}

