  indigo: "bg-indigo-500 hover:bg-indigo-600",
  blue: "bg-blue-500 hover:bg-blue-600",
  zinc: "bg-zinc-500 hover:bg-zinc-600",
};

const OFF_CLASSES =
  "bg-zinc-100 hover:bg-zinc-200 dark:bg-zinc-800 dark:hover:bg-zinc-700";

export const TimeGrid = forwardRef<HTMLDivElement, TimeGridProps>(
  (
    {
      rows,
      cols,
      value,
      onChange,
      toneOn = "violet",
      cellWidth = 20,
      cellHeight = 16,
      sparseColLabels = true,
      toggleStripsOnHeaderClick = true,
      ariaCell,
      cellId,
      className,
    },
    ref,
  ) => {
    const [drag, setDrag] = useState<boolean | null>(null);

    const setCell = (r: number, c: number, v: boolean) => {
      if (value[r]?.[c] === v) return;
      const next = value.map((row) => row.slice());
      next[r][c] = v;
      onChange(next);
    };

    const toggleRow = (r: number) => {
      if (!toggleStripsOnHeaderClick) return;
      const all = value[r].every(Boolean);
      const next = value.map((row) => row.slice());
      for (let c = 0; c < cols.length; c++) next[r][c] = !all;
      onChange(next);
    };

    const toggleCol = (c: number) => {
      if (!toggleStripsOnHeaderClick) return;
      const all = value.every((row) => row[c]);
      const next = value.map((row) => row.slice());
      for (let r = 0; r < rows.length; r++) next[r][c] = !all;
      onChange(next);
    };

    const colStep = Math.max(1, Math.floor(cols.length / 6));
    const onTone = TONE_CLASSES[toneOn];

    return (
      <div
        ref={ref}
        data-react-fancy-timegrid=""
        className={cn(
          "select-none overflow-x-auto",
          className,
        )}
        onMouseLeave={() => setDrag(null)}
        onMouseUp={() => setDrag(null)}
      >
        <table className="text-[10px]">
          <thead>
            <tr>
              <th />
              {cols.map((label, c) => (
                <th
                  key={c}
                  onClick={() => toggleCol(c)}
                  style={{ width: cellWidth }}
                  data-react-fancy-timegrid-col={c}
                  className={cn(
                    "text-zinc-400",
                    toggleStripsOnHeaderClick &&
                      "cursor-pointer hover:text-zinc-700 dark:hover:text-zinc-200",
                  )}
                >
                  {sparseColLabels ? (c % colStep === 0 ? label : "") : label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((label, r) => (
              <tr key={r}>
                <th
                  onClick={() => toggleRow(r)}
                  data-react-fancy-timegrid-row={r}
                  className={cn(
                    "pr-1 text-right font-medium text-zinc-500",
                    toggleStripsOnHeaderClick &&
                      "cursor-pointer hover:text-zinc-800 dark:hover:text-zinc-200",
                  )}
                >
                  {label}
                </th>
                {cols.map((_, c) => {
                  const on = value[r]?.[c] ?? false;
                  return (
                    <td key={c} className="p-px">
                      <button
                        type="button"
                        onMouseDown={() => {
                          const v = !on;
                          setDrag(v);
                          setCell(r, c, v);
                        }}
                        onMouseEnter={() => drag !== null && setCell(r, c, drag)}
                        style={{ width: cellWidth, height: cellHeight }}
                        data-react-fancy-timegrid-cell={
                          cellId ? cellId(r, c) : `${r}:${c}`
                        }
                        aria-pressed={on}
                        aria-label={
                          ariaCell
                            ? ariaCell(r, c, on)
                            : `${rows[r]} ${cols[c]} ${on ? "on" : "off"}`
                        }
                        className={cn(
                          "block rounded-sm transition",
                          on ? onTone : OFF_CLASSES,
                        )}
                      />
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  },
);

TimeGrid.displayName = "TimeGrid";

/**
 * Subset of palette colors the TimeGrid offers for the "cell-on" tone.
 * Mirrors react-fancy's `ActionColor` choice — small enough to keep the
 * compiled CSS tight, broad enough to cover most use cases.
 */
export type TimeGridTone =
  | "violet"
  | "emerald"
  | "sky"
  | "rose"
  | "amber"
  | "indigo"
  | "blue"
  | "zinc";

export interface TimeGridProps {
  /** Row labels, one per row in `value` (e.g. ["Sun","Mon",…]). */
  rows: string[];
  /** Column labels, one per column in `value` (e.g. ["0","1",…,"23"]). */
  cols: string[];
  /**
   * Controlled cell state. Must be a rectangular `rows.length × cols.length`
   * matrix of booleans. The component never mutates it — every change
   * produces a new array passed to `onChange`.
   */
  value: boolean[][];
  /** Called with the next matrix whenever a cell, row, or column toggles. */
  onChange: (next: boolean[][]) => void;

  /** Cell-on tone. Default `"violet"`. */
  toneOn?: TimeGridTone;
  /** Cell width in px. Default `20`. */
  cellWidth?: number;
  /** Cell height in px. Default `16`. */
  cellHeight?: number;
  /**
   * If true (default), only every Nth column label is rendered to keep the
   * top axis legible at small `cellWidth`. Set false to show all labels.
   */
  sparseColLabels?: boolean;
  /** If true (default), clicking a row/column header toggles that strip. */
  toggleStripsOnHeaderClick?: boolean;

  /**
   * Optional accessible label per cell. Default produces
   * `${rows[r]} ${cols[c]} on|off`. Override for richer context
   * (e.g. include unit: `${rows[r]} ${cols[c]}:00 ${on ? "on" : "off"}`).
   */
  ariaCell?: (rowIdx: number, colIdx: number, on: boolean) => string;

  /**
   * Stable per-cell identifier. Emitted as `data-react-fancy-timegrid-cell`
   * on the button so MCP bridges can address a specific cell from a tool
   * call without DOM walking. Default `${row}:${col}`.
   */
  cellId?: (rowIdx: number, colIdx: number) => string;

  /** Additional CSS classes on the outer scroll container. */
  className?: string;
}

import { forwardRef, useCallback } from "react";
import { ChevronUp, ChevronDown } from "lucide-react";
import { cn } from "../../utils/cn";
import { useControllableState } from "../../hooks/use-controllable-state";
import type { TimePickerProps } from "./TimePicker.types";

function pad(n: number): string {
  return n.toString().padStart(2, "0");
}

function parseTime(val: string): { hours: number; minutes: number } {
  const [h, m] = val.split(":").map(Number);
  return { hours: h || 0, minutes: m || 0 };
}

export const TimePicker = forwardRef<HTMLDivElement, TimePickerProps>(
  function TimePicker(
    {
      value: controlledValue,
      defaultValue = "12:00",
      onChange,
      format = "12h",
      minuteStep = 1,
      disabled = false,
      className,
    },
    ref,
  ) {
    const [value, setValue] = useControllableState(
      controlledValue,
      defaultValue,
      onChange,
    );

    const { hours: h24, minutes } = parseTime(value);
    const isPM = h24 >= 12;
    const displayHour = format === "12h" ? (h24 % 12 || 12) : h24;

    const updateTime = useCallback(
      (hours: number, mins: number) => {
        setValue(`${pad(hours)}:${pad(mins)}`);
      },
      [setValue],
    );

    const changeHour = useCallback(
      (delta: number) => {
        const newHour = (h24 + delta + 24) % 24;
        updateTime(newHour, minutes);
      },
      [h24, minutes, updateTime],
    );

    const changeMinute = useCallback(
      (delta: number) => {
        const newMin = (minutes + delta + 60) % 60;
        updateTime(h24, newMin);
      },
      [h24, minutes, updateTime],
    );

    const toggleAmPm = useCallback(() => {
      updateTime((h24 + 12) % 24, minutes);
    }, [h24, minutes, updateTime]);

    const spinBtnClass =
      "flex h-7 w-full items-center justify-center rounded text-zinc-400 transition-colors hover:bg-zinc-100 hover:text-zinc-600 dark:hover:bg-zinc-800 dark:hover:text-zinc-300 disabled:opacity-50";
    const displayClass =
      "flex h-10 w-12 items-center justify-center text-lg font-medium tabular-nums";

    return (
      <div
        data-react-fancy-time-picker=""
        ref={ref}
        className={cn(
          "inline-flex items-center gap-1 rounded-lg border border-zinc-200 bg-white p-2 dark:border-zinc-700 dark:bg-zinc-900",
          disabled && "opacity-50",
          className,
        )}
      >
        {/* Hour column */}
        <div className="flex flex-col items-center">
          <button type="button" onClick={() => changeHour(1)} disabled={disabled} className={spinBtnClass} aria-label="Increase hour">
            <ChevronUp size={14} />
          </button>
          <div className={displayClass}>{pad(displayHour)}</div>
          <button type="button" onClick={() => changeHour(-1)} disabled={disabled} className={spinBtnClass} aria-label="Decrease hour">
            <ChevronDown size={14} />
          </button>
        </div>

        <span className="text-lg text-zinc-400">:</span>

        {/* Minute column */}
        <div className="flex flex-col items-center">
          <button type="button" onClick={() => changeMinute(minuteStep)} disabled={disabled} className={spinBtnClass} aria-label="Increase minute">
            <ChevronUp size={14} />
          </button>
          <div className={displayClass}>{pad(minutes)}</div>
          <button type="button" onClick={() => changeMinute(-minuteStep)} disabled={disabled} className={spinBtnClass} aria-label="Decrease minute">
            <ChevronDown size={14} />
          </button>
        </div>

        {/* AM/PM toggle */}
        {format === "12h" && (
          <button
            type="button"
            onClick={toggleAmPm}
            disabled={disabled}
            className="ml-1 rounded-lg bg-zinc-100 px-2 py-1 text-sm font-medium transition-colors hover:bg-zinc-200 dark:bg-zinc-800 dark:hover:bg-zinc-700"
          >
            {isPM ? "PM" : "AM"}
          </button>
        )}
      </div>
    );
  },
);

TimePicker.displayName = "TimePicker";

export interface TimePickerProps {
  value?: string;
