          </div>
        )}

        {isHorizontal ? (
          <div
            ref={scrollRef}
            className="overflow-x-auto pb-4 -mb-4"
            style={{ scrollbarWidth: "thin", scrollbarColor: "rgb(161 161 170) transparent" }}
            onWheel={handleWheel}
          >
            <div className="flex min-w-max items-start">
              {content}
