import { useCallback, useMemo } from "react";
import { useForm as inertiaUseForm } from "@inertiajs/react";

/**
 * Per-field bridge returned by `useFancyForm().field(name)`. Shaped to
 * drop directly into react-fancy form components without further
 * wiring.
 */
export interface FancyFieldBridge<T = unknown> {
  /** Pass to `<Input value={...} />` — current field value (string). */
  value: T;
  /** Pass to `<Input onChange={...} />`. Accepts the React event *or* a raw value (Select, Switch). */
  onChange: (e: React.ChangeEvent<HTMLInputElement> | T) => void;
  /** Pass to `<Input error={...} />` — last server validation error for this field. */
  error?: string;
  /** True while a submit is in flight. */
  loading?: boolean;
  /** Stable name attribute. */
  name: string;
}

/**
 * Bridge type returned by useFancyForm. Wraps Inertia's `useForm()` and
 * adds a `field(name)` helper that returns props ready to spread into
 * react-fancy's `<Input>`, `<Select>`, `<Switch>`, `<Textarea>`, etc.
 */
export interface FancyFormBridge<TData extends Record<string, unknown>> {
  data: TData;
  setData: <K extends keyof TData>(key: K, value: TData[K]) => void;
  errors: Partial<Record<keyof TData, string>>;
  processing: boolean;

  /**
   * Returns `{ value, onChange, error, loading, name }` for a field.
   * `onChange` accepts both a React change event (native input/textarea)
   * and a raw value (Select/Switch/MultiSwitch which pass the new value
   * directly).
   */
  field<K extends keyof TData & string>(name: K): FancyFieldBridge<TData[K]>;

  /** Forwarded from Inertia's useForm. */
  submit: (method: string, url: string, options?: object) => void;
  post: (url: string, options?: object) => void;
  put: (url: string, options?: object) => void;
  patch: (url: string, options?: object) => void;
  delete: (url: string, options?: object) => void;
  reset: (...fields: Array<keyof TData>) => void;
  clearErrors: (...fields: Array<keyof TData>) => void;
}

/**
 * Inertia's `useForm()` shape (loose typing — we don't import @inertiajs
 * statically since it's an optional peer when fancy-inertia is used
 * outside of Inertia for code-sharing reasons).
 */
type InertiaForm<T> = {
  data: T;
  setData: (key: keyof T, value: unknown) => void;
  errors: Partial<Record<keyof T, string>>;
  processing: boolean;
  submit: (method: string, url: string, options?: object) => void;
  post: (url: string, options?: object) => void;
  put: (url: string, options?: object) => void;
  patch: (url: string, options?: object) => void;
  delete: (url: string, options?: object) => void;
  reset: (...fields: Array<keyof T>) => void;
  clearErrors: (...fields: Array<keyof T>) => void;
};

/**
 * Wraps Inertia's `useForm()` so each field can be wired into react-fancy
 * inputs in one line:
 *
 *   const form = useFancyForm({ name: "", email: "" });
 *   <Input {...form.field("name")} placeholder="Name" />
 *   <Input {...form.field("email")} placeholder="Email" />
 *   <Action onClick={() => form.post("/users")}>Save</Action>
 *
 * Call signature mirrors `useForm()` from @inertiajs/react. Pass either
 * the initial values, or the result of `useForm(...)` if you've already
 * called it (lets you compose with library-supplied form objects):
 *
 *   const inertiaForm = useForm({ name: "" });
 *   const form = useFancyForm(inertiaForm);
 */
export function useFancyForm<TData extends Record<string, unknown>>(
  initialOrForm: TData | InertiaForm<TData>,
): FancyFormBridge<TData> {
  // Lazy-resolve @inertiajs/react. If the consumer has already called
  // useForm() and passed the result in, we re-use it directly. Otherwise
  // we instantiate via the package.
  const form = useMemo<InertiaForm<TData>>(() => {
    if (isInertiaForm<TData>(initialOrForm)) {
      return initialOrForm;
    }
    return useInertiaFormShim(initialOrForm) as InertiaForm<TData>;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialOrForm]);

  const field = useCallback(
    <K extends keyof TData & string>(name: K): FancyFieldBridge<TData[K]> => ({
      name,
      value: form.data[name],
      onChange: (e) => {
        const next =
          e !== null && typeof e === "object" && "target" in (e as object)
            ? ((e as React.ChangeEvent<HTMLInputElement>).target as HTMLInputElement & {
                checked?: boolean;
                type?: string;
              })
            : null;
        if (next) {
          const value = next.type === "checkbox" ? next.checked : next.value;
          form.setData(name, value as unknown as TData[K]);
        } else {
          form.setData(name, e as unknown as TData[K]);
        }
      },
      error: form.errors[name],
      loading: form.processing,
    }),
    [form],
  );

  return {
    data: form.data,
    setData: form.setData as FancyFormBridge<TData>["setData"],
    errors: form.errors,
    processing: form.processing,
    field,
    submit: form.submit,
    post: form.post,
    put: form.put,
    patch: form.patch,
    delete: form.delete,
    reset: form.reset,
    clearErrors: form.clearErrors,
  };
}

function isInertiaForm<T>(x: unknown): x is InertiaForm<T> {
  return (
    typeof x === "object" &&
    x !== null &&
    "data" in (x as object) &&
    "setData" in (x as object) &&
    "errors" in (x as object) &&
    "processing" in (x as object)
  );
}

function useInertiaFormShim<TData extends Record<string, unknown>>(initial: TData): InertiaForm<TData> {
  return inertiaUseForm(initial as any) as unknown as InertiaForm<TData>;
}

import { useCallback, useRef, useState } from "react";
import { runFlow, type RunOptions, type RunResult } from "./run-flow";
import type {
  ExecutorRegistry,
  FlowGraph,
  NodeRunStatus,
  RunEvent,
} from "../types";

export type FlowRunFeedEntry = {
  id: string;
  at: number;
  level: "info" | "warn" | "error" | "status";
  text: string;
  nodeId?: string;
  detail?: unknown;
};

export type UseFlowRunReturn = {
  /** Status keyed by nodeId — drive the UI overlay from this. */
  statuses: Record<string, NodeRunStatus>;
  /** Per-node status text (e.g. error message). */
  statusText: Record<string, string | undefined>;
  /** Live event log (capped to last N). */
  feed: FlowRunFeedEntry[];
  /** Whether a run is currently in progress. */
  running: boolean;
  /** Last run result, or null. */
  lastResult: RunResult | null;
  /** Kick off a run with the provided graph + executors. */
  run: (graph: FlowGraph, executors: ExecutorRegistry, options?: RunOptions) => Promise<RunResult>;
  /** Cancel the current run (if any). */
  cancel: () => void;
  /** Reset all runtime state (statuses, feed, lastResult). */
  reset: () => void;
};

export type UseFlowRunOptions = {
  /** Cap the in-memory feed to this many entries. Default 200. */
  maxFeed?: number;
};

/**
 * useFlowRun — drives `runFlow` + maintains observability state. Pair with
 * `applyStatusesToNodes` (below) before passing nodes to `<FlowCanvas>` so
 * the per-node status badge renders.
 */
export function useFlowRun({ maxFeed = 200 }: UseFlowRunOptions = {}): UseFlowRunReturn {
  const [statuses, setStatuses] = useState<Record<string, NodeRunStatus>>({});
  const [statusText, setStatusText] = useState<Record<string, string | undefined>>({});
  const [feed, setFeed] = useState<FlowRunFeedEntry[]>([]);
  const [running, setRunning] = useState(false);
  const [lastResult, setLastResult] = useState<RunResult | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const handleEvent = useCallback(
    (e: RunEvent) => {
      switch (e.type) {
        case "node-status":
          setStatuses((s) => ({ ...s, [e.nodeId]: e.status }));
          setStatusText((t) => ({ ...t, [e.nodeId]: e.text }));
          appendFeed({ level: "status", text: `${e.nodeId} → ${e.status}${e.text ? ` (${e.text})` : ""}`, nodeId: e.nodeId });
          break;
        case "node-output":
          appendFeed({ level: "info", text: `${e.nodeId}.${e.portId} = ${preview(e.value)}`, nodeId: e.nodeId, detail: e.value });
          break;
        case "log":
          appendFeed({ level: e.level, text: e.message, nodeId: e.nodeId, detail: e.detail });
          break;
        case "run-start":
          appendFeed({ level: "info", text: "▶ run started" });
          break;
        case "run-end":
          appendFeed({ level: e.ok ? "info" : "error", text: e.ok ? "✓ run complete" : "✗ run failed" });
          break;
        case "run-error":
          appendFeed({ level: "error", text: e.error });
          break;
      }
      function appendFeed(partial: Omit<FlowRunFeedEntry, "id" | "at">) {
        setFeed((f) => {
          const entry: FlowRunFeedEntry = { id: `${Date.now()}_${f.length}`, at: Date.now(), ...partial };
          const next = [...f, entry];
          return next.length > maxFeed ? next.slice(next.length - maxFeed) : next;
        });
      }
    },
    [maxFeed],
  );

  const run = useCallback(
    async (graph: FlowGraph, executors: ExecutorRegistry, options: RunOptions = {}) => {
      if (running) {
        return { ok: false, outputs: {}, error: "another run is already in progress" } satisfies RunResult;
      }
      const controller = new AbortController();
      abortRef.current = controller;
      // Reset previous statuses for the nodes we're about to run.
      const idleStatuses: Record<string, NodeRunStatus> = {};
      for (const n of graph.nodes) idleStatuses[n.id] = "idle";
      setStatuses(idleStatuses);
      setStatusText({});
      setRunning(true);
      try {
        const result = await runFlow(graph, executors, handleEvent, { ...options, signal: controller.signal });
        setLastResult(result);
        return result;
      } finally {
        setRunning(false);
        abortRef.current = null;
      }
    },
    [handleEvent, running],
  );

  const cancel = useCallback(() => abortRef.current?.abort(), []);

  const reset = useCallback(() => {
    setStatuses({});
    setStatusText({});
    setFeed([]);
    setLastResult(null);
  }, []);

  return { statuses, statusText, feed, running, lastResult, run, cancel, reset };
}

/** Merge runtime statuses into nodes for rendering. */
export function applyStatusesToNodes<TNode extends { id: string; data: any }>(
  nodes: TNode[],
  statuses: Record<string, NodeRunStatus>,
  statusText: Record<string, string | undefined>,
): TNode[] {
  return nodes.map((n) => ({
    ...n,
    data: {
      ...n.data,
      status: statuses[n.id] ?? n.data?.status ?? "idle",
      statusText: statusText[n.id] ?? n.data?.statusText,
    },
  }));
}

function preview(v: unknown): string {
  try {
    const s = JSON.stringify(v);
    return s && s.length > 60 ? s.slice(0, 57) + "…" : (s ?? String(v));
  } catch {
    return String(v);
  }
}

import { useCallback, useState } from "react";
import {
  addEdge,
  applyEdgeChanges,
  applyNodeChanges,
  type Connection,
  type Edge,
  type EdgeChange,
  type NodeChange,
} from "@xyflow/react";
import type { FlowEdge, FlowGraph, FlowNode } from "../types";

export type UseFlowStateReturn = {
  nodes: FlowNode[];
  edges: FlowEdge[];
  setNodes: React.Dispatch<React.SetStateAction<FlowNode[]>>;
  setEdges: React.Dispatch<React.SetStateAction<FlowEdge[]>>;
  onNodesChange: (changes: NodeChange[]) => void;
  onEdgesChange: (changes: EdgeChange[]) => void;
  onConnect: (connection: Connection) => void;
  /** Snapshot the current graph (suitable for serialization). */
  toGraph: () => FlowGraph;
};

/**
 * useFlowState — React Flow's standard controlled-state plumbing in one hook.
 * Spread into <FlowCanvas>.
 */
export function useFlowState(initial: FlowGraph): UseFlowStateReturn {
  const [nodes, setNodes] = useState<FlowNode[]>(initial.nodes);
  const [edges, setEdges] = useState<FlowEdge[]>(initial.edges);

  const onNodesChange = useCallback((changes: NodeChange[]) => {
    setNodes((ns) => applyNodeChanges(changes, ns) as FlowNode[]);
  }, []);
  const onEdgesChange = useCallback((changes: EdgeChange[]) => {
    setEdges((es) => applyEdgeChanges(changes, es));
  }, []);
  const onConnect = useCallback((connection: Connection) => {
    setEdges((es) => addEdge(connection, es) as Edge[]);
  }, []);

  const toGraph = useCallback(() => ({ nodes, edges }), [nodes, edges]);

  return { nodes, edges, setNodes, setEdges, onNodesChange, onEdgesChange, onConnect, toGraph };
}
